/* Việt Sử V5.8 — bài học SGK Lịch sử lớp 6, 7 (sinh bởi tools/build_v58.py, đừng sửa tay) */
window.VS58_SGK={"phien_ban":"5.8","lop":{"6":{"sach":"Lịch sử và Địa lí 6 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 7–94","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Lịch sử và cuộc sống","trang":[9,10],"nam":null,"tom":"Mọi sự vật, con người và xã hội đều thay đổi theo thời gian; sự thay đổi ấy chính là lịch sử. Học lịch sử giúp ta hiểu cội nguồn, rút kinh nghiệm từ quá khứ để sống tốt hơn hôm nay.","muc":[["1. Lịch sử là gì?",["Lịch sử là tất cả những gì đã diễn ra trong quá khứ, từ một chiếc máy tính, một ngôi làng đến cả xã hội loài người.","Lịch sử còn là một ngành khoa học: nghiên cứu, tìm hiểu và phục dựng lại quá khứ dựa trên các dấu vết còn lại.","Môn Lịch sử ở trường tìm hiểu quá trình hình thành và phát triển của xã hội loài người, từ khi con người xuất hiện đến ngày nay."]],["2. Vì sao phải học lịch sử?",["Để biết cội nguồn của bản thân, gia đình, quê hương, dân tộc và nhân loại.","Để hiểu vì sao hiện tại lại như ngày nay, từ đó đúc rút bài học kinh nghiệm cho cuộc sống.","Người xưa đã ghi chép, biên soạn sử sách để lưu giữ kí ức và truyền lại cho đời sau; học sử là tiếp nối truyền thống ấy."]]],"nho":["Lịch sử là những gì đã xảy ra trong quá khứ và là khoa học phục dựng quá khứ.","Môn Lịch sử nghiên cứu quá trình phát triển của xã hội loài người.","Học lịch sử để hiểu cội nguồn và rút bài học cho hiện tại."],"hoi":["Em hiểu lịch sử là gì? Cho một ví dụ về sự thay đổi theo thời gian ở nơi em sống.","Vì sao chúng ta cần học lịch sử?","Theo em, việc ghi chép lại lịch sử gia đình có ý nghĩa gì?"]},{"so":2,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Dựa vào đâu để biết và phục dựng lại lịch sử?","trang":[11,13],"nam":null,"tom":"Các nhà sử học dựng lại quá khứ nhờ những dấu vết người xưa để lại, gọi là tư liệu lịch sử. Có bốn loại cơ bản: tư liệu hiện vật, chữ viết, truyền miệng và tư liệu gốc.","muc":[["1. Tư liệu hiện vật",["Là những di tích, đồ vật của người xưa còn giữ lại trong lòng đất hay trên mặt đất: công cụ, đồ gốm, trống đồng, đền tháp, thành luỹ…","Hiện vật cho biết khá cụ thể và trung thực về đời sống vật chất, một phần đời sống tinh thần của người xưa."]],["2. Tư liệu chữ viết",["Là những bản ghi, sách vở, văn bia, sắc phong… được viết tay hoặc in, khắc bằng chữ.","Ví dụ: các bia Tiến sĩ ở Văn Miếu – Quốc Tử Giám ghi tên người đỗ đạt qua nhiều khoa thi.","Chữ viết giúp ta biết tương đối đầy đủ về đời sống con người, nhưng có thể mang dấu ấn chủ quan của người viết."]],["3. Tư liệu truyền miệng",["Là truyền thuyết, thần thoại, ca dao, câu chuyện được kể lại từ đời này sang đời khác (ví dụ: Sơn Tinh – Thuỷ Tinh, Thánh Gióng).","Cho biết nhiều điều về quá khứ và tâm tư của người xưa, nhưng cần đối chiếu với tư liệu khác để tìm ra sự thật."]],["4. Tư liệu gốc",["Là tư liệu liên quan trực tiếp đến sự kiện, ra đời ngay lúc sự kiện xảy ra hoặc do người trong cuộc để lại.","Đây là nguồn đáng tin cậy nhất khi tìm hiểu lịch sử."]]],"nho":["Tư liệu hiện vật: đồ vật, di tích của người xưa.","Tư liệu chữ viết: sách, văn bản, văn bia ghi lại sự kiện.","Tư liệu truyền miệng: truyện kể, truyền thuyết lưu truyền qua nhiều đời.","Tư liệu gốc ra đời cùng lúc với sự kiện, có giá trị tin cậy cao nhất."],"hoi":["Kể tên bốn loại tư liệu lịch sử và cho mỗi loại một ví dụ.","Vì sao bia Tiến sĩ ở Văn Miếu được coi là tư liệu chữ viết?","Ở nơi em sống có hiện vật nào giúp tìm hiểu quá khứ của quê hương?"]},{"so":3,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Thời gian trong lịch sử","trang":[14,15],"nam":null,"tom":"Muốn hiểu lịch sử phải biết sự kiện xảy ra khi nào. Bài học giới thiệu âm lịch, dương lịch, Công nguyên và cách tính, ghi các mốc thời gian.","muc":[["1. Vì sao phải xác định thời gian trong lịch sử?",["Các sự kiện nối tiếp nhau theo trình tự trước – sau; biết thời gian xảy ra mới sắp xếp và hiểu được mối liên hệ giữa chúng.","Người xưa quan sát Mặt Trăng, Mặt Trời để tính thời gian và làm ra lịch."]],["2. Cách tính thời gian",["Âm lịch: tính theo chu kì Mặt Trăng quay quanh Trái Đất. Dương lịch: tính theo chu kì Trái Đất quay quanh Mặt Trời.","Công lịch là lịch chung của thế giới hiện nay, lấy năm tương truyền Chúa Giê-xu ra đời làm năm 1 Công nguyên (CN); trước đó là trước Công nguyên (TCN).","Đơn vị thời gian: thập kỉ = 10 năm, thế kỉ = 100 năm, thiên niên kỉ = 1 000 năm.","Cách tính khoảng cách: năm TCN và năm CN nằm hai phía của năm 1; muốn biết một năm TCN cách năm hiện tại bao nhiêu năm thì cộng số năm TCN với số năm hiện tại (ví dụ 2000 TCN đến năm 2025 khoảng 4 025 năm)."]]],"nho":["Âm lịch theo Mặt Trăng, dương lịch theo Mặt Trời.","Công lịch lấy năm 1 CN làm mốc; trước đó là TCN.","Thập kỉ 10 năm, thế kỉ 100 năm, thiên niên kỉ 1 000 năm."],"hoi":["Âm lịch và dương lịch khác nhau thế nào?","Năm 208 TCN thuộc thế kỉ nào? Cách năm nay bao nhiêu năm?","Vì sao thế giới cần một thứ lịch chung?"]},{"so":4,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Nguồn gốc loài người","trang":[17,19],"nam":null,"tom":"Loài người có nguồn gốc từ một loài Vượn người sống cách ngày nay khoảng 5–6 triệu năm, trải qua Người tối cổ rồi đến Người tinh khôn. Dấu tích Người tối cổ đã được tìm thấy ở Đông Nam Á và Việt Nam.","muc":[["1. Quá trình tiến hoá từ Vượn người thành người",["Khoảng 5–6 triệu năm trước, ở Đông Phi có loài Vượn người sinh sống.","Khoảng 4 triệu năm trước, một nhánh tiến hoá thành Người tối cổ: đi đứng bằng hai chân, hai chi trước thành tay, biết ghè đẽo công cụ đá.","Khoảng 15 vạn năm trước, Người tối cổ biến đổi thành Người tinh khôn, có cấu tạo cơ thể giống người ngày nay."]],["2. Dấu tích của quá trình chuyển biến ở Đông Nam Á và Việt Nam",["Đông Nam Á là một trong những nơi có dấu tích sớm của loài người, nổi tiếng là hoá thạch Người tối cổ ở đảo Gia-va (In-đô-nê-xi-a).","Ở Việt Nam đã tìm thấy răng hoá thạch Người tối cổ ở Thẩm Khuyên, Thẩm Hai (Lạng Sơn).","Công cụ đá ghè đẽo thô sơ có ở An Khê (Gia Lai), Núi Đọ (Thanh Hoá), Xuân Lộc, An Lộc (Đồng Nai)… chứng tỏ Việt Nam là nơi con người sinh sống từ rất sớm."]]],"nho":["Vượn người (5–6 triệu năm) → Người tối cổ (khoảng 4 triệu năm) → Người tinh khôn (khoảng 15 vạn năm).","Người tối cổ đi bằng hai chân, biết chế tác công cụ đá.","Việt Nam có dấu tích Người tối cổ ở Lạng Sơn, Thanh Hoá, Gia Lai, Đồng Nai."],"hoi":["Trình bày các giai đoạn tiến hoá từ Vượn người thành người.","Những bằng chứng nào cho thấy Việt Nam có con người sinh sống từ rất sớm?","Người tinh khôn khác Người tối cổ ở những điểm nào?"]},{"so":5,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Xã hội nguyên thuỷ","trang":[20,23],"nam":null,"tom":"Xã hội nguyên thuỷ kéo dài hàng triệu năm, trải qua hai giai đoạn: bầy người nguyên thuỷ và công xã thị tộc. Lao động giúp con người và xã hội loài người ngày càng phát triển.","muc":[["1. Các giai đoạn phát triển của xã hội nguyên thuỷ",["Bầy người nguyên thuỷ (thời Người tối cổ): sống thành bầy vài chục người, công cụ thô sơ, dựa vào hái lượm, săn bắt.","Công xã thị tộc (thời Người tinh khôn): gồm những người cùng huyết thống, sống chung, làm chung, hưởng chung; nhiều thị tộc hợp thành bộ lạc."]],["2. Đời sống vật chất, tinh thần và tổ chức xã hội",["Vật chất: từ ghè đẽo đến mài đá, làm cung tên, đồ gốm; biết dùng lửa; từ hái lượm, săn bắt chuyển dần sang trồng trọt, chăn nuôi; sống trong hang động, mái đá rồi dựng lều.","Tinh thần: có tục chôn người chết kèm công cụ, biết làm đồ trang sức, vẽ trên vách hang – thể hiện tín ngưỡng và óc thẩm mĩ.","Ở Việt Nam, di chỉ văn hoá Hoà Bình, Bắc Sơn, Quỳnh Văn, Hạ Long… có nhiều công cụ đá mài, đồ gốm, dấu vết trồng trọt."]],["3. Vai trò của lao động",["Lao động làm đôi tay khéo léo, trí óc phát triển, con người dần hoàn thiện mình.","Nhờ lao động, con người cải thiện đời sống và tổ chức xã hội ngày càng chặt chẽ."]]],"nho":["Hai giai đoạn: bầy người nguyên thuỷ và công xã thị tộc.","Người nguyên thuỷ biết dùng lửa, mài đá, làm gốm, bước đầu trồng trọt, chăn nuôi.","Lao động đóng vai trò quyết định trong sự phát triển của con người."],"hoi":["Nêu đặc điểm của bầy người nguyên thuỷ và công xã thị tộc.","Đời sống tinh thần của người nguyên thuỷ có những biểu hiện nào?","Vì sao nói lao động giúp con người hoàn thiện chính mình?"]},{"so":6,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Sự chuyển biến và phân hoá của xã hội nguyên thuỷ","trang":[24,27],"nam":null,"tom":"Việc phát hiện kim loại làm năng suất lao động tăng, xuất hiện của cải dư thừa và sự phân hoá giàu nghèo, dẫn tới xã hội có giai cấp. Ở Việt Nam, quá trình này thể hiện qua các nền văn hoá Phùng Nguyên – Đồng Đậu – Gò Mun.","muc":[["1. Kim loại và bước tiến của xã hội",["Khoảng 3500 năm TCN, con người biết đúc đồng đỏ, sau đó là đồng thau; khoảng cuối thiên niên kỉ II TCN biết luyện sắt.","Công cụ kim loại giúp khai hoang, mở rộng trồng trọt, làm thêm nghề thủ công; sản phẩm làm ra nhiều hơn, có dư thừa.","Của cải dư thừa bị một số người chiếm làm riêng; xã hội phân hoá giàu – nghèo, gia đình phụ hệ thay cho thị tộc, xã hội có giai cấp ra đời."]],["2. Sự phân hoá không triệt để ở phương Đông",["Cư dân phương Đông sống ven sông lớn, cần làm thuỷ lợi chung nên quan hệ cộng đồng (công xã nông thôn) vẫn được giữ lại.","Vì vậy xã hội có phân hoá nhưng nhiều tàn dư của xã hội nguyên thuỷ còn tồn tại lâu dài."]],["3. Sự tan rã của xã hội nguyên thuỷ ở Việt Nam",["Từ khoảng 4 000 năm trước, cư dân ở Bắc Bộ, Trung Bộ và Nam Bộ đã biết đồ đồng.","Các nền văn hoá Phùng Nguyên – Đồng Đậu – Gò Mun cho thấy nghề luyện kim, trồng lúa nước, làm gốm phát triển; cư dân định cư ven các dòng sông lớn.","Mộ táng có sự chênh lệch đồ chôn theo, phản ánh sự phân hoá trong xã hội."]]],"nho":["Kim loại → năng suất tăng → của cải dư thừa → phân hoá giàu nghèo → xã hội có giai cấp.","Phương Đông phân hoá không triệt để do nhu cầu làm thuỷ lợi chung.","Ở Việt Nam: Phùng Nguyên – Đồng Đậu – Gò Mun."],"hoi":["Kim loại đã làm thay đổi đời sống con người như thế nào?","Vì sao xã hội nguyên thuỷ ở phương Đông phân hoá không triệt để?","Nêu một số nét chính về xã hội Việt Nam thời Phùng Nguyên – Đồng Đậu – Gò Mun."]},{"so":7,"chuong":"Chương 3. Xã hội cổ đại","ten":"Ai Cập và Lưỡng Hà cổ đại","trang":[29,33],"nam":-3200,"tom":"Nhờ phù sa sông Nin, sông Ơ-phrát và Ti-grơ, Ai Cập và Lưỡng Hà sớm hình thành nhà nước từ thiên niên kỉ IV TCN, để lại nhiều thành tựu văn hoá lớn cho nhân loại.","muc":[["1. Điều kiện tự nhiên",["Ai Cập nằm ở Đông Bắc châu Phi, dọc sông Nin; Lưỡng Hà nằm giữa hai con sông Ơ-phrát và Ti-grơ (Tây Á).","Đất phù sa màu mỡ, dễ canh tác; nước sông thuận cho tưới tiêu và đi lại, nhưng cũng gây lũ lụt nên phải làm thuỷ lợi."]],["2. Quá trình thành lập nhà nước",["Ai Cập: các công xã (Nôm) hợp nhất; khoảng năm 3200 TCN, vua Na-mơ (Menes) thống nhất, lập nhà nước; đứng đầu là Pha-ra-ông có quyền tối cao.","Lưỡng Hà: khoảng thiên niên kỉ IV TCN, người Xu-me lập nhiều thành bang; đứng đầu là En-xi; sau này có vương quốc Ba-bi-lon với bộ luật Ham-mu-ra-bi."]],["3. Những thành tựu văn hoá tiêu biểu",["Chữ viết: chữ tượng hình (Ai Cập), chữ hình nêm khắc trên đất sét (Lưỡng Hà).","Toán học: Ai Cập giỏi hình học, tính diện tích; Lưỡng Hà giỏi số học, đếm theo hệ 60.","Lịch và thiên văn: làm ra âm lịch; Ai Cập có lịch 365 ngày.","Kiến trúc: kim tự tháp, tượng Nhân sư (Ai Cập); vườn treo Ba-bi-lon (Lưỡng Hà).","Y học: kĩ thuật ướp xác của người Ai Cập."]]],"nho":["Ai Cập ven sông Nin; Lưỡng Hà giữa sông Ơ-phrát và Ti-grơ.","Nhà nước hình thành từ thiên niên kỉ IV TCN.","Thành tựu: chữ tượng hình, chữ hình nêm, toán học, lịch, kim tự tháp, vườn treo."],"hoi":["Các dòng sông đã ảnh hưởng thế nào đến sự hình thành văn minh Ai Cập và Lưỡng Hà?","Kể tên ba thành tựu văn hoá tiêu biểu của mỗi nền văn minh.","Theo em, thành tựu nào của người Ai Cập, Lưỡng Hà còn được sử dụng đến ngày nay?"]},{"so":8,"chuong":"Chương 3. Xã hội cổ đại","ten":"Ấn Độ cổ đại","trang":[34,38],"nam":-2500,"tom":"Ấn Độ cổ đại hình thành bên lưu vực sông Ấn và sông Hằng, có xã hội phân chia đẳng cấp sâu sắc (chế độ Vác-na) và nhiều thành tựu văn hoá ảnh hưởng rộng ra khu vực, trong đó có Đông Nam Á.","muc":[["1. Điều kiện tự nhiên",["Ấn Độ là một bán đảo ở Nam Á; phía bắc có dãy Hi-ma-lay-a, có hai con sông lớn là sông Ấn và sông Hằng bồi đắp đồng bằng màu mỡ.","Khí hậu có gió mùa; miền nam là cao nguyên Đê-can khô hạn."]],["2. Xã hội Ấn Độ cổ đại",["Khoảng giữa thiên niên kỉ III TCN, người bản địa Đra-vi-đa xây dựng các thành thị ở lưu vực sông Ấn.","Khoảng giữa thiên niên kỉ II TCN, người A-ri-a từ Trung Á tràn vào, lập ra các vương quốc.","Chế độ đẳng cấp Vác-na chia xã hội thành bốn đẳng cấp: Bra-man (tăng lữ), Ksa-tri-a (quý tộc, chiến binh), Vai-si-a (nông dân, thương nhân, thợ thủ công), Su-đra (người lao động nghèo); quy định khắt khe về hôn nhân, nghề nghiệp."]],["3. Những thành tựu văn hoá tiêu biểu",["Tôn giáo: nơi ra đời của đạo Bà La Môn (sau là Hin-đu) và Phật giáo.","Chữ viết: chữ Phạn; văn học với các sử thi Ma-ha-bha-ra-ta, Ra-ma-y-a-na.","Toán học: sáng tạo hệ chữ số, trong đó có số 0.","Kiến trúc: tháp Phật, chùa hang, cột đá A-sô-ca."]]],"nho":["Văn minh Ấn Độ gắn với sông Ấn, sông Hằng.","Chế độ Vác-na với bốn đẳng cấp.","Thành tựu: Phật giáo, Hin-đu giáo, chữ Phạn, sử thi, chữ số và số 0."],"hoi":["Trình bày chế độ đẳng cấp Vác-na của Ấn Độ cổ đại.","Nêu các thành tựu văn hoá tiêu biểu của Ấn Độ cổ đại.","Thành tựu nào của Ấn Độ cổ đại có ảnh hưởng đến Việt Nam?"]},{"so":9,"chuong":"Chương 3. Xã hội cổ đại","ten":"Trung Quốc cổ đại","trang":[39,43],"nam":-221,"tom":"Văn minh Trung Quốc hình thành ở lưu vực Hoàng Hà và Trường Giang. Năm 221 TCN, Tần Thuỷ Hoàng thống nhất Trung Quốc; các triều đại tiếp theo để lại nhiều thành tựu lớn.","muc":[["1. Điều kiện tự nhiên",["Hoàng Hà và Trường Giang bồi đắp những đồng bằng rộng lớn, màu mỡ, thuận lợi cho trồng trọt.","Lũ lụt thường xuyên khiến cư dân phải đắp đê, làm thuỷ lợi."]],["2. Quá trình thống nhất và xác lập chế độ phong kiến",["Từ thời Hạ, Thương, Chu, rồi đến thời Xuân Thu – Chiến Quốc với nhiều nước nhỏ đánh chiếm lẫn nhau.","Năm 221 TCN, nhà Tần thống nhất Trung Quốc; Tần Thuỷ Hoàng thống nhất đo lường, tiền tệ, chữ viết, xây dựng chế độ quân chủ chuyên chế.","Xã hội hình thành hai giai cấp chính: địa chủ và nông dân lĩnh canh; chế độ phong kiến được xác lập."]],["3. Từ đế chế Hán đến Tuỳ",["Nhà Hán (206 TCN – 220) mở rộng lãnh thổ, kinh tế phát triển.","Sau đó là thời kì chia cắt Tam quốc, Tấn, Nam – Bắc triều; năm 589 nhà Tuỳ thống nhất lại đất nước."]],["4. Những thành tựu văn hoá tiêu biểu",["Tư tưởng: Nho giáo (Khổng Tử), Đạo giáo (Lão Tử).","Chữ viết: từ chữ giáp cốt đến chữ Hán; sử học có Sử kí của Tư Mã Thiên.","Kĩ thuật: giấy, la bàn, thuốc súng, kĩ thuật in.","Công trình: Vạn Lí Trường Thành."]]],"nho":["Văn minh Trung Quốc gắn với Hoàng Hà, Trường Giang.","221 TCN: nhà Tần thống nhất Trung Quốc.","Thành tựu: Nho giáo, chữ Hán, Sử kí, giấy, la bàn, thuốc súng, Vạn Lí Trường Thành."],"hoi":["Tần Thuỷ Hoàng đã làm gì để củng cố sự thống nhất Trung Quốc?","Xã hội Trung Quốc thời phong kiến có những giai cấp nào?","Kể tên bốn phát minh kĩ thuật nổi tiếng của người Trung Quốc."]},{"so":10,"chuong":"Chương 3. Xã hội cổ đại","ten":"Hy Lạp và La Mã cổ đại","trang":[44,49],"nam":null,"tom":"Hy Lạp và La Mã hình thành bên bờ Địa Trung Hải, phát triển mạnh thương nghiệp, hàng hải và để lại tổ chức nhà nước dân chủ chủ nô, đế chế cùng nhiều thành tựu văn hoá rực rỡ.","muc":[["1. Điều kiện tự nhiên",["Hy Lạp gồm bán đảo Ban-căng, nhiều đảo nhỏ; La Mã ở bán đảo I-ta-li-a.","Đất ít, khô cứng, khó trồng lúa; bù lại có bờ biển khúc khuỷu, nhiều vịnh, nhiều khoáng sản → phát triển thủ công nghiệp, thương nghiệp đường biển."]],["2. Tổ chức nhà nước",["Hy Lạp gồm nhiều thành bang độc lập; tiêu biểu là A-ten với nhà nước dân chủ chủ nô: Đại hội nhân dân, Hội đồng 500 người… nhưng phụ nữ, kiều dân và nô lệ không có quyền công dân.","La Mã từ cộng hoà chuyển sang đế chế; quyền lực tập trung trong tay hoàng đế, lãnh thổ bao quanh Địa Trung Hải.","Nô lệ là lực lượng lao động chính trong xã hội."]],["3. Những thành tựu văn hoá tiêu biểu",["Chữ viết: hệ chữ cái La-tinh, chữ số La Mã.","Khoa học: các nhà toán học như Py-ta-go, Ta-lét, Ác-si-mét…","Văn học, sử học: sử thi I-li-át, Ô-đi-xê của Hô-me.","Kiến trúc, điêu khắc: đền Pác-tê-nông, đấu trường Cô-li-dê, tượng thần Vệ nữ Mi-lô.","Lịch: người La Mã làm ra dương lịch, nền tảng của lịch dùng ngày nay."]]],"nho":["Biển là điều kiện thuận lợi để Hy Lạp, La Mã phát triển thương nghiệp.","A-ten: dân chủ chủ nô; La Mã: từ cộng hoà đến đế chế.","Thành tựu: chữ cái La-tinh, toán học, sử thi, đền Pác-tê-nông, đấu trường Cô-li-dê, dương lịch."],"hoi":["Điều kiện tự nhiên ảnh hưởng thế nào đến kinh tế Hy Lạp, La Mã?","Nhà nước dân chủ chủ nô ở A-ten được tổ chức như thế nào? Có hạn chế gì?","Thành tựu nào của Hy Lạp, La Mã vẫn được dùng ngày nay?"]},{"so":11,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Các quốc gia sơ kì ở Đông Nam Á","trang":[51,53],"nam":null,"tom":"Từ những thế kỉ trước và sau Công nguyên, trên cơ sở kinh tế nông nghiệp lúa nước, buôn bán và tiếp thu văn hoá bên ngoài, ở Đông Nam Á lần lượt ra đời các quốc gia sơ kì.","muc":[["1. Điều kiện hình thành",["Đông Nam Á có khí hậu gió mùa, nhiều sông lớn, đồng bằng màu mỡ, thuận lợi trồng lúa nước.","Nằm trên đường giao thương giữa Ấn Độ và Trung Quốc nên sớm có buôn bán, tiếp xúc văn hoá.","Kĩ thuật luyện kim (đồng, sắt) phát triển, xã hội phân hoá."]],["2. Sự xuất hiện các quốc gia sơ kì",["Khoảng thế kỉ VII TCN – thế kỉ VII, xuất hiện nhiều quốc gia sơ kì: Văn Lang – Âu Lạc, Chăm-pa, Phù Nam (trên lãnh thổ Việt Nam), các quốc gia ở hạ lưu sông Chao Phray-a, trên các đảo Gia-va, Xu-ma-tơ-ra…","Các quốc gia này còn nhỏ, chưa có sự thống nhất lớn; kinh tế dựa vào nông nghiệp và thương mại đường biển."]]],"nho":["Cơ sở: lúa nước, luyện kim, giao thương biển.","Các quốc gia sơ kì tiêu biểu: Văn Lang – Âu Lạc, Chăm-pa, Phù Nam."],"hoi":["Những điều kiện nào dẫn tới sự ra đời các quốc gia sơ kì ở Đông Nam Á?","Kể tên một số quốc gia sơ kì ở Đông Nam Á và ở Việt Nam."]},{"so":12,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Sự hình thành và bước đầu phát triển của các vương quốc phong kiến ở Đông Nam Á (từ thế kỉ VII đến thế kỉ X)","trang":[54,55],"nam":null,"tom":"Từ thế kỉ VII đến thế kỉ X, ở Đông Nam Á hình thành các vương quốc phong kiến, nổi bật là Sri Vi-giay-a ở hải đảo; kinh tế thương mại biển phát triển mạnh.","muc":[["1. Sự hình thành các vương quốc phong kiến",["Các vương quốc thường lấy một tộc người đông và phát triển nhất làm nòng cốt: Chân Lạp của người Khơ-me (thay thế Phù Nam), Sri Kse-tra của người Pyu, Đva-ra-va-ti của người Môn (lưu vực sông Chao Phray-a), Sri Vi-giay-a ở đảo Xu-ma-tơ-ra…","Sri Vi-giay-a nằm ở vùng eo biển Ma-lắc-ca, trở thành cường quốc thương mại biển."]],["2. Sự phát triển kinh tế",["Kinh tế nông nghiệp trồng lúa vẫn giữ vai trò chính ở vùng lục địa.","Thương mại biển phát triển; nhiều thương cảng sầm uất, buôn bán với Ấn Độ, Trung Quốc, A-rập."]]],"nho":["Thế kỉ VII – X: các vương quốc phong kiến hình thành ở Đông Nam Á.","Sri Vi-giay-a là cường quốc thương mại biển."],"hoi":["Kể tên các vương quốc phong kiến ở Đông Nam Á từ thế kỉ VII đến thế kỉ X.","Vì sao thương mại biển ở Đông Nam Á phát triển mạnh?"]},{"so":13,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Giao lưu văn hoá ở Đông Nam Á từ đầu Công nguyên đến thế kỉ X","trang":[56,58],"nam":null,"tom":"Qua buôn bán và truyền giáo, cư dân Đông Nam Á tiếp thu văn hoá Ấn Độ, Trung Quốc một cách chọn lọc, kết hợp với văn hoá bản địa để tạo nên bản sắc riêng.","muc":[["1. Tiếp thu văn hoá Ấn Độ",["Tôn giáo: Phật giáo, Hin-đu giáo theo các thương nhân, tăng lữ vào Đông Nam Á.","Chữ viết: nhiều dân tộc dựa vào chữ Phạn để sáng tạo chữ viết riêng.","Văn học, kiến trúc: sử thi Ra-ma-y-a-na lan rộng; đền tháp mang phong cách Ấn Độ."]],["2. Tiếp thu văn hoá Trung Quốc",["Ảnh hưởng rõ nhất ở Việt Nam: chữ Hán, Nho giáo, Đạo giáo, cách tổ chức nhà nước.","Cư dân Đông Nam Á tiếp thu có chọn lọc, giữ những yếu tố phù hợp và giữ gìn văn hoá bản địa."]]],"nho":["Đông Nam Á tiếp thu văn hoá Ấn Độ và Trung Quốc qua buôn bán, truyền giáo.","Tiếp thu có chọn lọc, kết hợp với văn hoá bản địa."],"hoi":["Văn hoá Ấn Độ ảnh hưởng đến Đông Nam Á ở những lĩnh vực nào?","Vì sao nói cư dân Đông Nam Á tiếp thu văn hoá bên ngoài có chọn lọc?"]},{"so":14,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Nhà nước Văn Lang, Âu Lạc","trang":[60,64],"nam":-208,"tom":"Khoảng thế kỉ VII TCN, nhà nước Văn Lang ra đời ở lưu vực sông Hồng, sông Mã, sông Cả. Khoảng năm 208 TCN, Thục Phán lập nước Âu Lạc, đóng đô ở Cổ Loa.","muc":[["1. Sự ra đời nhà nước Văn Lang",["Cư dân Việt cổ định cư ven các dòng sông lớn, làm nông nghiệp lúa nước, cần trị thuỷ và chống ngoại xâm, nên các bộ lạc liên kết lại.","Khoảng thế kỉ VII TCN, thủ lĩnh bộ lạc Văn Lang hợp nhất các bộ lạc, xưng Hùng Vương, đóng đô ở Phong Châu (Phú Thọ ngày nay), đặt tên nước là Văn Lang.","Tổ chức nhà nước còn đơn giản: Hùng Vương – Lạc hầu, Lạc tướng – Bồ chính ở các chiềng, chạ."]],["2. Nhà nước Âu Lạc",["Cuối thế kỉ III TCN, người Âu Việt và Lạc Việt cùng kháng chiến chống quân Tần.","Khoảng năm 208 TCN, Thục Phán lên ngôi, hiệu An Dương Vương, lập nước Âu Lạc, xây thành Cổ Loa; quân đội mạnh, có nỏ bắn nhiều phát.","Năm 179 TCN, Triệu Đà đánh chiếm Âu Lạc; nước ta rơi vào thời kì Bắc thuộc."]],["3. Đời sống của cư dân Văn Lang, Âu Lạc",["Vật chất: trồng lúa nước, chăn nuôi, đánh cá; đúc đồng (trống đồng Đông Sơn), làm gốm; ở nhà sàn, ăn cơm, rau, cá; nam đóng khố, nữ mặc váy.","Tinh thần: thờ cúng tổ tiên, thờ thần tự nhiên; có tục nhuộm răng, ăn trầu, xăm mình; lễ hội đua thuyền, giã gạo."]]],"nho":["Thế kỉ VII TCN: nhà nước Văn Lang, kinh đô Phong Châu.","Khoảng 208 TCN: An Dương Vương lập Âu Lạc, xây thành Cổ Loa.","Trống đồng Đông Sơn tiêu biểu cho văn minh Văn Lang – Âu Lạc."],"hoi":["Vì sao nhà nước Văn Lang ra đời?","Thành Cổ Loa và nỏ thần cho thấy điều gì về nhà nước Âu Lạc?","Những phong tục nào của cư dân Văn Lang, Âu Lạc còn được giữ đến ngày nay?"]},{"so":15,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Chính sách cai trị của các triều đại phong kiến phương Bắc và sự chuyển biến của xã hội Âu Lạc","trang":[65,69],"nam":null,"tom":"Hơn một nghìn năm Bắc thuộc, các triều đại phương Bắc chia nước ta thành quận huyện, bóc lột nặng nề và tìm cách đồng hoá. Dù vậy, kinh tế, xã hội Âu Lạc vẫn có những chuyển biến.","muc":[["1. Chính sách cai trị",["Chính trị: chia Âu Lạc thành các quận, huyện, sáp nhập vào lãnh thổ phương Bắc; đặt quan lại cai trị đến cấp huyện.","Kinh tế: bắt nộp tô thuế nặng, cống nạp sản vật quý; nắm độc quyền muối, sắt.","Văn hoá: truyền bá chữ Hán, Nho giáo, bắt theo phong tục người Hán nhằm đồng hoá dân ta."]],["2. Chuyển biến về kinh tế",["Nông nghiệp: dùng cày sắt, trâu bò kéo; làm thuỷ lợi, trồng lúa hai vụ.","Thủ công: rèn sắt, làm gốm, dệt vải phát triển; một số nghề mới như làm giấy, thuỷ tinh.","Thương mại: một số trung tâm buôn bán như Luy Lâu."]],["3. Chuyển biến về xã hội",["Xã hội phân hoá sâu sắc; quan lại đô hộ, địa chủ người Hán và hào trưởng người Việt.","Nông dân bị bóc lột nặng nề, mâu thuẫn với chính quyền đô hộ ngày càng gay gắt."]]],"nho":["Bắc thuộc: chia quận huyện, bóc lột nặng, đồng hoá văn hoá.","Kinh tế vẫn phát triển: cày sắt, trâu bò, nghề thủ công mới.","Mâu thuẫn dân tộc gay gắt dẫn tới các cuộc khởi nghĩa."],"hoi":["Nêu những chính sách cai trị của phong kiến phương Bắc về chính trị, kinh tế, văn hoá.","Kinh tế Âu Lạc thời Bắc thuộc có những chuyển biến gì?","Vì sao các cuộc khởi nghĩa liên tục nổ ra trong thời Bắc thuộc?"]},{"so":16,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Các cuộc khởi nghĩa tiêu biểu giành độc lập trước thế kỉ X","trang":[70,77],"nam":40,"tom":"Trong hơn một nghìn năm Bắc thuộc, người Việt liên tục vùng lên. Tiêu biểu là các cuộc khởi nghĩa Hai Bà Trưng, Bà Triệu, Lý Bí, Mai Thúc Loan, Phùng Hưng.","muc":[["1. Khởi nghĩa Hai Bà Trưng (năm 40)",["Nguyên nhân: căm thù ách đô hộ của nhà Hán, Thái thú Tô Định tham lam, tàn bạo.","Mùa xuân năm 40, Trưng Trắc, Trưng Nhị dựng cờ ở Hát Môn, nghĩa quân chiếm Mê Linh, Cổ Loa, Luy Lâu; Trưng Trắc lên ngôi vua.","Năm 42–43, nhà Hán đem quân sang đàn áp; cuộc khởi nghĩa thất bại nhưng khẳng định ý chí độc lập."]],["2. Khởi nghĩa Bà Triệu (năm 248)",["Bà Triệu (Triệu Thị Trinh) cùng anh khởi nghĩa ở núi Nưa (Thanh Hoá) chống ách đô hộ của nhà Ngô.","Cuộc khởi nghĩa làm rung động chính quyền đô hộ, sau đó bị đàn áp."]],["3. Khởi nghĩa Lý Bí và nước Vạn Xuân (542–602)",["Năm 542, Lý Bí khởi nghĩa chống nhà Lương, chiếm thành Long Biên.","Năm 544, Lý Bí lên ngôi, xưng Lý Nam Đế, đặt tên nước là Vạn Xuân.","Triệu Quang Phục tiếp tục kháng chiến ở đầm Dạ Trạch; nước Vạn Xuân tồn tại đến năm 602."]],["4. Khởi nghĩa Mai Thúc Loan và Phùng Hưng",["Đầu thế kỉ VIII, Mai Thúc Loan khởi nghĩa ở Hoan Châu, xưng hoàng đế (Mai Hắc Đế), xây thành Vạn An.","Khoảng năm 776, Phùng Hưng khởi nghĩa ở Đường Lâm, chiếm phủ thành Tống Bình; nhân dân tôn ông là Bố Cái Đại Vương."]]],"nho":["Năm 40: Hai Bà Trưng; năm 248: Bà Triệu; năm 542: Lý Bí, năm 544 lập nước Vạn Xuân.","Thế kỉ VIII: Mai Thúc Loan, Phùng Hưng.","Các cuộc khởi nghĩa thể hiện ý chí độc lập bền bỉ của dân tộc."],"hoi":["Trình bày nguyên nhân, diễn biến chính và ý nghĩa của khởi nghĩa Hai Bà Trưng.","Việc Lý Bí đặt tên nước là Vạn Xuân có ý nghĩa gì?","Lập bảng các cuộc khởi nghĩa tiêu biểu: thời gian, người lãnh đạo, kết quả."]},{"so":17,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Cuộc đấu tranh bảo tồn và phát triển văn hoá dân tộc của người Việt","trang":[78,79],"nam":null,"tom":"Dù bị đô hộ lâu dài, người Việt vẫn giữ được tiếng nói, phong tục, tín ngưỡng của mình, đồng thời tiếp thu chọn lọc văn hoá Trung Hoa để làm giàu văn hoá dân tộc.","muc":[["1. Giữ gìn văn hoá truyền thống",["Người Việt vẫn nói tiếng Việt; giữ tục thờ cúng tổ tiên, thờ các anh hùng, thờ thần tự nhiên.","Phong tục nhuộm răng đen, ăn trầu, làm bánh chưng, bánh giầy được duy trì trong làng xã.","Làng xã là nơi lưu giữ và bảo vệ văn hoá dân tộc."]],["2. Tiếp thu có chọn lọc văn hoá Trung Hoa",["Học chữ Hán nhưng đọc theo cách đọc của người Việt.","Tiếp thu Nho giáo, Phật giáo, Đạo giáo một cách phù hợp, kết hợp với tín ngưỡng dân gian.","Học kĩ thuật làm giấy, làm thuỷ tinh… để phát triển kinh tế."]]],"nho":["Người Việt giữ được tiếng nói và phong tục truyền thống.","Tiếp thu văn hoá Trung Hoa có chọn lọc, không bị đồng hoá."],"hoi":["Những phong tục nào của người Việt vẫn được giữ gìn trong thời Bắc thuộc?","Vì sao người Việt không bị đồng hoá sau hơn một nghìn năm Bắc thuộc?"]},{"so":18,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Bước ngoặt lịch sử đầu thế kỉ X","trang":[80,85],"nam":938,"tom":"Đầu thế kỉ X, họ Khúc giành quyền tự chủ; Dương Đình Nghệ đánh bại quân Nam Hán lần thứ nhất. Năm 938, Ngô Quyền lãnh đạo chiến thắng Bạch Đằng, chấm dứt hơn một nghìn năm Bắc thuộc.","muc":[["1. Họ Khúc dựng quyền tự chủ",["Năm 905, nhân nhà Đường suy yếu, Khúc Thừa Dụ chiếm thành Đại La, tự xưng Tiết độ sứ, dựng quyền tự chủ.","Khúc Hạo tiến hành nhiều cải cách: định lại thuế, đặt lại các đơn vị hành chính, chăm lo đời sống nhân dân."]],["2. Dương Đình Nghệ chống quân Nam Hán",["Năm 930, quân Nam Hán chiếm nước ta. Năm 931, Dương Đình Nghệ đem quân từ Ái Châu đánh tan quân Nam Hán, giữ vững quyền tự chủ.","Năm 937, Dương Đình Nghệ bị Kiều Công Tiễn giết hại; Kiều Công Tiễn cầu cứu nhà Nam Hán."]],["3. Ngô Quyền và chiến thắng Bạch Đằng năm 938",["Ngô Quyền tiến quân ra Bắc, giết Kiều Công Tiễn, chuẩn bị đánh quân Nam Hán.","Ông cho đóng cọc gỗ đầu bịt sắt ở cửa sông Bạch Đằng, lợi dụng thuỷ triều nhử địch vào trận địa cọc.","Khi nước triều rút, quân ta đánh mạnh; thuyền giặc va vào cọc, đắm vỡ; Lưu Hoằng Tháo tử trận.","Ý nghĩa: chấm dứt hơn một nghìn năm Bắc thuộc, mở ra thời kì độc lập lâu dài của dân tộc."]]],"nho":["905: Khúc Thừa Dụ dựng quyền tự chủ.","931: Dương Đình Nghệ đánh đuổi quân Nam Hán.","938: Ngô Quyền chiến thắng Bạch Đằng, kết thúc thời Bắc thuộc."],"hoi":["Vì sao nói họ Khúc đặt nền móng cho nền độc lập?","Trình bày kế hoạch đánh giặc độc đáo của Ngô Quyền trên sông Bạch Đằng.","Chiến thắng Bạch Đằng năm 938 có ý nghĩa như thế nào?"]},{"so":19,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Vương quốc Chăm-pa từ thế kỉ II đến thế kỉ X","trang":[86,90],"nam":192,"tom":"Cuối thế kỉ II, Khu Liên lập nước Lâm Ấp ở vùng Tượng Lâm, về sau gọi là Chăm-pa. Vương quốc này có nền kinh tế biển phát triển và văn hoá đặc sắc với những đền tháp Chăm.","muc":[["1. Sự thành lập và phát triển",["Năm 192, nhân dân huyện Tượng Lâm dưới sự lãnh đạo của Khu Liên nổi dậy, lập nước Lâm Ấp; đến thế kỉ VI đổi tên là Chăm-pa.","Lãnh thổ trải dài ven biển miền Trung Việt Nam ngày nay; các kinh đô như Sin-ha-pu-ra (Trà Kiệu), In-đra-pu-ra (Đồng Dương)."]],["2. Kinh tế và xã hội",["Trồng lúa nước, làm ruộng bậc thang; khai thác lâm sản quý như trầm hương.","Đánh cá, buôn bán đường biển phát triển; nhiều thương cảng sầm uất.","Xã hội gồm vua, quý tộc, nông dân tự do và nô lệ."]],["3. Văn hoá",["Sáng tạo chữ viết riêng dựa trên chữ Phạn.","Theo Hin-đu giáo và Phật giáo; xây dựng nhiều đền tháp, tiêu biểu là khu đền tháp Mỹ Sơn (Quảng Nam).","Nghệ thuật điêu khắc tinh xảo; tục hoả táng người chết."]]],"nho":["192: Khu Liên lập nước Lâm Ấp, sau là Chăm-pa.","Kinh tế lúa nước, buôn bán biển; văn hoá chịu ảnh hưởng Ấn Độ.","Khu đền tháp Mỹ Sơn tiêu biểu cho văn hoá Chăm-pa."],"hoi":["Trình bày sự ra đời của vương quốc Chăm-pa.","Nêu những nét chính về kinh tế, văn hoá Chăm-pa.","Ngày nay còn những di sản nào của văn hoá Chăm-pa?"]},{"so":20,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Vương quốc Phù Nam","trang":[91,94],"nam":null,"tom":"Khoảng thế kỉ I, vương quốc Phù Nam hình thành ở vùng châu thổ sông Cửu Long, phát triển mạnh nhờ thương mại biển với trung tâm là thương cảng Óc Eo, đến thế kỉ VII thì suy yếu.","muc":[["1. Sự thành lập, phát triển và suy vong",["Khoảng thế kỉ I, Phù Nam ra đời ở vùng đồng bằng châu thổ sông Cửu Long.","Thế kỉ III – V là thời kì phát triển mạnh, mở rộng ảnh hưởng ra nhiều vùng xung quanh.","Cuối thế kỉ VI, Phù Nam suy yếu và bị Chân Lạp thôn tính vào thế kỉ VII."]],["2. Kinh tế, xã hội và văn hoá",["Trồng lúa nước, làm thủ công (gốm, kim hoàn), buôn bán đường biển rất phát triển.","Thương cảng Óc Eo (An Giang) là nơi buôn bán với Ấn Độ, Trung Quốc, Địa Trung Hải.","Cư dân ở nhà sàn, theo Hin-đu giáo và Phật giáo; văn hoá Óc Eo để lại nhiều di vật quý."]]],"nho":["Phù Nam hình thành khoảng thế kỉ I ở châu thổ sông Cửu Long.","Óc Eo là thương cảng quốc tế quan trọng.","Thế kỉ VII, Phù Nam bị Chân Lạp thôn tính."],"hoi":["Trình bày sự hình thành và phát triển của vương quốc Phù Nam.","Vì sao thương cảng Óc Eo trở thành trung tâm buôn bán quan trọng?","Kể tên một số di vật của văn hoá Óc Eo mà em biết."]}]},"7":{"sach":"Lịch sử và Địa lí 7 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 7–94 và hai chủ đề chung tr. 166–174","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Quá trình hình thành và phát triển của chế độ phong kiến ở Tây Âu","trang":[9,13],"nam":null,"tom":"Sau khi Đế quốc Tây La Mã sụp đổ (năm 476), các vương quốc của người Giéc-man hình thành, chế độ phong kiến Tây Âu ra đời với các lãnh địa, rồi thành thị trung đại xuất hiện, kinh tế hàng hoá phát triển.","muc":[["1. Sự hình thành chế độ phong kiến ở Tây Âu",["Cuối thế kỉ V, người Giéc-man tràn vào, Đế quốc Tây La Mã diệt vong (476); nhiều vương quốc mới được lập ra.","Người Giéc-man chiếm ruộng đất của chủ nô cũ, phong tước vị cho nhau; hình thành hai giai cấp lãnh chúa và nông nô."]],["2. Lãnh địa phong kiến và quan hệ trong xã hội",["Lãnh địa là vùng đất do lãnh chúa làm chủ, có lâu đài, nhà thờ, ruộng đất, như một vương quốc thu nhỏ, tự cấp tự túc.","Nông nô nhận ruộng canh tác, nộp tô thuế và chịu nhiều nghĩa vụ; lãnh chúa sống sung sướng nhờ bóc lột nông nô."]],["3. Thành thị trung đại và Thiên Chúa giáo",["Từ thế kỉ XI, sản xuất phát triển, thợ thủ công và thương nhân tụ tập ở nơi đông người, lập ra thành thị.","Thành thị thúc đẩy kinh tế hàng hoá, phá vỡ tính tự cấp tự túc của lãnh địa; tầng lớp thị dân ra đời.","Thiên Chúa giáo có vai trò lớn trong đời sống tinh thần và chính trị; Giáo hội là thế lực phong kiến lớn."]]],"nho":["476: Tây La Mã diệt vong; chế độ phong kiến Tây Âu hình thành.","Lãnh chúa và nông nô là hai giai cấp chính; lãnh địa là đơn vị kinh tế tự cấp tự túc.","Thành thị trung đại thúc đẩy kinh tế hàng hoá."],"hoi":["Chế độ phong kiến Tây Âu hình thành như thế nào?","Mô tả đời sống trong một lãnh địa phong kiến.","Thành thị trung đại có vai trò gì đối với xã hội Tây Âu?"]},{"so":2,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Các cuộc phát kiến địa lí và sự hình thành quan hệ sản xuất tư bản chủ nghĩa ở Tây Âu","trang":[14,17],"nam":1492,"tom":"Cuối thế kỉ XV – đầu thế kỉ XVI, những chuyến đi biển lớn tìm ra đường sang phương Đông, châu Mỹ và vòng quanh Trái Đất, đem lại nguồn vốn và thị trường cho quan hệ sản xuất tư bản chủ nghĩa ở Tây Âu.","muc":[["1. Các cuộc phát kiến địa lí",["Nguyên nhân: nhu cầu vàng bạc, hương liệu, thị trường; con đường buôn bán qua Tây Á bị chặn; kĩ thuật hàng hải tiến bộ (la bàn, tàu ca-ra-ven, hiểu biết về địa lí).","B. Đi-a-xơ vòng qua cực nam châu Phi (1487); C. Cô-lôm-bô đến châu Mỹ (1492); Va-xcô đơ Ga-ma đến Ấn Độ bằng đường biển (1497–1498); Ph. Ma-gien-lan thực hiện chuyến đi vòng quanh Trái Đất (1519–1522).","Hệ quả: mở ra những con đường mới, đem về nhiều vàng bạc, nguyên liệu, mở rộng thị trường; nhưng cũng mở đầu quá trình xâm chiếm thuộc địa, buôn bán nô lệ."]],["2. Sự hình thành quan hệ sản xuất tư bản chủ nghĩa",["Quý tộc, thương nhân tích luỹ vốn bằng cướp bóc thuộc địa, buôn bán; đuổi nông dân khỏi ruộng đất để có nhân công.","Xuất hiện công trường thủ công, công ti thương mại, đồn điền.","Xã hội hình thành hai giai cấp mới: tư sản (chủ xưởng, chủ đồn điền) và vô sản (người làm thuê)."]]],"nho":["1487 Đi-a-xơ; 1492 Cô-lôm-bô; 1497–1498 Va-xcô đơ Ga-ma; 1519–1522 Ma-gien-lan.","Phát kiến địa lí đem lại vốn, thị trường nhưng mở đầu thời kì xâm chiếm thuộc địa.","Giai cấp tư sản và vô sản hình thành."],"hoi":["Vì sao người châu Âu tiến hành các cuộc phát kiến địa lí?","Trình bày hệ quả tích cực và tiêu cực của các cuộc phát kiến địa lí.","Quan hệ sản xuất tư bản chủ nghĩa hình thành ở Tây Âu như thế nào?"]},{"so":3,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Phong trào Văn hoá Phục hưng và Cải cách tôn giáo","trang":[18,22],"nam":1517,"tom":"Từ thế kỉ XIV ở I-ta-li-a, phong trào Văn hoá Phục hưng đề cao con người và khoa học; đầu thế kỉ XVI, phong trào Cải cách tôn giáo bùng nổ, đòi xoá bỏ những lạc hậu của Giáo hội Thiên Chúa.","muc":[["1. Phong trào Văn hoá Phục hưng",["Bắt đầu ở I-ta-li-a (thế kỉ XIV), lan ra nhiều nước Tây Âu; giai cấp tư sản muốn có hệ tư tưởng riêng, chống lại sự kìm hãm của Giáo hội.","Thành tựu: hội hoạ, điêu khắc của Lê-ô-na-đô đa Vin-xi, Mi-ken-lăng-giơ, Ra-pha-en; văn học của Sếch-xpia, Xéc-van-téc; khoa học của Cô-péc-ních, Ga-li-lê.","Ý nghĩa: đề cao giá trị con người, khoa học, mở đường cho văn hoá châu Âu phát triển."]],["2. Phong trào Cải cách tôn giáo",["Nguyên nhân: Giáo hội ngày càng giàu có, sa đoạ, cản trở sự phát triển của giai cấp tư sản.","Năm 1517, M. Lu-thơ ở Đức công bố luận cương phê phán Giáo hội; sau đó Can-vanh ở Thuỵ Sĩ tiếp tục cải cách.","Nội dung: phủ nhận vai trò thống trị của Giáo hội và Giáo hoàng, đòi bỏ các lễ nghi tốn kém, quay về giáo lí nguyên thuỷ.","Tác động: Thiên Chúa giáo chia thành Cựu giáo và Tân giáo; thúc đẩy cuộc đấu tranh chống phong kiến."]]],"nho":["Phục hưng: bắt đầu ở I-ta-li-a, đề cao con người và khoa học.","Lê-ô-na-đô đa Vin-xi, Sếch-xpia, Cô-péc-ních là những đại diện tiêu biểu.","1517: Lu-thơ khởi đầu Cải cách tôn giáo."],"hoi":["Nêu một số thành tựu tiêu biểu của phong trào Văn hoá Phục hưng.","Phong trào Văn hoá Phục hưng có ý nghĩa gì với xã hội Tây Âu?","Trình bày nguyên nhân và tác động của phong trào Cải cách tôn giáo."]},{"so":4,"chuong":"Chương 2. Trung Quốc và Ấn Độ thời trung đại","ten":"Trung Quốc từ thế kỉ III trước Công nguyên đến giữa thế kỉ XIX","trang":[24,28],"nam":618,"tom":"Từ nhà Tần đến nhà Thanh, chế độ phong kiến Trung Quốc hình thành, phát triển thịnh đạt dưới thời Đường và có mầm mống kinh tế tư bản thời Minh – Thanh, để lại nhiều thành tựu văn hoá lớn.","muc":[["1. Sơ lược tiến trình lịch sử",["Năm 221 TCN, nhà Tần thống nhất Trung Quốc; tiếp theo là Hán, Tuỳ, Đường, Tống, Nguyên, Minh, Thanh.","Chế độ phong kiến được xác lập với hai giai cấp chính: địa chủ và nông dân lĩnh canh."]],["2. Trung Quốc thời Đường",["Nhà Đường (618–907) là thời thịnh trị: bộ máy nhà nước hoàn thiện, tuyển quan lại bằng thi cử.","Kinh tế phát triển nhờ chính sách quân điền, giảm thuế; thủ công, thương nghiệp phát đạt, con đường tơ lụa nhộn nhịp.","Lãnh thổ mở rộng; nhà Đường tăng cường chiến tranh xâm lược bên ngoài."]],["3. Kinh tế thời Minh – Thanh",["Nông nghiệp tiến bộ, thủ công nghiệp có nhiều xưởng lớn thuê nhân công; buôn bán trong và ngoài nước mở rộng.","Xuất hiện mầm mống quan hệ sản xuất tư bản chủ nghĩa."]],["4. Một số thành tựu văn hoá tiêu biểu",["Tư tưởng: Nho giáo giữ vai trò chính thống; Phật giáo phát triển mạnh.","Văn học: thơ Đường (Lý Bạch, Đỗ Phủ, Bạch Cư Dị); tiểu thuyết Tam quốc diễn nghĩa, Thuỷ hử, Tây du kí, Hồng lâu mộng.","Sử học: Sử kí của Tư Mã Thiên và các bộ sử của triều đình.","Kiến trúc, kĩ thuật: Vạn Lí Trường Thành, Cố Cung; giấy, la bàn, thuốc súng, kĩ thuật in."]]],"nho":["Nhà Đường (618–907): thời thịnh trị của phong kiến Trung Quốc.","Thời Minh – Thanh xuất hiện mầm mống tư bản chủ nghĩa.","Thơ Đường, tiểu thuyết Minh – Thanh, bốn phát minh kĩ thuật."],"hoi":["Vì sao nói thời Đường là thời thịnh trị của phong kiến Trung Quốc?","Kinh tế thời Minh – Thanh có điểm gì mới so với thời Đường?","Kể tên một số tác phẩm văn học Trung Quốc thời trung đại mà em biết."]},{"so":5,"chuong":"Chương 2. Trung Quốc và Ấn Độ thời trung đại","ten":"Ấn Độ từ thế kỉ IV đến giữa thế kỉ XIX","trang":[29,33],"nam":null,"tom":"Ấn Độ thời trung đại trải qua ba vương triều lớn: Gúp-ta, Hồi giáo Đê-li và Mô-gôn, với nền văn hoá đặc sắc ảnh hưởng sâu rộng tới Đông Nam Á.","muc":[["1. Các vương triều lớn",["Vương triều Gúp-ta (thế kỉ IV – VI): thống nhất miền Bắc Ấn Độ; kinh tế, văn hoá phát triển, biết luyện sắt (cột sắt không gỉ).","Vương triều Hồi giáo Đê-li (thế kỉ XIII – XVI): người Thổ Nhĩ Kì gốc Trung Á lập ra; truyền bá đạo Hồi; buôn bán với nhiều nước.","Vương triều Mô-gôn (thế kỉ XVI – giữa XIX): người Mông Cổ gốc Trung Á lập ra; thời vua A-cơ-ba đất nước ổn định, phát triển; về sau suy yếu và bị thực dân Anh xâm chiếm."]],["2. Một số thành tựu văn hoá",["Tôn giáo: Hin-đu giáo, Phật giáo, Hồi giáo cùng tồn tại.","Chữ viết, văn học: chữ Phạn hoàn thiện; văn học Hin-đu giáo phong phú.","Kiến trúc, điêu khắc: đền Kha-giu-ra-hô (Hin-đu giáo), lăng Ta-giơ Ma-han (thời Mô-gôn)."]]],"nho":["Ba vương triều: Gúp-ta, Hồi giáo Đê-li, Mô-gôn.","Hin-đu giáo, Phật giáo, Hồi giáo cùng tồn tại.","Lăng Ta-giơ Ma-han là công trình tiêu biểu thời Mô-gôn."],"hoi":["Nêu những nét chính về ba vương triều Gúp-ta, Hồi giáo Đê-li và Mô-gôn.","Kể tên một số thành tựu văn hoá tiêu biểu của Ấn Độ thời trung đại.","Văn hoá Ấn Độ đã ảnh hưởng thế nào đến các nước Đông Nam Á?"]},{"so":6,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Các vương quốc phong kiến Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","trang":[35,38],"nam":null,"tom":"Từ nửa sau thế kỉ X, các vương quốc phong kiến Đông Nam Á bước vào thời kì phát triển thịnh đạt, kinh tế mở rộng giao thương và văn hoá có nhiều thành tựu mang bản sắc riêng.","muc":[["1. Sự phát triển của các vương quốc phong kiến",["Hình thành và phát triển nhiều quốc gia mạnh: Đại Việt, Cam-pu-chia thời Ăng-co, Pa-gan (Mi-an-ma), Su-khô-thay rồi A-du-thay-a (Thái Lan), Lan Xang (Lào), Ma-giắc-pa-hít (In-đô-nê-xi-a), Ma-lắc-ca…","Kinh tế nông nghiệp lúa nước giữ vai trò chính; thủ công và thương mại biển phát triển, nhiều thương cảng sầm uất."]],["2. Một số thành tựu văn hoá",["Tín ngưỡng – tôn giáo: Phật giáo, Hin-đu giáo, Hồi giáo cùng tín ngưỡng dân gian.","Chữ viết – văn học: nhiều dân tộc sáng tạo chữ viết riêng trên cơ sở chữ Phạn, chữ Hán; văn học dân gian và viết phong phú.","Kiến trúc – điêu khắc: Ăng-co Vát, Ăng-co Thom (Cam-pu-chia), chùa tháp Pa-gan (Mi-an-ma), Thạt Luổng (Lào)…"]]],"nho":["Từ nửa sau thế kỉ X, các vương quốc Đông Nam Á thịnh đạt.","Nhiều dân tộc sáng tạo chữ viết riêng.","Công trình tiêu biểu: Ăng-co Vát, Pa-gan, Thạt Luổng."],"hoi":["Kể tên một số vương quốc phong kiến lớn ở Đông Nam Á thời kì này.","Việc nhiều quốc gia Đông Nam Á có chữ viết riêng có ý nghĩa gì?","Giới thiệu một công trình kiến trúc tiêu biểu của Đông Nam Á."]},{"so":7,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Vương quốc Lào","trang":[39,41],"nam":1353,"tom":"Năm 1353, Pha Ngừm thống nhất các mường Lào, lập nước Lan Xang. Lan Xang phát triển thịnh vượng trong các thế kỉ XV – XVII, để lại nền văn hoá Phật giáo đặc sắc.","muc":[["1. Sự hình thành và phát triển",["Người Lào Thơng là cư dân cổ, sau có người Lào Lùm di cư đến; tổ chức xã hội sơ khai là các mường cổ.","Năm 1353, Pha Ngừm thống nhất các mường, lên ngôi vua, đặt tên nước là Lan Xang (Triệu Voi).","Thời thịnh vượng: tổ chức bộ máy nhà nước chặt chẽ, quân đội mạnh, giữ quan hệ hoà hiếu với láng giềng, kiên quyết chống xâm lược."]],["2. Một số nét văn hoá",["Phật giáo được tôn sùng, nhiều chùa tháp được xây dựng.","Có chữ viết riêng trên cơ sở chữ của người Khơ-me; văn học dân gian phong phú.","Công trình tiêu biểu: That Luổng (Thạt Luổng) ở Viêng Chăn; lễ hội té nước, nhảy lăm-vông."]]],"nho":["1353: Pha Ngừm lập nước Lan Xang.","Lan Xang thịnh vượng thế kỉ XV – XVII.","Phật giáo giữ vị trí quan trọng; Thạt Luổng là công trình tiêu biểu."],"hoi":["Vương quốc Lan Xang được thành lập như thế nào?","Nêu những nét chính về sự phát triển của Lan Xang thời thịnh vượng.","Kể tên một vài nét văn hoá tiêu biểu của Lào."]},{"so":8,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Vương quốc Cam-pu-chia","trang":[42,43],"nam":802,"tom":"Năm 802, vua Giay-a-vác-man II thống nhất đất nước, mở ra thời Ăng-co – thời kì phát triển huy hoàng của Cam-pu-chia với những công trình kiến trúc nổi tiếng thế giới.","muc":[["1. Sự hình thành và phát triển",["Từ thế kỉ VI, vương quốc Chân Lạp của người Khơ-me hình thành.","Năm 802, Giay-a-vác-man II thống nhất lãnh thổ, đổi tên nước là Cam-pu-chia, mở đầu thời Ăng-co.","Thời Ăng-co: nông nghiệp có hệ thống thuỷ lợi lớn, lãnh thổ mở rộng; về sau đất nước suy yếu dần."]],["2. Một số nét văn hoá",["Có chữ viết riêng (chữ Khơ-me cổ) bắt nguồn từ chữ Phạn.","Hin-đu giáo và Phật giáo có ảnh hưởng lớn.","Kiến trúc đền tháp Ăng-co Vát, Ăng-co Thom là di sản văn hoá thế giới."]]],"nho":["802: Giay-a-vác-man II mở ra thời Ăng-co.","Ăng-co Vát, Ăng-co Thom là những công trình nổi tiếng."],"hoi":["Trình bày quá trình hình thành và phát triển của vương quốc Cam-pu-chia.","Vì sao thời Ăng-co được coi là thời kì phát triển huy hoàng?"]},{"so":9,"chuong":"Chương 4. Đất nước dưới thời các vương triều Ngô – Đinh – Tiền Lê (939 – 1009)","ten":"Đất nước buổi đầu độc lập (939 – 967)","trang":[45,47],"nam":939,"tom":"Năm 939, Ngô Quyền xưng vương, đóng đô ở Cổ Loa, xây dựng nền độc lập. Sau khi ông mất, đất nước rơi vào loạn 12 sứ quân cho đến khi Đinh Bộ Lĩnh thống nhất vào năm 967.","muc":[["1. Ngô Quyền dựng nền độc lập",["Năm 939, Ngô Quyền bỏ chức Tiết độ sứ, xưng vương, đóng đô ở Cổ Loa.","Đặt triều nghi, chế độ phục sức, đặt các chức quan văn võ; cử tướng lĩnh cai quản các châu.","Việc xưng vương khẳng định nước ta là một quốc gia độc lập, không còn phụ thuộc phương Bắc."]],["2. Loạn 12 sứ quân và sự thống nhất",["Năm 944, Ngô Quyền mất; triều đình suy yếu, các thế lực cát cứ nổi lên, gây nên loạn 12 sứ quân.","Đinh Bộ Lĩnh xây dựng lực lượng ở Hoa Lư, được nhân dân ủng hộ, lần lượt dẹp các sứ quân.","Năm 967, đất nước được thống nhất."]]],"nho":["939: Ngô Quyền xưng vương, đóng đô ở Cổ Loa.","944: Ngô Quyền mất, loạn 12 sứ quân.","967: Đinh Bộ Lĩnh dẹp loạn, thống nhất đất nước."],"hoi":["Việc Ngô Quyền xưng vương có ý nghĩa như thế nào?","Vì sao xảy ra loạn 12 sứ quân?","Đinh Bộ Lĩnh đã thống nhất đất nước như thế nào?"]},{"so":10,"chuong":"Chương 4. Đất nước dưới thời các vương triều Ngô – Đinh – Tiền Lê (939 – 1009)","ten":"Đại Cồ Việt thời Đinh và Tiền Lê (968 – 1009)","trang":[48,50],"nam":968,"tom":"Năm 968, Đinh Bộ Lĩnh lên ngôi hoàng đế, đặt tên nước là Đại Cồ Việt, đóng đô ở Hoa Lư. Năm 981, Lê Hoàn lãnh đạo nhân dân đánh tan quân xâm lược Tống, bảo vệ nền độc lập.","muc":[["1. Tình hình chính trị",["Năm 968, Đinh Bộ Lĩnh lên ngôi (Đinh Tiên Hoàng), đặt quốc hiệu Đại Cồ Việt, đóng đô ở Hoa Lư; định triều nghi, đặt luật pháp nghiêm.","Năm 979, Đinh Tiên Hoàng bị ám hại; vua mới còn nhỏ, nhà Tống lăm le xâm lược. Năm 980, Lê Hoàn lên ngôi, lập nhà Tiền Lê.","Năm 981, quân Tống tiến sang theo hai đường thuỷ, bộ; Lê Hoàn chặn đánh ở sông Bạch Đằng và vùng Chi Lăng, quân Tống thua to.","Chính quyền Tiền Lê được tổ chức chặt chẽ hơn; chia nước thành các lộ, phủ, châu."]],["2. Tình hình xã hội và văn hoá",["Xã hội gồm vua, quan lại, nhà sư; nông dân, thợ thủ công, thương nhân; một số ít nô tì.","Nông nghiệp được chú trọng: vua Lê Hoàn làm lễ cày tịch điền, khai kênh đào.","Phật giáo được đề cao, nhà sư có uy tín, tham gia việc nước; các lễ hội dân gian như đua thuyền, đấu vật phát triển."]]],"nho":["968: Đinh Bộ Lĩnh lập Đại Cồ Việt, kinh đô Hoa Lư.","980: Lê Hoàn lên ngôi; 981: đánh tan quân Tống.","Phật giáo được đề cao, nhà sư tham gia việc nước."],"hoi":["Việc đặt quốc hiệu Đại Cồ Việt và đóng đô ở Hoa Lư có ý nghĩa gì?","Trình bày cuộc kháng chiến chống Tống năm 981 của Lê Hoàn.","Đời sống văn hoá thời Đinh – Tiền Lê có điểm gì nổi bật?"]},{"so":11,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Nhà Lý xây dựng và phát triển đất nước (1009 – 1225)","trang":[52,57],"nam":1010,"tom":"Năm 1009, Lý Công Uẩn lập nhà Lý; năm 1010 dời đô về Thăng Long. Nhà Lý xây dựng bộ máy nhà nước, luật pháp, quân đội vững mạnh, phát triển kinh tế và văn hoá, giáo dục.","muc":[["1. Sự thành lập nhà Lý",["Năm 1009, Lý Công Uẩn được triều thần tôn lên làm vua, lập ra nhà Lý.","Năm 1010, vua ban Chiếu dời đô, chuyển kinh đô từ Hoa Lư về Đại La, đổi tên là Thăng Long.","Năm 1054, nhà Lý đổi tên nước là Đại Việt."]],["2. Xây dựng đất nước",["Bộ máy nhà nước: đứng đầu là vua; giúp vua có các quan văn, võ; cả nước chia thành các lộ, phủ.","Luật pháp: năm 1042 ban hành bộ Hình thư; quân đội gồm cấm quân và quân địa phương, thực hiện chính sách “ngụ binh ư nông”.","Đối nội: mềm dẻo với các tù trưởng miền núi; đối ngoại: giữ hoà hiếu nhưng kiên quyết bảo vệ chủ quyền."]],["3. Kinh tế, xã hội",["Nông nghiệp: khuyến khích khai hoang, đắp đê (đê Cơ Xá năm 1108), lễ cày tịch điền.","Thủ công: dệt (năm 1040 dệt được gấm vóc), gốm, đúc đồng phát triển; thương nghiệp có trao đổi trong nước và với nước ngoài, cảng Vân Đồn.","Xã hội gồm vua quan, địa chủ, nông dân, thợ thủ công, thương nhân, nô tì."]],["4. Văn hoá, giáo dục",["Phật giáo phát triển mạnh, chùa tháp được xây dựng nhiều: chùa Một Cột, tháp Báo Thiên.","Năm 1070 dựng Văn Miếu; năm 1075 mở khoa thi đầu tiên; năm 1076 lập Quốc Tử Giám.","Văn học chữ Hán phát triển; nghệ thuật điêu khắc, kiến trúc đặc sắc."]]],"nho":["1009: nhà Lý thành lập; 1010: dời đô về Thăng Long; 1054: quốc hiệu Đại Việt.","1042: bộ Hình thư; chính sách “ngụ binh ư nông”.","1070 Văn Miếu, 1075 khoa thi đầu tiên, 1076 Quốc Tử Giám."],"hoi":["Vì sao Lý Công Uẩn quyết định dời đô về Đại La?","Nhà Lý đã làm gì để xây dựng bộ máy nhà nước, luật pháp và quân đội?","Nêu những thành tựu về giáo dục thời Lý."]},{"so":12,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Cuộc kháng chiến chống quân xâm lược Tống (1075 – 1077)","trang":[58,61],"nam":1075,"tom":"Dưới sự chỉ huy của Lý Thường Kiệt, quân dân Đại Việt chủ động tấn công trước để chặn thế mạnh của giặc (1075), rồi lập phòng tuyến sông Như Nguyệt đánh bại quân Tống (1077).","muc":[["1. Giai đoạn thứ nhất (1075): tiến công để tự vệ",["Nhà Tống chuẩn bị xâm lược Đại Việt; Lý Thường Kiệt chủ trương “ngồi yên đợi giặc không bằng đem quân ra trước để chặn thế mạnh của giặc”.","Cuối năm 1075, quân Lý bất ngờ tấn công các căn cứ tập kết lương thảo, khí giới của quân Tống ở Khâm Châu, Liêm Châu, Ung Châu rồi rút về nước."]],["2. Giai đoạn thứ hai (1076 – 1077): phòng tuyến sông Như Nguyệt",["Lý Thường Kiệt cho xây dựng phòng tuyến trên bờ nam sông Như Nguyệt (sông Cầu), đóng cọc, đắp luỹ.","Năm 1077, quân Tống do Quách Quỳ chỉ huy kéo sang, nhiều lần vượt sông tấn công nhưng đều thất bại.","Tương truyền bài thơ “Nam quốc sơn hà” vang lên, cổ vũ tinh thần quân ta. Quân ta phản công, quân Tống thua to.","Lý Thường Kiệt chủ động giảng hoà để kết thúc chiến tranh; quân Tống rút về nước."]],["3. Ý nghĩa",["Bảo vệ vững chắc nền độc lập của Đại Việt.","Thể hiện nghệ thuật quân sự độc đáo: tiến công để tự vệ, chặn giặc bằng phòng tuyến, kết thúc chiến tranh bằng giảng hoà."]]],"nho":["1075: tiến công Khâm Châu, Liêm Châu, Ung Châu.","1077: phòng tuyến sông Như Nguyệt, quân Tống thất bại.","Lý Thường Kiệt chủ động giảng hoà để giữ hoà hiếu lâu dài."],"hoi":["Vì sao Lý Thường Kiệt chủ động tấn công sang đất Tống?","Trình bày trận chiến trên phòng tuyến sông Như Nguyệt.","Việc chủ động giảng hoà của Lý Thường Kiệt có ý nghĩa gì?"],"sa_ban":{"ten":"Sa bàn 3D Phòng tuyến Như Nguyệt 1077","url":"khong-gian/engine/2.1.0/sa-ban.html?goi=nhu-nguyet-1077"}},{"so":13,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Đại Việt thời Trần (1226 – 1400)","trang":[62,67],"nam":1226,"tom":"Năm 1226, nhà Trần thành lập, củng cố bộ máy nhà nước với chế độ Thái thượng hoàng, phát triển kinh tế, xã hội và đạt nhiều thành tựu văn hoá rực rỡ.","muc":[["1. Sự thành lập nhà Trần và tổ chức nhà nước",["Cuối thời Lý, triều đình suy yếu; năm 1226, Lý Chiêu Hoàng nhường ngôi cho Trần Cảnh, nhà Trần thành lập.","Thực hiện chế độ Thái thượng hoàng: vua cha nhường ngôi sớm cho con, cùng trông coi việc nước.","Cả nước chia thành 12 lộ; ban hành bộ Quốc triều hình luật; quân đội theo chủ trương “quân lính cốt tinh nhuệ, không cốt đông”."]],["2. Kinh tế, xã hội",["Nông nghiệp: khuyến khích khai hoang, lập điền trang; đặt chức Hà đê sứ trông coi đê điều.","Thủ công, thương nghiệp phát triển; Thăng Long có nhiều phường nghề, chợ.","Xã hội: tầng lớp quý tộc nắm quyền; nông dân, thợ thủ công, thương nhân; nông nô, nô tì làm việc trong điền trang."]],["3. Văn hoá",["Tư tưởng, tôn giáo: Phật giáo phát triển, vua Trần Nhân Tông lập Thiền phái Trúc Lâm; Nho giáo ngày càng được coi trọng.","Giáo dục, khoa cử: tổ chức nhiều khoa thi; Quốc Tử Giám mở rộng.","Khoa học: Quốc sử viện, bộ Đại Việt sử kí của Lê Văn Hưu; y học có danh y Tuệ Tĩnh.","Văn học, nghệ thuật: Hịch tướng sĩ của Trần Quốc Tuấn; chữ Nôm được dùng; tháp Phổ Minh, kiến trúc, điêu khắc đặc sắc."]]],"nho":["1226: nhà Trần thành lập; chế độ Thái thượng hoàng.","Quốc triều hình luật; Hà đê sứ; quân đội tinh nhuệ.","Thiền phái Trúc Lâm; Đại Việt sử kí của Lê Văn Hưu; Hịch tướng sĩ."],"hoi":["Chế độ Thái thượng hoàng có tác dụng gì?","Nêu những nét chính về kinh tế thời Trần.","Kể tên một số thành tựu văn hoá tiêu biểu thời Trần."]},{"so":14,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Ba lần kháng chiến chống quân xâm lược Mông – Nguyên","trang":[68,73],"nam":1258,"tom":"Trong các năm 1258, 1285 và 1287 – 1288, quân dân Đại Việt dưới sự lãnh đạo của nhà Trần ba lần đánh bại quân xâm lược Mông – Nguyên, đội quân mạnh nhất thế giới thời đó.","muc":[["1. Lần thứ nhất (1258)",["Đầu năm 1258, quân Mông Cổ tiến vào Đại Việt; sau trận Bình Lệ Nguyên, quân ta rút lui để bảo toàn lực lượng, thực hiện “vườn không nhà trống”.","Trần Thủ Độ khẳng định: “Đầu thần chưa rơi xuống đất, xin bệ hạ đừng lo”.","Quân ta phản công ở Đông Bộ Đầu, quân Mông Cổ phải rút chạy."]],["2. Lần thứ hai (1285)",["Nhà Trần mở Hội nghị Bình Than (1282) bàn kế đánh giặc, Hội nghị Diên Hồng (1285) hỏi ý các bô lão; quân sĩ thích hai chữ “Sát Thát” lên cánh tay.","Quân Nguyên do Thoát Hoan chỉ huy tiến vào; quân ta tạm rút khỏi Thăng Long.","Giữa năm 1285, quân ta phản công thắng lớn ở Tây Kết, Hàm Tử, Chương Dương, Vạn Kiếp; quân Nguyên thua chạy."]],["3. Lần thứ ba (1287 – 1288)",["Trần Khánh Dư đánh tan đoàn thuyền lương của giặc ở Vân Đồn, làm quân Nguyên lâm vào cảnh thiếu lương.","Trần Quốc Tuấn bố trí trận địa cọc trên sông Bạch Đằng; tháng 4/1288, đoàn thuyền giặc bị tiêu diệt, Ô Mã Nhi bị bắt."]],["4. Nguyên nhân thắng lợi và ý nghĩa",["Toàn dân tham gia đánh giặc; vua tôi đoàn kết; sự lãnh đạo tài giỏi của vua Trần và các tướng như Trần Quốc Tuấn, Trần Quang Khải, Trần Thủ Độ.","Đập tan ý chí xâm lược của Mông – Nguyên, bảo vệ nền độc lập; để lại bài học quý về đoàn kết và nghệ thuật quân sự."]]],"nho":["Ba lần kháng chiến: 1258, 1285, 1287 – 1288.","Hội nghị Bình Than, Diên Hồng; hai chữ “Sát Thát”.","1288: chiến thắng Bạch Đằng do Trần Quốc Tuấn chỉ huy."],"hoi":["Trình bày diễn biến chính của ba lần kháng chiến chống Mông – Nguyên.","Nêu nguyên nhân thắng lợi của ba lần kháng chiến.","Câu nói của Trần Thủ Độ thể hiện tinh thần gì?"]},{"so":15,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Nước Đại Ngu thời Hồ (1400 – 1407)","trang":[74,76],"nam":1400,"tom":"Năm 1400, Hồ Quý Ly lập nhà Hồ, đổi tên nước là Đại Ngu và tiến hành nhiều cải cách. Cuộc kháng chiến chống quân Minh của nhà Hồ thất bại vào năm 1407.","muc":[["1. Nhà Hồ thành lập và cải cách",["Cuối thế kỉ XIV, nhà Trần suy yếu; năm 1400, Hồ Quý Ly phế vua Trần, lập nhà Hồ, đổi tên nước là Đại Ngu.","Chính trị, quân sự: thay quan lại họ Trần bằng người tài; tăng cường quân đội; xây thành Tây Đô (Thanh Hoá).","Kinh tế, xã hội: ban hành chính sách hạn điền, hạn nô; phát hành tiền giấy “Thông bảo hội sao”; thống nhất đo lường.","Văn hoá, giáo dục: dịch sách chữ Hán ra chữ Nôm, đề cao chữ Nôm; sửa đổi chế độ thi cử."]],["2. Cuộc kháng chiến chống quân Minh",["Năm 1406, quân Minh xâm lược Đại Ngu.","Nhà Hồ không đoàn kết được toàn dân, chỉ dựa vào thành luỹ để phòng thủ; năm 1407 kháng chiến thất bại.","Hồ Nguyên Trừng nói: “Thần không sợ đánh, chỉ sợ lòng dân không theo” – nêu rõ nguyên nhân thất bại."]]],"nho":["1400: nhà Hồ thành lập, quốc hiệu Đại Ngu.","Cải cách: hạn điền, hạn nô, tiền giấy, đề cao chữ Nôm.","1407: kháng chiến chống Minh thất bại vì không được lòng dân."],"hoi":["Nêu những nội dung chính trong cải cách của Hồ Quý Ly.","Vì sao cuộc kháng chiến chống quân Minh của nhà Hồ thất bại?","Thành Tây Đô có giá trị gì? Ngày nay thành này được công nhận là gì?"]},{"so":16,"chuong":"Chương 6. Khởi nghĩa Lam Sơn và Đại Việt thời Lê sơ (1418 – 1527)","ten":"Khởi nghĩa Lam Sơn (1418 – 1427)","trang":[78,82],"nam":1418,"tom":"Năm 1418, Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn. Sau mười năm chiến đấu gian khổ, nghĩa quân giành toàn thắng năm 1427, giải phóng đất nước khỏi ách đô hộ của nhà Minh.","muc":[["1. Lê Lợi dựng cờ khởi nghĩa",["Dưới ách đô hộ của nhà Minh, nhân dân bị bóc lột nặng nề.","Đầu năm 1418, Lê Lợi cùng Nguyễn Trãi và các hào kiệt dựng cờ khởi nghĩa ở Lam Sơn (Thanh Hoá), xưng Bình Định Vương."]],["2. Diễn biến chính",["1418 – 1423: những năm đầu khó khăn, nghĩa quân nhiều lần bị vây ở núi Chí Linh; Lê Lai liều mình cứu chúa; có lúc phải tạm hoà với giặc.","1424 – 1425: theo kế của Nguyễn Chích, nghĩa quân chuyển vào Nghệ An, rồi giải phóng Tân Bình, Thuận Hoá; giành thắng lợi đầu tiên.","1426 – 1427: tiến quân ra Bắc; thắng lớn ở Tốt Động – Chúc Động (1426); trận Chi Lăng – Xương Giang (1427), Liễu Thăng tử trận, viện binh Minh bị tiêu diệt.","Cuối năm 1427, Hội thề Đông Quan; quân Minh rút về nước. Nguyễn Trãi viết Bình Ngô đại cáo."]],["3. Nguyên nhân thắng lợi và ý nghĩa",["Nhân dân đồng lòng ủng hộ; lòng yêu nước, ý chí bất khuất; đường lối đúng đắn và tài chỉ huy của Lê Lợi, Nguyễn Trãi.","Kết thúc 20 năm đô hộ của nhà Minh, mở ra thời kì phát triển mới cho Đại Việt."]]],"nho":["1418: Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn.","1426 Tốt Động – Chúc Động; 1427 Chi Lăng – Xương Giang.","Bình Ngô đại cáo của Nguyễn Trãi tuyên bố nền độc lập."],"hoi":["Khởi nghĩa Lam Sơn bùng nổ như thế nào?","Trình bày các giai đoạn phát triển của cuộc khởi nghĩa.","Vì sao khởi nghĩa Lam Sơn giành được thắng lợi?"]},{"so":17,"chuong":"Chương 6. Khởi nghĩa Lam Sơn và Đại Việt thời Lê sơ (1418 – 1527)","ten":"Đại Việt thời Lê sơ (1428 – 1527)","trang":[83,88],"nam":1428,"tom":"Năm 1428, Lê Lợi lên ngôi, lập nhà Lê sơ. Dưới thời Lê Thánh Tông, Đại Việt đạt tới thời thịnh trị với bộ máy nhà nước hoàn chỉnh, luật Hồng Đức và nền giáo dục khoa cử phát triển.","muc":[["1. Tình hình chính trị",["Năm 1428, Lê Lợi lên ngôi, khôi phục quốc hiệu Đại Việt, đóng đô ở Thăng Long (Đông Kinh).","Lê Thánh Tông (1460 – 1497) cải cách: bỏ một số chức quan lớn, vua nắm mọi quyền; chia cả nước thành 13 đạo thừa tuyên.","Ban hành bộ Quốc triều hình luật (luật Hồng Đức), có điểm tiến bộ như bảo vệ quyền lợi phụ nữ.","Kiên quyết bảo vệ chủ quyền lãnh thổ: “một thước núi, một tấc sông của ta, lẽ nào lại tự tiện vứt bỏ”."]],["2. Kinh tế, xã hội",["Nông nghiệp: chính sách quân điền, khuyến khích khai hoang, đắp đê.","Thủ công nghiệp, thương nghiệp phát triển; nhiều làng nghề, chợ.","Xã hội gồm vua quan, địa chủ, nông dân, thợ thủ công, thương nhân, nô tì; số nô tì giảm dần."]],["3. Văn hoá, giáo dục và danh nhân",["Nho giáo chiếm vị trí độc tôn; giáo dục, khoa cử rất phát triển; năm 1484 bắt đầu dựng bia Tiến sĩ ở Văn Miếu.","Nguyễn Trãi: nhà quân sự, chính trị, nhà văn hoá lớn (Bình Ngô đại cáo, Quốc âm thi tập).","Lê Thánh Tông: vị vua anh minh, lập Hội Tao đàn, nhiều tác phẩm văn học.","Ngô Sĩ Liên biên soạn Đại Việt sử kí toàn thư; Lương Thế Vinh viết Đại thành toán pháp."]]],"nho":["1428: nhà Lê sơ thành lập.","Lê Thánh Tông: 13 đạo thừa tuyên, luật Hồng Đức.","1484: dựng bia Tiến sĩ; danh nhân Nguyễn Trãi, Lê Thánh Tông, Ngô Sĩ Liên, Lương Thế Vinh."],"hoi":["Trình bày những cải cách của vua Lê Thánh Tông.","Bộ luật Hồng Đức có những điểm tiến bộ nào?","Giới thiệu một danh nhân văn hoá thời Lê sơ."]},{"so":18,"chuong":"Chương 7. Vùng đất phía Nam Việt Nam từ đầu thế kỉ X đến đầu thế kỉ XVI","ten":"Vương quốc Chăm-pa và vùng đất Nam Bộ từ đầu thế kỉ X đến đầu thế kỉ XVI","trang":[90,94],"nam":null,"tom":"Từ thế kỉ X, Chăm-pa bước vào thời kì Vi-giay-a với kinh đô ở Đồ Bàn, có nền kinh tế, văn hoá phát triển nhưng gặp nhiều khó khăn vì chiến tranh. Vùng đất Nam Bộ thời kì này dân cư còn thưa thớt.","muc":[["1. Vương quốc Chăm-pa",["Năm 988, một quý tộc Chăm lập vương triều Vi-giay-a, kinh đô chuyển về Vi-giay-a (Đồ Bàn, Bình Định ngày nay).","Chăm-pa nhiều lần xảy ra chiến tranh với Chân Lạp và xung đột với Đại Việt; năm 1069 cắt ba châu Bố Chính, Địa Lý, Ma Linh cho Đại Việt.","Kinh tế: trồng lúa nước, khai thác lâm sản, buôn bán đường biển; văn hoá: theo Hin-đu giáo, Phật giáo, xây dựng nhiều đền tháp (tháp Bánh Ít, tháp Dương Long…)."]],["2. Vùng đất Nam Bộ",["Sau khi Phù Nam sụp đổ (đầu thế kỉ VII), Nam Bộ thuộc quyền kiểm soát của Chân Lạp.","Dân cư thưa thớt, nhiều vùng hoang vu, sình lầy; cư dân sống chủ yếu bằng nông nghiệp, khai thác sản vật."]]],"nho":["988: vương triều Vi-giay-a của Chăm-pa; kinh đô Đồ Bàn.","Chăm-pa có kinh tế biển và văn hoá đền tháp phát triển.","Nam Bộ thời kì này thuộc Chân Lạp, dân cư thưa thớt."],"hoi":["Nêu những nét chính về chính trị, kinh tế, văn hoá của Chăm-pa từ thế kỉ X đến đầu thế kỉ XVI.","Vùng đất Nam Bộ thời kì này có đặc điểm gì?"]},{"so":"CĐ1","chuong":"Chủ đề chung","ten":"Các cuộc đại phát kiến địa lí","trang":[166,169],"nam":1492,"tom":"Chủ đề tích hợp Lịch sử và Địa lí về các chuyến thám hiểm lớn cuối thế kỉ XV – đầu thế kỉ XVI, tiêu biểu là chuyến đi của C. Cô-lôm-bô và Ph. Ma-gien-lan, cùng tác động của chúng tới thế giới.","muc":[["1. Cô-lôm-bô và cuộc thám hiểm tìm ra châu Mỹ",["Năm 1492, C. Cô-lôm-bô được hoàng gia Tây Ban Nha tài trợ, đi về phía tây Đại Tây Dương với ý định tới Ấn Độ.","Đoàn thám hiểm đến được các đảo vùng Ca-ri-bê, mở ra con đường đến châu Mỹ cho người châu Âu."]],["2. Ma-gien-lan và chuyến đi vòng quanh Trái Đất",["Năm 1519, Ph. Ma-gien-lan dẫn đoàn thuyền vượt Đại Tây Dương, qua eo biển ở cực nam châu Mỹ (sau mang tên ông), vào Thái Bình Dương.","Ma-gien-lan bị giết ở Phi-líp-pin; những người còn lại tiếp tục hành trình, về đến Tây Ban Nha năm 1522, chứng minh Trái Đất hình cầu."]],["3. Tác động",["Mở rộng hiểu biết về Trái Đất, thúc đẩy giao lưu kinh tế, văn hoá giữa các châu lục.","Mở đầu quá trình xâm chiếm, cướp bóc thuộc địa và buôn bán nô lệ."]]],"nho":["1492: Cô-lôm-bô đến châu Mỹ.","1519 – 1522: chuyến đi vòng quanh Trái Đất của đoàn Ma-gien-lan.","Phát kiến địa lí mở rộng hiểu biết nhưng kéo theo chủ nghĩa thực dân."],"hoi":["Kể lại hành trình của Cô-lôm-bô hoặc Ma-gien-lan.","Chuyến đi của Ma-gien-lan chứng minh điều gì?","Các cuộc đại phát kiến địa lí tác động thế nào tới thế giới?"]},{"so":"CĐ2","chuong":"Chủ đề chung","ten":"Đô thị: lịch sử và hiện tại","trang":[170,174],"nam":null,"tom":"Chủ đề tích hợp về sự ra đời và vai trò của đô thị từ thời cổ đại đến trung đại, gắn với các nền văn minh phương Đông, Hy Lạp – La Mã và châu Âu trung đại.","muc":[["1. Đô thị thời cổ đại",["Ở phương Đông, các làng ven sông lớn mở rộng thành những khu dân cư đông đúc, hình thành đô thị như Ba-bi-lon (Lưỡng Hà), Mem-phít (Ai Cập), Mô-hen-giô Đa-rô (Ấn Độ). Đô thị là trung tâm chính trị, kinh tế, văn hoá của các quốc gia cổ đại.","Ở Hy Lạp, La Mã, đô thị gắn với thủ công nghiệp, thương nghiệp đường biển; là nơi ra đời thể chế dân chủ A-ten và nhiều thành tựu văn hoá."]],["2. Đô thị châu Âu thời trung đại",["Từ thế kỉ XI, thợ thủ công, thương nhân lập ra các thành thị; thị dân lập phường hội, thương hội.","Thương nhân buôn bán khắp châu Âu, góp phần phá vỡ kinh tế tự cấp tự túc của lãnh địa, thúc đẩy kinh tế hàng hoá và văn hoá phát triển."]],["3. Đô thị hôm nay",["Đô thị ngày nay là trung tâm kinh tế, văn hoá, khoa học; đối mặt với các vấn đề dân số, môi trường, giao thông.","Tìm hiểu lịch sử đô thị giúp ta hiểu và có ý thức gìn giữ di sản của thành phố nơi mình sống."]]],"nho":["Đô thị cổ đại: Ba-bi-lon, Mem-phít, Mô-hen-giô Đa-rô, A-ten, Rô-ma.","Thành thị trung đại thúc đẩy kinh tế hàng hoá.","Đô thị là trung tâm chính trị, kinh tế, văn hoá qua mọi thời kì."],"hoi":["Các đô thị cổ ở phương Đông có vai trò gì?","Thương nhân có vai trò thế nào trong các đô thị châu Âu trung đại?","Giới thiệu lịch sử một đô thị ở Việt Nam mà em biết."]}]},"8":{"sach":"Lịch sử và Địa lí 8 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 6–92 và hai chủ đề chung tr. 155–171","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII","ten":"Cách mạng tư sản Anh và Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ","trang":[8,11],"nam":1640,"tom":"Hai cuộc cách mạng tư sản tiêu biểu ở Anh (thế kỉ XVII) và Bắc Mỹ (thế kỉ XVIII) mở đường cho chủ nghĩa tư bản phát triển; nước Mỹ ra đời.","muc":[["1. Cách mạng tư sản Anh (thế kỉ XVII)",["Nguyên nhân: kinh tế tư bản chủ nghĩa phát triển mạnh, giai cấp tư sản và quý tộc mới giàu lên nhưng bị chế độ quân chủ chuyên chế của vua Sác-lơ I kìm hãm.","Diễn biến: năm 1642 nội chiến bùng nổ giữa phe Quốc hội và phe nhà vua; năm 1649 vua Sác-lơ I bị xử tử, nước Anh thành nước cộng hoà; năm 1688 chính biến đưa tới chế độ quân chủ lập hiến.","Kết quả, ý nghĩa: lật đổ chế độ quân chủ chuyên chế, mở đường cho chủ nghĩa tư bản ở Anh phát triển; nhưng quyền lợi chủ yếu thuộc về tư sản và quý tộc mới."]],["2. Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ (1775 – 1783)",["Nguyên nhân: chính quyền Anh đánh thuế nặng, cấm mở mang sản xuất, buôn bán, kìm hãm kinh tế của 13 thuộc địa; sự kiện “chè Bô-xtơn” (1773) làm mâu thuẫn bùng nổ.","Diễn biến: năm 1775 chiến tranh bắt đầu; ngày 4/7/1776, Tuyên ngôn Độc lập được công bố; năm 1777 nghĩa quân thắng lớn ở Xa-ra-tô-ga; năm 1783 Anh phải công nhận nền độc lập.","Kết quả, ý nghĩa: Hợp chúng quốc Mỹ ra đời, Hiến pháp 1787 xác lập chế độ cộng hoà; đây vừa là cuộc chiến tranh giải phóng dân tộc vừa là một cuộc cách mạng tư sản."]]],"nho":["1642 – 1688: Cách mạng tư sản Anh, xác lập chế độ quân chủ lập hiến.","4/7/1776: Tuyên ngôn Độc lập của 13 thuộc địa.","1783: Anh công nhận nền độc lập; Hợp chúng quốc Mỹ ra đời."],"hoi":["Nêu nguyên nhân bùng nổ Cách mạng tư sản Anh.","Trình bày kết quả và ý nghĩa của Chiến tranh giành độc lập ở Bắc Mỹ.","Vì sao nói Chiến tranh giành độc lập của 13 thuộc địa cũng là một cuộc cách mạng tư sản?"]},{"so":2,"chuong":"Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII","ten":"Cách mạng tư sản Pháp cuối thế kỉ XVIII","trang":[12,14],"nam":1789,"tom":"Cuộc cách mạng bùng nổ năm 1789, lật đổ chế độ quân chủ chuyên chế, có ảnh hưởng sâu rộng tới châu Âu và thế giới.","muc":[["1. Nguyên nhân",["Kinh tế tư bản chủ nghĩa phát triển nhưng bị chế độ phong kiến kìm hãm; nhà nước rơi vào khủng hoảng tài chính.","Xã hội chia ba đẳng cấp: tăng lữ, quý tộc có đặc quyền; đẳng cấp thứ ba (tư sản, nông dân, bình dân thành thị) chịu mọi thứ thuế.","Trào lưu Triết học Ánh sáng (Mông-te-xki-ơ, Vôn-te, Rút-xô) phê phán chế độ cũ, chuẩn bị về tư tưởng cho cách mạng."]],["2. Diễn biến chính",["Ngày 14/7/1789, quần chúng Pa-ri tấn công ngục Ba-xti, mở đầu cách mạng; Quốc hội thông qua Tuyên ngôn Nhân quyền và Dân quyền.","Năm 1792 chế độ quân chủ bị lật đổ, nền cộng hoà được thành lập.","1793 – 1794: phái Gia-cô-banh cầm quyền, thực hiện nhiều biện pháp triệt để, đánh lui thù trong giặc ngoài; tháng 7/1794 bị lật đổ, cách mạng đi xuống."]],["3. Kết quả và ý nghĩa",["Lật đổ chế độ phong kiến chuyên chế, xoá bỏ nhiều trở ngại cho chủ nghĩa tư bản phát triển.","Là cuộc cách mạng tư sản triệt để nhất thời kì này, tư tưởng tự do, bình đẳng lan rộng khắp châu Âu và thế giới."]]],"nho":["14/7/1789: phá ngục Ba-xti, mở đầu Cách mạng tư sản Pháp.","Tuyên ngôn Nhân quyền và Dân quyền khẳng định quyền tự do, bình đẳng.","1793 – 1794: chuyên chính Gia-cô-banh, đỉnh cao của cách mạng."],"hoi":["Trình bày những nguyên nhân dẫn đến Cách mạng tư sản Pháp.","Vì sao nói chuyên chính Gia-cô-banh là đỉnh cao của cách mạng?","Nêu ý nghĩa của Cách mạng tư sản Pháp cuối thế kỉ XVIII."]},{"so":3,"chuong":"Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII","ten":"Cách mạng công nghiệp (nửa sau thế kỉ XVIII – giữa thế kỉ XIX)","trang":[15,18],"nam":null,"tom":"Máy móc thay thế lao động thủ công, bắt đầu ở Anh rồi lan ra các nước, làm thay đổi sâu sắc kinh tế và xã hội.","muc":[["1. Những thành tựu tiêu biểu",["Cách mạng công nghiệp bắt đầu ở Anh từ những năm 60 của thế kỉ XVIII, khởi đầu từ ngành dệt.","Máy kéo sợi Gien-ni (1764), máy dệt chạy bằng sức nước, máy hơi nước của Giêm Oát (1784) giúp sản xuất bằng máy thay cho lao động thủ công.","Giao thông vận tải: tàu thuỷ chạy bằng hơi nước của Phơn-tơn (1807), đầu máy xe lửa của Xti-phen-xơn (1814); sau đó cách mạng công nghiệp lan sang Pháp, Đức, Mỹ."]],["2. Tác động",["Kinh tế: năng suất lao động tăng vọt, nhiều trung tâm công nghiệp và thành phố mới ra đời.","Xã hội: hình thành hai giai cấp cơ bản là tư sản công nghiệp và vô sản công nghiệp; đời sống công nhân cực khổ dẫn tới đấu tranh.","Cách mạng công nghiệp thúc đẩy các nước tư bản tìm kiếm thị trường, thuộc địa."]]],"nho":["Cách mạng công nghiệp bắt đầu ở Anh từ nửa sau thế kỉ XVIII.","Máy hơi nước của Giêm Oát là phát minh then chốt.","Hình thành giai cấp tư sản và vô sản công nghiệp."],"hoi":["Kể tên một số phát minh tiêu biểu của cách mạng công nghiệp.","Cách mạng công nghiệp tác động thế nào tới kinh tế và xã hội?","Vì sao cách mạng công nghiệp bắt đầu từ ngành dệt ở Anh?"]},{"so":4,"chuong":"Chương 2. Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX","ten":"Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX","trang":[19,22],"nam":null,"tom":"Các nước phương Tây từng bước xâm nhập Đông Nam Á; nhân dân trong khu vực đấu tranh chống ách đô hộ của thực dân.","muc":[["1. Quá trình xâm nhập của thực dân phương Tây",["Từ thế kỉ XVI, Bồ Đào Nha, Tây Ban Nha rồi Hà Lan, Anh, Pháp lần lượt tìm đến Đông Nam Á; năm 1511 Bồ Đào Nha chiếm Ma-lắc-ca.","Ban đầu là buôn bán, truyền đạo, lập thương điếm; dần dần chuyển sang xâm chiếm đất đai, đặt ách cai trị (Tây Ban Nha ở Phi-líp-pin, Hà Lan ở In-đô-nê-xi-a…)."]],["2. Tình hình chính trị, kinh tế, văn hoá – xã hội",["Chính quyền thực dân áp đặt bộ máy cai trị, chia để trị, vơ vét tài nguyên, độc quyền buôn bán.","Kinh tế thuộc địa hình thành: đồn điền, khai mỏ, xuất khẩu nông sản; đời sống nhân dân cơ cực.","Văn hoá: Thiên Chúa giáo được truyền bá mạnh ở một số nơi; văn hoá truyền thống bị kìm hãm."]],["3. Đấu tranh chống ách đô hộ",["Nhân dân Đông Nam Á nổi dậy ở nhiều nơi: In-đô-nê-xi-a, Phi-líp-pin, Mi-an-ma…","Các cuộc đấu tranh còn lẻ tẻ, chưa thắng lợi nhưng thể hiện tinh thần yêu nước, đặt nền móng cho phong trào giải phóng dân tộc về sau."]]],"nho":["Từ thế kỉ XVI, thực dân phương Tây xâm nhập Đông Nam Á.","1511: Bồ Đào Nha chiếm Ma-lắc-ca.","Nhân dân Đông Nam Á liên tục đấu tranh chống thực dân."],"hoi":["Trình bày quá trình xâm nhập Đông Nam Á của các nước phương Tây.","Chính sách cai trị của thực dân đã ảnh hưởng thế nào đến Đông Nam Á?","Nêu một số cuộc đấu tranh tiêu biểu chống thực dân ở Đông Nam Á."]},{"so":5,"chuong":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","ten":"Cuộc xung đột Nam – Bắc triều và Trịnh – Nguyễn","trang":[23,27],"nam":1527,"tom":"Nhà Mạc thành lập dẫn tới chiến tranh Nam – Bắc triều, sau đó là cục diện Đàng Trong – Đàng Ngoài chia cắt đất nước.","muc":[["1. Nhà Mạc thành lập và xung đột Nam – Bắc triều",["Đầu thế kỉ XVI, nhà Lê sơ suy yếu, xã hội rối ren; năm 1527, Mạc Đăng Dung phế vua Lê, lập nhà Mạc.","Năm 1533, Nguyễn Kim lập một người dòng dõi nhà Lê lên ngôi ở Thanh Hoá, gọi là Nam triều; nhà Mạc ở Thăng Long là Bắc triều.","Chiến tranh Nam – Bắc triều kéo dài đến năm 1592, khi Nam triều chiếm lại Thăng Long."]],["2. Xung đột Trịnh – Nguyễn",["Sau khi Nguyễn Kim mất, quyền lực rơi vào tay họ Trịnh; Nguyễn Hoàng vào trấn thủ Thuận Hoá (1558), dần xây dựng thế lực riêng ở phía Nam.","1627 – 1672: họ Trịnh và họ Nguyễn đánh nhau bảy lần nhưng không phân thắng bại, lấy sông Gianh làm ranh giới.","Đất nước bị chia cắt thành Đàng Ngoài và Đàng Trong hơn 200 năm, gây nhiều tổn thất cho nhân dân."]]],"nho":["1527: nhà Mạc thành lập; 1533 – 1592: chiến tranh Nam – Bắc triều.","1627 – 1672: chiến tranh Trịnh – Nguyễn.","Sông Gianh là ranh giới Đàng Ngoài – Đàng Trong."],"hoi":["Vì sao nhà Mạc ra đời?","Trình bày hệ quả của các cuộc xung đột Nam – Bắc triều và Trịnh – Nguyễn.","Theo em, sự chia cắt đất nước gây ra những hậu quả gì?"]},{"so":6,"chuong":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","ten":"Công cuộc khai phá vùng đất phía Nam từ thế kỉ XVI đến thế kỉ XVIII","trang":[28,30],"nam":null,"tom":"Các chúa Nguyễn và cư dân Việt khai phá, xác lập chủ quyền ở vùng đất phía Nam, gồm cả các quần đảo Hoàng Sa, Trường Sa.","muc":[["1. Quá trình khai phá vùng đất phía Nam",["Từ năm 1558, Nguyễn Hoàng và các chúa Nguyễn mở rộng khai phá từ Thuận Hoá, Quảng Nam vào phía Nam.","Cư dân Việt cùng các tộc người tại chỗ khai hoang, lập làng; năm 1698, Nguyễn Hữu Cảnh vào kinh lược, lập phủ Gia Định.","Đến giữa thế kỉ XVIII (1757), vùng đất Nam Bộ ngày nay về cơ bản thuộc quyền quản lí của chúa Nguyễn; vùng Hà Tiên do họ Mạc khai phá cũng thuộc về Đàng Trong."]],["2. Xác lập và thực thi chủ quyền ở Hoàng Sa, Trường Sa",["Các chúa Nguyễn lập đội Hoàng Sa, đội Bắc Hải hằng năm ra các đảo khai thác sản vật, đo đạc, kiểm soát.","Đây là những bằng chứng lịch sử về việc nhà nước Việt Nam xác lập và thực thi chủ quyền đối với hai quần đảo Hoàng Sa, Trường Sa."]],["3. Ý nghĩa",["Mở rộng lãnh thổ, hình thành vùng đất phía Nam trù phú.","Thúc đẩy giao lưu giữa các tộc người, tạo nên bản sắc văn hoá phong phú của Nam Bộ."]]],"nho":["1558: Nguyễn Hoàng vào trấn thủ Thuận Hoá.","1698: Nguyễn Hữu Cảnh lập phủ Gia Định.","Đội Hoàng Sa, đội Bắc Hải thực thi chủ quyền ở Hoàng Sa, Trường Sa."],"hoi":["Trình bày quá trình khai phá vùng đất phía Nam.","Đội Hoàng Sa, đội Bắc Hải có vai trò gì?","Công cuộc khai phá vùng đất phía Nam có ý nghĩa như thế nào?"]},{"so":7,"chuong":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","ten":"Khởi nghĩa nông dân ở Đàng Ngoài thế kỉ XVIII","trang":[31,34],"nam":null,"tom":"Đời sống khổ cực dưới chính quyền Lê – Trịnh dẫn tới nhiều cuộc khởi nghĩa nông dân lớn ở Đàng Ngoài.","muc":[["1. Nguyên nhân",["Giữa thế kỉ XVIII, chính quyền Lê – Trịnh ở Đàng Ngoài mục nát; quan lại tham nhũng, sưu thuế nặng nề.","Ruộng đất bị địa chủ, cường hào chiếm đoạt; mất mùa, đói kém liên tiếp, nông dân phải bỏ làng đi phiêu tán."]],["2. Một số cuộc khởi nghĩa tiêu biểu",["Khởi nghĩa của Nguyễn Danh Phương (1740 – 1751) ở vùng Tam Đảo.","Khởi nghĩa của Nguyễn Hữu Cầu (1741 – 1751) ở vùng Hải Dương, Kinh Bắc.","Khởi nghĩa của Hoàng Công Chất (1739 – 1769) ở Sơn Nam và miền Tây Bắc; khởi nghĩa của Lê Duy Mật (1738 – 1770) ở Thanh Hoá, Nghệ An."]],["3. Ý nghĩa",["Các cuộc khởi nghĩa cuối cùng bị đàn áp nhưng làm cho chính quyền Lê – Trịnh lung lay.","Thể hiện tinh thần đấu tranh của nông dân, là tiền đề cho phong trào Tây Sơn sau này."]]],"nho":["Nguyên nhân: chính quyền Lê – Trịnh mục nát, đời sống nông dân cực khổ.","Tiêu biểu: Nguyễn Danh Phương, Nguyễn Hữu Cầu, Hoàng Công Chất, Lê Duy Mật."],"hoi":["Vì sao giữa thế kỉ XVIII, khởi nghĩa nông dân bùng nổ ở Đàng Ngoài?","Lập bảng các cuộc khởi nghĩa tiêu biểu (thời gian, người lãnh đạo, địa bàn).","Phong trào khởi nghĩa nông dân có ý nghĩa gì?"]},{"so":8,"chuong":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","ten":"Phong trào Tây Sơn","trang":[35,41],"nam":1771,"tom":"Từ năm 1771, phong trào Tây Sơn lật đổ các tập đoàn phong kiến, đánh tan quân Xiêm (1785) và quân Thanh (1789).","muc":[["1. Khởi nghĩa Tây Sơn bùng nổ (1771)",["Năm 1771, ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ dựng cờ khởi nghĩa ở Tây Sơn thượng đạo (Gia Lai), được nhân dân ủng hộ.","Nghĩa quân lần lượt làm chủ nhiều vùng; năm 1777 lật đổ chính quyền chúa Nguyễn ở Đàng Trong."]],["2. Đánh tan quân xâm lược Xiêm và Thanh",["Đầu năm 1785, Nguyễn Huệ bố trí trận địa mai phục trên sông Tiền, đánh tan quân Xiêm ở Rạch Gầm – Xoài Mút.","Năm 1786, nghĩa quân ra Bắc lật đổ chính quyền họ Trịnh. Cuối năm 1788, quân Thanh kéo sang; Nguyễn Huệ lên ngôi hoàng đế (Quang Trung) và tiến quân ra Bắc.","Tết Kỷ Dậu (1789), quân Tây Sơn thắng lớn ở Ngọc Hồi – Đống Đa, giải phóng Thăng Long."]],["3. Quang Trung xây dựng đất nước",["Ban Chiếu khuyến nông, khuyến khích khôi phục sản xuất; mở cửa ải, thông chợ búa.","Ban Chiếu lập học, đề cao chữ Nôm; tổ chức lại quân đội; đặt quan hệ hoà hiếu với nhà Thanh.","Năm 1792, Quang Trung qua đời; công cuộc dở dang, triều Tây Sơn suy yếu dần."]],["4. Ý nghĩa",["Phong trào Tây Sơn xoá bỏ ranh giới chia cắt, đặt nền tảng thống nhất đất nước.","Đánh tan hai đạo quân xâm lược, bảo vệ độc lập dân tộc; Nguyễn Huệ – Quang Trung là thiên tài quân sự."]]],"nho":["1771: khởi nghĩa Tây Sơn bùng nổ.","1785: chiến thắng Rạch Gầm – Xoài Mút.","Tết Kỷ Dậu 1789: chiến thắng Ngọc Hồi – Đống Đa."],"hoi":["Trình bày những thắng lợi tiêu biểu của phong trào Tây Sơn.","Nêu những chính sách của vua Quang Trung trong xây dựng đất nước.","Vì sao phong trào Tây Sơn giành được thắng lợi?"],"sa_ban":{"ten":"Sa bàn 3D Ngọc Hồi – Đống Đa 1789","url":"khong-gian/engine/1.0.0/sa-ban.html?goi=ngoc-hoi-dong-da"}},{"so":9,"chuong":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","ten":"Tình hình kinh tế, văn hoá, tôn giáo trong các thế kỉ XVI – XVIII","trang":[42,45],"nam":null,"tom":"Kinh tế hàng hoá, đô thị phát triển; văn hoá, tôn giáo có nhiều chuyển biến, chữ Quốc ngữ ra đời.","muc":[["1. Kinh tế",["Nông nghiệp: Đàng Ngoài có lúc trì trệ vì chiến tranh, Đàng Trong phát triển mạnh nhờ khai hoang, nhất là vùng đất phía Nam.","Thủ công nghiệp: nhiều làng nghề nổi tiếng như gốm Bát Tràng, lụa Vạn Phúc, đường mía, đúc đồng.","Thương nghiệp phát triển, buôn bán với thương nhân Nhật Bản, Trung Quốc, Hà Lan, Anh…; đô thị hưng khởi: Thăng Long – Kẻ Chợ, Phố Hiến, Hội An, Thanh Hà."]],["2. Văn hoá, tôn giáo",["Nho giáo vẫn được đề cao nhưng giảm sút; Phật giáo, Đạo giáo được phục hồi; Thiên Chúa giáo được truyền vào.","Chữ Quốc ngữ được hình thành dựa trên chữ cái La-tinh, ban đầu dùng cho việc truyền đạo.","Văn học chữ Nôm, văn học dân gian phát triển; nghệ thuật dân gian: tranh Đông Hồ, chèo, tuồng, kiến trúc đình làng."]]],"nho":["Đô thị tiêu biểu: Thăng Long – Kẻ Chợ, Phố Hiến, Hội An.","Chữ Quốc ngữ ra đời từ thế kỉ XVII.","Văn học chữ Nôm và nghệ thuật dân gian phát triển mạnh."],"hoi":["Nêu những nét chính về kinh tế Việt Nam thế kỉ XVI – XVIII.","Vì sao các đô thị phát triển trong thời kì này?","Chữ Quốc ngữ ra đời trong hoàn cảnh nào?"]},{"so":10,"chuong":"Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX","ten":"Sự hình thành chủ nghĩa đế quốc ở các nước Âu – Mỹ (cuối thế kỉ XIX – đầu thế kỉ XX)","trang":[46,49],"nam":null,"tom":"Chủ nghĩa tư bản chuyển sang giai đoạn đế quốc, các nước lớn đẩy mạnh xâm chiếm thuộc địa.","muc":[["1. Sự hình thành chủ nghĩa đế quốc",["Cuối thế kỉ XIX – đầu thế kỉ XX, sản xuất tập trung cao, các công ti độc quyền ra đời và chi phối nền kinh tế.","Xuất khẩu tư bản trở nên phổ biến; các nước lớn tăng cường xâm chiếm, tranh giành thuộc địa."]],["2. Đặc điểm của một số nước đế quốc",["Anh: “chủ nghĩa đế quốc thực dân”, có hệ thống thuộc địa rộng lớn nhất thế giới.","Pháp: “chủ nghĩa đế quốc cho vay lãi”, xuất khẩu tư bản chủ yếu dưới hình thức cho vay.","Đức: “chủ nghĩa đế quốc quân phiệt hiếu chiến”; Mỹ: kinh tế vươn lên hàng đầu thế giới với những công ti độc quyền khổng lồ."]],["3. Mâu thuẫn trong lòng các nước đế quốc",["Mâu thuẫn giữa tư sản và vô sản, giữa đế quốc với thuộc địa, giữa các nước đế quốc với nhau ngày càng gay gắt.","Cuộc tranh giành thuộc địa là nguyên nhân sâu xa dẫn tới Chiến tranh thế giới thứ nhất."]]],"nho":["Đặc trưng: công ti độc quyền, xuất khẩu tư bản, tranh giành thuộc địa.","Anh – thực dân; Pháp – cho vay lãi; Đức – quân phiệt; Mỹ – công ti độc quyền."],"hoi":["Chủ nghĩa đế quốc hình thành như thế nào?","Nêu đặc điểm của chủ nghĩa đế quốc Anh, Pháp, Đức, Mỹ.","Vì sao các nước đế quốc tranh giành thuộc địa quyết liệt?"]},{"so":11,"chuong":"Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX","ten":"Phong trào công nhân từ cuối thế kỉ XVIII đến đầu thế kỉ XX và sự ra đời của chủ nghĩa xã hội khoa học","trang":[50,53],"nam":null,"tom":"Giai cấp công nhân đấu tranh ngày càng mạnh; chủ nghĩa xã hội khoa học ra đời với Tuyên ngôn của Đảng Cộng sản (1848).","muc":[["1. Phong trào công nhân",["Cuối thế kỉ XVIII – đầu thế kỉ XIX, công nhân đập phá máy móc, đốt công xưởng – hình thức đấu tranh tự phát.","Nửa đầu thế kỉ XIX: khởi nghĩa của công nhân Li-ông (Pháp), phong trào Hiến chương (Anh), khởi nghĩa thợ dệt Sơ-lê-din (Đức) đánh dấu bước trưởng thành.","Năm 1871, Công xã Pa-ri – nhà nước kiểu mới đầu tiên của giai cấp vô sản ra đời, tồn tại 72 ngày."]],["2. Chủ nghĩa xã hội khoa học ra đời",["C. Mác và Ph. Ăng-ghen xây dựng học thuyết về chủ nghĩa xã hội khoa học; tháng 2/1848, Tuyên ngôn của Đảng Cộng sản được công bố.","Năm 1864, Hội Liên hiệp lao động quốc tế (Quốc tế thứ nhất) thành lập; năm 1889, Quốc tế thứ hai thành lập, lấy ngày 1/5 làm ngày Quốc tế lao động."]]],"nho":["1848: Tuyên ngôn của Đảng Cộng sản.","1864: Quốc tế thứ nhất; 1871: Công xã Pa-ri; 1889: Quốc tế thứ hai.","Mác và Ăng-ghen là những người sáng lập chủ nghĩa xã hội khoa học."],"hoi":["Phong trào công nhân phát triển qua những hình thức đấu tranh nào?","Tuyên ngôn của Đảng Cộng sản ra đời có ý nghĩa gì?","Vì sao Công xã Pa-ri được coi là nhà nước kiểu mới?"]},{"so":12,"chuong":"Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX","ten":"Chiến tranh thế giới thứ nhất (1914 – 1918) và Cách mạng tháng Mười Nga năm 1917","trang":[54,57],"nam":1914,"tom":"Cuộc chiến tranh đế quốc gây hậu quả nặng nề; Cách mạng tháng Mười Nga thắng lợi mở ra thời kì mới.","muc":[["1. Chiến tranh thế giới thứ nhất (1914 – 1918)",["Nguyên nhân: mâu thuẫn về thuộc địa giữa các nước đế quốc; hình thành hai khối đối địch: phe Liên minh (Đức, Áo – Hung…) và phe Hiệp ước (Anh, Pháp, Nga).","Duyên cớ: ngày 28/6/1914, Thái tử Áo – Hung bị ám sát ở Xa-ra-e-vô; tháng 7 – 8/1914 chiến tranh bùng nổ.","Diễn biến: 1914 – 1916 phe Liên minh tấn công mạnh; 1917 – 1918 phe Hiệp ước phản công, Mỹ tham chiến; ngày 11/11/1918 Đức kí hiệp định đầu hàng.","Hậu quả: khoảng 10 triệu người chết, nhiều thành phố, làng mạc bị tàn phá; bản đồ châu Âu thay đổi."]],["2. Cách mạng tháng Mười Nga năm 1917",["Cách mạng tháng Hai (1917) lật đổ chế độ Nga hoàng, dẫn tới tình trạng hai chính quyền song song.","Đảng Bôn-sê-vích do V. I. Lê-nin lãnh đạo chuẩn bị khởi nghĩa; đêm 24/10 (6/11) khởi nghĩa ở Pê-tơ-rô-grát, chiếm Cung điện Mùa Đông.","Chính quyền Xô viết thành lập, ban hành Sắc lệnh hoà bình và Sắc lệnh ruộng đất.","Ý nghĩa: mở ra kỉ nguyên mới, cổ vũ phong trào cách mạng và giải phóng dân tộc trên thế giới."]]],"nho":["28/6/1914: sự kiện Xa-ra-e-vô; 11/11/1918: chiến tranh kết thúc.","Cách mạng tháng Mười Nga thắng lợi năm 1917 dưới sự lãnh đạo của Lê-nin.","Sắc lệnh hoà bình, Sắc lệnh ruộng đất là văn kiện đầu tiên của chính quyền Xô viết."],"hoi":["Trình bày nguyên nhân và hậu quả của Chiến tranh thế giới thứ nhất.","Nêu diễn biến chính của Cách mạng tháng Mười Nga.","Cách mạng tháng Mười có ý nghĩa gì đối với thế giới?"]},{"so":13,"chuong":"Chương 5. Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX","ten":"Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX","trang":[58,61],"nam":null,"tom":"Nhiều phát minh khoa học, kĩ thuật và tác phẩm văn học, nghệ thuật lớn làm thay đổi đời sống con người.","muc":[["1. Khoa học tự nhiên và kĩ thuật",["Nhiều phát hiện lớn: định luật bảo toàn vật chất và năng lượng, thuyết tiến hoá của Đác-uyn, bảng tuần hoàn của Men-đê-lê-ép, vắc-xin của Pa-xtơ.","Kĩ thuật: điện được ứng dụng rộng rãi; điện tín, điện thoại, đèn điện ra đời; giao thông có xe lửa, tàu thuỷ, ô tô."]],["2. Khoa học xã hội",["Xuất hiện chủ nghĩa duy vật, phép biện chứng; kinh tế chính trị học tư sản.","Chủ nghĩa xã hội không tưởng (Xanh Xi-mông, Phu-ri-ê, Ô-oen) và chủ nghĩa xã hội khoa học của Mác – Ăng-ghen."]],["3. Văn học, nghệ thuật",["Văn học: nhiều tác giả lớn như V. Huy-gô (Pháp), L. Tôn-xtôi (Nga), M. Tuên (Mỹ) phản ánh hiện thực xã hội.","Âm nhạc, hội hoạ: Mô-da, Bét-tô-ven, Sô-panh; các danh hoạ trường phái ấn tượng.","Ý nghĩa: thúc đẩy sản xuất, làm thay đổi đời sống con người và góp phần vào cuộc đấu tranh chống phong kiến, bất công xã hội."]]],"nho":["Thuyết tiến hoá (Đác-uyn), bảng tuần hoàn (Men-đê-lê-ép), vắc-xin (Pa-xtơ).","Điện, điện tín, điện thoại, đèn điện làm thay đổi đời sống.","Văn học, nghệ thuật phản ánh hiện thực và đề cao con người."],"hoi":["Kể tên một số thành tựu khoa học tự nhiên thế kỉ XVIII – XIX.","Những phát minh kĩ thuật đã làm thay đổi đời sống con người như thế nào?","Giới thiệu một tác giả văn học hoặc nghệ sĩ tiêu biểu thời kì này."]},{"so":14,"chuong":"Chương 6. Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","ten":"Trung Quốc và Nhật Bản từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","trang":[62,66],"nam":1868,"tom":"Trung Quốc dần trở thành nửa thuộc địa; Nhật Bản tiến hành Duy tân Minh Trị (1868) và trở thành nước đế quốc.","muc":[["1. Trung Quốc",["Sau Chiến tranh thuốc phiện (1840 – 1842), các nước đế quốc tranh nhau xâu xé, Trung Quốc dần trở thành nước nửa thuộc địa, nửa phong kiến.","Nhân dân đấu tranh mạnh mẽ: phong trào Thái bình Thiên quốc (1851 – 1864), cuộc vận động Duy tân (1898), phong trào Nghĩa Hoà đoàn.","Năm 1905, Tôn Trung Sơn thành lập Trung Quốc Đồng minh hội; Cách mạng Tân Hợi (1911) lật đổ triều Mãn Thanh, Trung Hoa Dân quốc ra đời."]],["2. Nhật Bản",["Giữa thế kỉ XIX, Nhật Bản đứng trước nguy cơ bị phương Tây xâm lược; năm 1868, Thiên hoàng Minh Trị tiến hành cải cách (Duy tân Minh Trị) trên mọi lĩnh vực.","Nhờ cải cách, Nhật Bản phát triển thành nước tư bản công nghiệp, rồi chuyển sang chủ nghĩa đế quốc, gây chiến tranh với Trung Quốc (1894 – 1895) và Nga (1904 – 1905)."]]],"nho":["1840 – 1842: Chiến tranh thuốc phiện; Trung Quốc thành nước nửa thuộc địa.","1911: Cách mạng Tân Hợi do Tôn Trung Sơn lãnh đạo.","1868: Duy tân Minh Trị đưa Nhật Bản phát triển."],"hoi":["Vì sao Trung Quốc trở thành nước nửa thuộc địa, nửa phong kiến?","Trình bày ý nghĩa của Cách mạng Tân Hợi.","Nêu nội dung và kết quả của cuộc Duy tân Minh Trị."]},{"so":15,"chuong":"Chương 6. Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","ten":"Ấn Độ và Đông Nam Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","trang":[67,70],"nam":null,"tom":"Ấn Độ và hầu hết các nước Đông Nam Á bị thực dân cai trị; phong trào đấu tranh giải phóng dân tộc lan rộng.","muc":[["1. Ấn Độ",["Giữa thế kỉ XIX, Anh hoàn thành xâm lược và đặt ách cai trị trực tiếp ở Ấn Độ, vơ vét tài nguyên, kìm hãm kinh tế.","Năm 1857 – 1859, khởi nghĩa Xi-pay bùng nổ; năm 1885, Đảng Quốc đại thành lập, lãnh đạo phong trào đấu tranh của nhân dân."]],["2. Đông Nam Á",["Cuối thế kỉ XIX, các nước thực dân hoàn thành xâm lược Đông Nam Á; riêng Xiêm giữ được độc lập nhờ cải cách của vua Ra-ma V và chính sách ngoại giao mềm dẻo.","Chính quyền thực dân áp đặt bộ máy cai trị, khai thác thuộc địa, làm biến đổi kinh tế – xã hội.","Phong trào đấu tranh phát triển: ở In-đô-nê-xi-a, Phi-líp-pin (cách mạng 1896), Cam-pu-chia, Lào, Mi-an-ma…"]]],"nho":["1857 – 1859: khởi nghĩa Xi-pay; 1885: Đảng Quốc đại Ấn Độ.","Xiêm là nước duy nhất ở Đông Nam Á giữ được độc lập.","Phong trào giải phóng dân tộc ở Đông Nam Á phát triển mạnh."],"hoi":["Trình bày phong trào đấu tranh của nhân dân Ấn Độ cuối thế kỉ XIX – đầu thế kỉ XX.","Vì sao Xiêm giữ được độc lập?","Kể tên một số cuộc đấu tranh tiêu biểu ở Đông Nam Á."]},{"so":16,"chuong":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","ten":"Việt Nam dưới thời Nguyễn (nửa đầu thế kỉ XIX)","trang":[71,76],"nam":1802,"tom":"Năm 1802, nhà Nguyễn thành lập, xây dựng bộ máy nhà nước, kinh tế, văn hoá và thực thi chủ quyền biển đảo.","muc":[["1. Chính trị",["Năm 1802, Nguyễn Ánh lên ngôi (Gia Long), lập nhà Nguyễn, đóng đô ở Phú Xuân (Huế); năm 1804 đặt quốc hiệu Việt Nam, đến thời Minh Mạng đổi là Đại Nam.","Bộ máy nhà nước quân chủ tập quyền được củng cố; vua Minh Mạng cải cách hành chính (1831 – 1832), chia cả nước thành 30 tỉnh và phủ Thừa Thiên.","Ban hành bộ Hoàng Việt luật lệ; đối ngoại thận trọng, thực hiện chính sách đóng cửa với phương Tây."]],["2. Kinh tế và xã hội",["Nông nghiệp: khuyến khích khai hoang, lập ấp doanh điền (Nguyễn Công Trứ); nhưng đê điều không được chăm lo, mất mùa đói kém nhiều.","Thủ công, thương nghiệp có phát triển nhưng bị hạn chế bởi chính sách “bế quan toả cảng”.","Đời sống nhân dân khó khăn dẫn tới nhiều cuộc khởi nghĩa: Phan Bá Vành, Nông Văn Vân, Lê Văn Khôi, Cao Bá Quát…"]],["3. Văn hoá và chủ quyền biển đảo",["Nho giáo được đề cao; lập Quốc sử quán biên soạn nhiều bộ sử; văn học có Truyện Kiều của Nguyễn Du; kinh thành Huế là công trình kiến trúc lớn.","Nhà Nguyễn tiếp tục thực thi chủ quyền ở Hoàng Sa, Trường Sa: cử thuỷ quân ra đo đạc, cắm mốc, dựng bia, vẽ bản đồ."]]],"nho":["1802: nhà Nguyễn thành lập; 1804: quốc hiệu Việt Nam.","Cải cách Minh Mạng: 30 tỉnh và phủ Thừa Thiên.","Nhà Nguyễn thực thi chủ quyền ở Hoàng Sa, Trường Sa."],"hoi":["Trình bày những nét chính về chính trị thời Nguyễn nửa đầu thế kỉ XIX.","Vì sao dưới thời Nguyễn nhiều cuộc khởi nghĩa nông dân nổ ra?","Nhà Nguyễn đã thực thi chủ quyền ở Hoàng Sa, Trường Sa như thế nào?"]},{"so":17,"chuong":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","ten":"Cuộc kháng chiến chống thực dân Pháp xâm lược từ năm 1858 đến năm 1884","trang":[77,83],"nam":1858,"tom":"Năm 1858, Pháp nổ súng xâm lược; triều Nguyễn lần lượt kí các hiệp ước, nhân dân kiên cường kháng chiến.","muc":[["1. Pháp xâm lược và quá trình mất ba tỉnh miền Đông, ba tỉnh miền Tây Nam Kỳ",["Ngày 1/9/1858, liên quân Pháp – Tây Ban Nha nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược; nhân dân và quân triều đình chống trả quyết liệt.","Năm 1859, Pháp đánh Gia Định; năm 1862 triều đình kí Hiệp ước Nhâm Tuất nhượng ba tỉnh miền Đông Nam Kỳ; năm 1867 Pháp chiếm nốt ba tỉnh miền Tây.","Nhân dân Nam Kỳ kháng chiến kiên cường: Trương Định, Nguyễn Trung Trực, Nguyễn Hữu Huân…"]],["2. Pháp đánh Bắc Kỳ và triều đình đầu hàng",["Năm 1873, Pháp đánh Bắc Kỳ lần thứ nhất; quân ta thắng trận Cầu Giấy (1873); triều đình kí Hiệp ước 1874.","Năm 1882, Pháp đánh Bắc Kỳ lần thứ hai; trận Cầu Giấy lần thứ hai (1883) Ri-vi-e bị giết.","Năm 1883 và 1884, triều đình kí Hiệp ước Hác-măng và Pa-tơ-nốt, chính thức thừa nhận sự bảo hộ của Pháp; Việt Nam trở thành thuộc địa."]]],"nho":["1/9/1858: Pháp tấn công Đà Nẵng.","1862: Hiệp ước Nhâm Tuất; 1874: Hiệp ước Giáp Tuất.","1883 – 1884: Hiệp ước Hác-măng, Pa-tơ-nốt, Việt Nam thành thuộc địa."],"hoi":["Trình bày quá trình Pháp xâm lược Nam Kỳ.","Nêu những trận đánh tiêu biểu của nhân dân ta chống Pháp ở Bắc Kỳ.","Vì sao Việt Nam rơi vào tay thực dân Pháp?"]},{"so":18,"chuong":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","ten":"Phong trào chống Pháp trong những năm 1885 – 1896","trang":[84,87],"nam":1885,"tom":"Phong trào Cần vương và các cuộc khởi nghĩa tự phát chống Pháp cuối thế kỉ XIX.","muc":[["1. Phong trào Cần vương (1885 – 1896)",["Đêm 4 rạng sáng 5/7/1885, phái chủ chiến do Tôn Thất Thuyết đứng đầu tấn công quân Pháp ở kinh thành Huế nhưng thất bại.","Tôn Thất Thuyết đưa vua Hàm Nghi ra Tân Sở (Quảng Trị), ngày 13/7/1885 ban Chiếu Cần vương kêu gọi nhân dân giúp vua cứu nước.","Khởi nghĩa tiêu biểu: Ba Đình (1886 – 1887, Phạm Bành, Đinh Công Tráng), Bãi Sậy (1883 – 1892, Nguyễn Thiện Thuật), Hương Khê (1885 – 1896, Phan Đình Phùng, Cao Thắng) – cuộc khởi nghĩa lớn nhất."]],["2. Khởi nghĩa Yên Thế và các cuộc đấu tranh khác",["Khởi nghĩa nông dân Yên Thế (1884 – 1913) do Hoàng Hoa Thám lãnh đạo, kéo dài gần 30 năm, mang tính tự phát.","Đồng bào các dân tộc miền núi cũng nổi dậy chống Pháp ở nhiều nơi."]],["3. Ý nghĩa",["Các phong trào thể hiện tinh thần yêu nước, ý chí bất khuất của nhân dân, gây cho Pháp nhiều tổn thất.","Thất bại của phong trào Cần vương cho thấy ngọn cờ phong kiến không còn phù hợp để cứu nước."]]],"nho":["13/7/1885: Chiếu Cần vương.","Khởi nghĩa Hương Khê (1885 – 1896) là tiêu biểu nhất.","Khởi nghĩa Yên Thế (1884 – 1913) do Hoàng Hoa Thám lãnh đạo."],"hoi":["Phong trào Cần vương bùng nổ trong hoàn cảnh nào?","Lập bảng các cuộc khởi nghĩa tiêu biểu cuối thế kỉ XIX.","Vì sao các phong trào chống Pháp cuối thế kỉ XIX thất bại?"]},{"so":19,"chuong":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","ten":"Phong trào yêu nước chống Pháp ở Việt Nam từ đầu thế kỉ XX đến năm 1917","trang":[88,92],"nam":1905,"tom":"Các phong trào yêu nước theo khuynh hướng mới; Nguyễn Tất Thành ra đi tìm đường cứu nước (1911).","muc":[["1. Những chuyển biến về kinh tế, xã hội",["Thực dân Pháp tiến hành khai thác thuộc địa lần thứ nhất (1897 – 1914): khai mỏ, lập đồn điền, xây dựng đường sắt, bến cảng.","Xã hội phân hoá: xuất hiện tầng lớp tư sản, tiểu tư sản và giai cấp công nhân; tư tưởng dân chủ tư sản từ bên ngoài truyền vào."]],["2. Phong trào yêu nước theo khuynh hướng mới",["Phan Bội Châu lập Duy tân hội (1904), tổ chức phong trào Đông du (1905 – 1908) đưa thanh niên sang Nhật học; năm 1912 lập Việt Nam Quang phục hội.","Phan Châu Trinh chủ trương cải cách, nâng cao dân trí, dân quyền, khởi xướng cuộc vận động Duy tân ở Trung Kỳ; năm 1908 bùng nổ phong trào chống thuế.","Năm 1907, Đông Kinh nghĩa thục mở trường học, cổ động văn hoá mới ở Hà Nội."]],["3. Nguyễn Tất Thành ra đi tìm đường cứu nước",["Ngày 5/6/1911, Nguyễn Tất Thành rời bến cảng Nhà Rồng, sang phương Tây tìm đường cứu nước.","Đây là sự kiện mở đầu hành trình tìm ra con đường giải phóng dân tộc mới."]]],"nho":["1897 – 1914: khai thác thuộc địa lần thứ nhất.","Phan Bội Châu – Đông du; Phan Châu Trinh – Duy tân; Đông Kinh nghĩa thục 1907.","5/6/1911: Nguyễn Tất Thành ra đi tìm đường cứu nước."],"hoi":["Cuộc khai thác thuộc địa lần thứ nhất làm xã hội Việt Nam biến đổi thế nào?","So sánh chủ trương cứu nước của Phan Bội Châu và Phan Châu Trinh.","Sự kiện ngày 5/6/1911 có ý nghĩa gì?"]},{"so":"CĐ1","chuong":"Chủ đề chung","ten":"Văn minh châu thổ sông Hồng và sông Cửu Long","trang":[155,161],"nam":null,"tom":"Chủ đề tích hợp về quá trình hình thành và những đặc trưng văn minh của hai vùng châu thổ lớn.","muc":[["1. Văn minh châu thổ sông Hồng",["Cư dân Việt cổ khai phá đồng bằng sông Hồng từ rất sớm, gắn với các nền văn hoá Phùng Nguyên, Đồng Đậu, Gò Mun, Đông Sơn.","Thành tựu: trồng lúa nước, hệ thống đê điều trị thuỷ sông Hồng, làng xã, tín ngưỡng và lễ hội nông nghiệp; là cái nôi của văn minh Văn Lang – Âu Lạc và Đại Việt."]],["2. Văn minh châu thổ sông Cửu Long",["Từ đầu Công nguyên, văn hoá Óc Eo và vương quốc Phù Nam phát triển ở đây; từ thế kỉ XVII, cư dân Việt cùng người Khơ-me, Hoa, Chăm khai phá mạnh mẽ.","Thành tựu: nông nghiệp lúa nước, hệ thống kênh rạch, văn hoá sông nước, chợ nổi, sự giao thoa văn hoá nhiều tộc người."]],["3. Ý nghĩa",["Hai vùng châu thổ là trung tâm kinh tế, văn hoá quan trọng của đất nước.","Hiểu về văn minh châu thổ giúp ta có ý thức gìn giữ, phát huy giá trị di sản và ứng phó với biến đổi khí hậu."]]],"nho":["Sông Hồng: đê điều, làng xã, văn minh Văn Lang – Âu Lạc, Đại Việt.","Cửu Long: văn hoá Óc Eo, kênh rạch, văn hoá sông nước."],"hoi":["Nêu những thành tựu tiêu biểu của văn minh châu thổ sông Hồng.","Văn minh châu thổ sông Cửu Long có những nét đặc trưng nào?","Em có thể làm gì để góp phần gìn giữ giá trị văn minh châu thổ?"]},{"so":"CĐ2","chuong":"Chủ đề chung","ten":"Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","trang":[162,171],"nam":null,"tom":"Chủ đề tích hợp về vị trí của Biển Đông và quá trình xác lập, thực thi chủ quyền của Việt Nam.","muc":[["1. Vị trí của Biển Đông",["Biển Đông là biển lớn, nằm trên tuyến hàng hải quốc tế quan trọng nối Thái Bình Dương và Ấn Độ Dương.","Việt Nam có vùng biển rộng với nhiều đảo, quần đảo, trong đó có hai quần đảo Hoàng Sa và Trường Sa."]],["2. Quá trình xác lập và thực thi chủ quyền",["Từ thế kỉ XVII, các chúa Nguyễn lập đội Hoàng Sa, đội Bắc Hải khai thác và quản lí các quần đảo.","Triều Nguyễn tiếp tục đo đạc, cắm mốc, dựng bia, vẽ bản đồ; các nhà nước Việt Nam sau này kế tục thực thi chủ quyền."]],["3. Bảo vệ chủ quyền, quyền và lợi ích hợp pháp",["Việt Nam giải quyết tranh chấp bằng biện pháp hoà bình, trên cơ sở luật pháp quốc tế, nhất là Công ước của Liên hợp quốc về Luật Biển năm 1982.","Mỗi công dân cần hiểu biết lịch sử, có ý thức bảo vệ chủ quyền biển đảo của Tổ quốc."]]],"nho":["Biển Đông có vị trí chiến lược trên tuyến hàng hải quốc tế.","Đội Hoàng Sa, đội Bắc Hải là bằng chứng lịch sử về chủ quyền.","Giải quyết tranh chấp bằng hoà bình, theo Công ước Luật Biển 1982."],"hoi":["Vì sao Biển Đông có vị trí quan trọng?","Trình bày quá trình xác lập chủ quyền của Việt Nam ở Hoàng Sa, Trường Sa.","Học sinh có thể làm gì để góp phần bảo vệ chủ quyền biển đảo?"]}]},"9":{"sach":"Lịch sử và Địa lí 9 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 6–115 và ba chủ đề chung tr. 221–235","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Thế giới từ năm 1918 đến năm 1945","ten":"Nước Nga và Liên Xô từ năm 1918 đến năm 1945","trang":[7,9],"nam":1922,"tom":"Nước Nga Xô viết bảo vệ chính quyền, Liên Xô thành lập (1922) và xây dựng chủ nghĩa xã hội.","muc":[["1. Nước Nga Xô viết trong những năm 1918 – 1922",["Sau Cách mạng tháng Mười, nước Nga Xô viết phải đối phó với nội chiến và sự can thiệp của 14 nước đế quốc; chính quyền thực hiện Chính sách cộng sản thời chiến.","Năm 1921, chuyển sang Chính sách kinh tế mới (NEP), khôi phục kinh tế sau chiến tranh.","Tháng 12/1922, Liên bang Cộng hoà xã hội chủ nghĩa Xô viết (Liên Xô) được thành lập."]],["2. Liên Xô xây dựng chủ nghĩa xã hội (1922 – 1941)",["Tiến hành công nghiệp hoá xã hội chủ nghĩa, tập thể hoá nông nghiệp; thực hiện các kế hoạch 5 năm.","Từ một nước nông nghiệp lạc hậu, Liên Xô trở thành cường quốc công nghiệp; văn hoá, giáo dục phát triển, xoá nạn mù chữ.","Bên cạnh thành tựu, việc xây dựng có những sai lầm, hạn chế."]]],"nho":["1921: Chính sách kinh tế mới (NEP).","12/1922: Liên Xô thành lập.","Công nghiệp hoá giúp Liên Xô trở thành cường quốc công nghiệp."],"hoi":["Nước Nga Xô viết đã vượt qua khó khăn những năm 1918 – 1922 như thế nào?","Nêu những thành tựu của Liên Xô trong xây dựng chủ nghĩa xã hội (1922 – 1941).","Vì sao Liên Xô được thành lập?"]},{"so":2,"chuong":"Chương 1. Thế giới từ năm 1918 đến năm 1945","ten":"Châu Âu và nước Mỹ từ năm 1918 đến năm 1945","trang":[10,13],"nam":1929,"tom":"Thời kì ổn định ngắn rồi khủng hoảng kinh tế 1929 – 1933; chủ nghĩa phát xít lên nắm quyền ở một số nước.","muc":[["1. Châu Âu từ năm 1918 đến năm 1945",["Sau Chiến tranh thế giới thứ nhất, cao trào cách mạng bùng nổ ở nhiều nước; Quốc tế Cộng sản thành lập (1919).","Những năm 1924 – 1929, các nước tư bản ổn định và phát triển; cuộc khủng hoảng kinh tế 1929 – 1933 gây hậu quả nặng nề.","Để thoát khủng hoảng, Đức, I-ta-li-a, Nhật Bản đi theo con đường phát xít hoá; Anh, Pháp cải cách kinh tế – xã hội. Mặt trận nhân dân Pháp chống phát xít ra đời."]],["2. Nước Mỹ từ năm 1918 đến năm 1945",["Những năm 1920, kinh tế Mỹ phát triển phồn vinh, đứng đầu thế giới.","Khủng hoảng 1929 – 1933 làm kinh tế Mỹ suy sụp; Tổng thống Ru-dơ-ven thực hiện Chính sách mới, giúp nước Mỹ vượt qua khủng hoảng."]]],"nho":["1929 – 1933: khủng hoảng kinh tế thế giới.","Đức, I-ta-li-a đi theo con đường phát xít.","Chính sách mới của Ru-dơ-ven giúp Mỹ thoát khủng hoảng."],"hoi":["Cuộc khủng hoảng kinh tế 1929 – 1933 tác động thế nào đến các nước tư bản?","Vì sao chủ nghĩa phát xít lên cầm quyền ở Đức?","Trình bày nội dung chính của Chính sách mới ở Mỹ."]},{"so":3,"chuong":"Chương 1. Thế giới từ năm 1918 đến năm 1945","ten":"Châu Á từ năm 1918 đến năm 1945","trang":[14,17],"nam":null,"tom":"Phong trào độc lập dân tộc ở châu Á phát triển; Nhật Bản đi theo con đường quân phiệt.","muc":[["1. Nhật Bản",["Sau chiến tranh, kinh tế Nhật phát triển nhưng không ổn định; khủng hoảng 1929 – 1933 làm kinh tế suy sụp.","Nhật Bản quân phiệt hoá bộ máy nhà nước, gây chiến tranh xâm lược Trung Quốc (1931, 1937), hình thành lò lửa chiến tranh ở châu Á."]],["2. Trung Quốc",["Phong trào Ngũ tứ (1919) mở đầu cao trào chống đế quốc, phong kiến; năm 1921, Đảng Cộng sản Trung Quốc thành lập.","Nhân dân Trung Quốc kháng chiến chống Nhật (1937 – 1945) trong mặt trận dân tộc thống nhất."]],["3. Ấn Độ và Đông Nam Á",["Ở Ấn Độ, phong trào đấu tranh do Đảng Quốc đại và M. Gan-đi lãnh đạo phát triển mạnh.","Ở Đông Nam Á, phong trào độc lập dân tộc lan rộng; nhiều đảng cộng sản ra đời; trong Chiến tranh thế giới thứ hai, nhân dân đấu tranh chống phát xít Nhật."]]],"nho":["1919: phong trào Ngũ tứ; 1921: Đảng Cộng sản Trung Quốc ra đời.","Nhật Bản trở thành lò lửa chiến tranh ở châu Á.","Phong trào độc lập dân tộc lan rộng ở Ấn Độ, Đông Nam Á."],"hoi":["Vì sao Nhật Bản đi theo con đường quân phiệt hoá?","Trình bày phong trào cách mạng ở Trung Quốc từ năm 1919 đến năm 1945.","Nêu những nét chính của phong trào độc lập ở Đông Nam Á thời kì này."]},{"so":4,"chuong":"Chương 1. Thế giới từ năm 1918 đến năm 1945","ten":"Chiến tranh thế giới thứ hai (1939 – 1945)","trang":[18,21],"nam":1939,"tom":"Cuộc chiến tranh lớn nhất lịch sử nhân loại, kết thúc với thắng lợi của phe Đồng minh chống phát xít.","muc":[["1. Nguyên nhân",["Mâu thuẫn giữa các nước đế quốc về thị trường, thuộc địa ngày càng gay gắt sau khủng hoảng 1929 – 1933.","Các nước phát xít Đức, I-ta-li-a, Nhật Bản liên kết, đẩy mạnh xâm lược; chính sách nhượng bộ của Anh, Pháp tạo điều kiện cho phát xít."]],["2. Diễn biến chính",["Ngày 1/9/1939, Đức tấn công Ba Lan, chiến tranh bùng nổ; Đức lần lượt chiếm phần lớn châu Âu.","Tháng 6/1941, Đức tấn công Liên Xô; tháng 12/1941, Nhật tấn công Trân Châu Cảng, Mỹ tham chiến; khối Đồng minh chống phát xít hình thành.","Chiến thắng Xta-lin-grát (1942 – 1943) tạo bước ngoặt; năm 1944 Đồng minh mở mặt trận thứ hai ở Pháp.","Ngày 9/5/1945, Đức đầu hàng; tháng 8/1945, Mỹ ném bom nguyên tử xuống Hi-rô-si-ma, Na-ga-xa-ki, Liên Xô đánh tan đạo quân Quan Đông; ngày 15/8/1945 Nhật đầu hàng."]],["3. Kết cục và tác động",["Chủ nghĩa phát xít bị tiêu diệt; Liên Xô, Mỹ, Anh là những lực lượng trụ cột đánh thắng phát xít.","Chiến tranh làm khoảng 60 triệu người chết, thiệt hại vật chất to lớn; mở ra điều kiện cho phong trào giải phóng dân tộc, trong đó có Việt Nam."]]],"nho":["1/9/1939: Đức tấn công Ba Lan, chiến tranh bùng nổ.","Xta-lin-grát (1942 – 1943) là bước ngoặt của chiến tranh.","9/5/1945: Đức đầu hàng; 15/8/1945: Nhật đầu hàng."],"hoi":["Trình bày nguyên nhân bùng nổ Chiến tranh thế giới thứ hai.","Nêu những sự kiện tiêu biểu trong diễn biến chiến tranh.","Chiến tranh thế giới thứ hai kết thúc tác động thế nào đến Việt Nam?"]},{"so":5,"chuong":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","ten":"Phong trào dân tộc dân chủ trong những năm 1918 – 1930","trang":[22,25],"nam":null,"tom":"Sau Chiến tranh thế giới thứ nhất, các phong trào yêu nước của nhiều giai tầng phát triển mạnh.","muc":[["1. Những chuyển biến kinh tế, xã hội",["Sau Chiến tranh thế giới thứ nhất, Pháp tiến hành khai thác thuộc địa lần thứ hai (1919 – 1929) với quy mô lớn, đầu tư mạnh vào đồn điền cao su, khai mỏ.","Xã hội phân hoá sâu sắc: giai cấp công nhân phát triển, tư sản dân tộc và tiểu tư sản tăng lên; mâu thuẫn dân tộc trở nên gay gắt."]],["2. Phong trào dân tộc dân chủ",["Tư sản dân tộc chống độc quyền cảng Sài Gòn, lập Đảng Lập hiến; tiểu tư sản đấu tranh đòi thả Phan Bội Châu (1925), để tang Phan Châu Trinh (1926).","Phong trào công nhân chuyển từ tự phát sang tự giác, tiêu biểu là cuộc bãi công của thợ máy xưởng Ba Son (1925).","Năm 1927, Việt Nam Quốc dân đảng ra đời; khởi nghĩa Yên Bái (2/1930) thất bại."]]],"nho":["1919 – 1929: khai thác thuộc địa lần thứ hai.","1925: bãi công Ba Son; phong trào đòi thả Phan Bội Châu.","1930: khởi nghĩa Yên Bái của Việt Nam Quốc dân đảng."],"hoi":["Cuộc khai thác thuộc địa lần thứ hai làm xã hội Việt Nam biến đổi như thế nào?","Nêu những phong trào đấu tranh tiêu biểu những năm 1918 – 1930.","Vì sao khởi nghĩa Yên Bái thất bại?"]},{"so":6,"chuong":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","ten":"Hoạt động của Nguyễn Ái Quốc và sự thành lập Đảng Cộng sản Việt Nam","trang":[26,29],"nam":1930,"tom":"Nguyễn Ái Quốc tìm ra con đường cứu nước, chuẩn bị về tư tưởng, tổ chức và thành lập Đảng Cộng sản Việt Nam (1930).","muc":[["1. Nguyễn Ái Quốc tìm đường cứu nước",["Năm 1919, Nguyễn Ái Quốc gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Véc-xai.","Năm 1920, đọc Luận cương của Lê-nin về vấn đề dân tộc và thuộc địa, Người tìm thấy con đường cứu nước theo cách mạng vô sản; tham gia sáng lập Đảng Cộng sản Pháp."]],["2. Chuẩn bị về tư tưởng và tổ chức",["Người viết báo Người cùng khổ, tác phẩm Bản án chế độ thực dân Pháp, truyền bá chủ nghĩa Mác – Lê-nin về nước.","Năm 1925, Người thành lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu, mở lớp huấn luyện cán bộ; tác phẩm Đường Kách mệnh (1927)."]],["3. Thành lập Đảng Cộng sản Việt Nam",["Năm 1929, ba tổ chức cộng sản ra đời ở Việt Nam.","Đầu năm 1930, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất ở Hương Cảng, thành lập Đảng Cộng sản Việt Nam, thông qua Cương lĩnh chính trị đầu tiên.","Ý nghĩa: bước ngoặt vĩ đại của cách mạng Việt Nam, chấm dứt khủng hoảng về đường lối cứu nước."]]],"nho":["1920: Nguyễn Ái Quốc tìm thấy con đường cứu nước.","1925: Hội Việt Nam Cách mạng Thanh niên.","Đầu năm 1930: Đảng Cộng sản Việt Nam thành lập."],"hoi":["Trình bày quá trình Nguyễn Ái Quốc tìm ra con đường cứu nước.","Nguyễn Ái Quốc chuẩn bị về tư tưởng và tổ chức cho việc thành lập Đảng như thế nào?","Việc thành lập Đảng Cộng sản Việt Nam có ý nghĩa gì?"]},{"so":7,"chuong":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","ten":"Phong trào cách mạng Việt Nam thời kì 1930 – 1939","trang":[30,33],"nam":1930,"tom":"Phong trào cách mạng 1930 – 1931, cuộc vận động dân chủ 1936 – 1939 dưới sự lãnh đạo của Đảng.","muc":[["1. Phong trào cách mạng 1930 – 1931",["Khủng hoảng kinh tế và chính sách khủng bố của Pháp làm đời sống nhân dân cực khổ; Đảng ra đời lãnh đạo phong trào.","Phong trào lên cao ở Nghệ An, Hà Tĩnh; chính quyền Xô viết ra đời ở nhiều làng, thực hiện nhiều chính sách tiến bộ.","Tháng 10/1930, Hội nghị Ban Chấp hành Trung ương đổi tên Đảng thành Đảng Cộng sản Đông Dương, thông qua Luận cương chính trị."]],["2. Phong trào dân chủ 1936 – 1939",["Bối cảnh: chủ nghĩa phát xít đe doạ hoà bình thế giới; Mặt trận nhân dân Pháp lên cầm quyền.","Đảng chủ trương đấu tranh đòi tự do, dân chủ, cơm áo, hoà bình; lập Mặt trận Dân chủ Đông Dương; hình thức đấu tranh công khai, hợp pháp kết hợp bí mật.","Ý nghĩa: quần chúng được giác ngộ, đội quân chính trị đông đảo hình thành; là cuộc tập dượt cho Cách mạng tháng Tám."]]],"nho":["1930 – 1931: phong trào cách mạng, đỉnh cao là Xô viết Nghệ – Tĩnh.","10/1930: Đảng Cộng sản Đông Dương, Luận cương chính trị.","1936 – 1939: phong trào dân chủ, cuộc tập dượt thứ hai."],"hoi":["Vì sao phong trào cách mạng 1930 – 1931 bùng nổ?","Xô viết Nghệ – Tĩnh đã thực hiện những chính sách gì?","So sánh phong trào 1930 – 1931 với phong trào 1936 – 1939."]},{"so":8,"chuong":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","ten":"Cách mạng tháng Tám năm 1945","trang":[34,40],"nam":1945,"tom":"Tổng khởi nghĩa giành chính quyền trong cả nước; ngày 2/9/1945 nước Việt Nam Dân chủ Cộng hoà ra đời.","muc":[["1. Chuẩn bị cho Tổng khởi nghĩa",["Năm 1940, Nhật vào Đông Dương; nhân dân chịu cảnh “một cổ hai tròng”.","Năm 1941, Nguyễn Ái Quốc về nước, chủ trì Hội nghị Trung ương 8, thành lập Mặt trận Việt Minh; xây dựng lực lượng chính trị, vũ trang, căn cứ địa.","Ngày 9/3/1945, Nhật đảo chính Pháp; Đảng phát động cao trào kháng Nhật cứu nước, phong trào phá kho thóc giải quyết nạn đói."]],["2. Tổng khởi nghĩa tháng Tám năm 1945",["Ngày 15/8/1945, Nhật đầu hàng Đồng minh; Hội nghị toàn quốc của Đảng và Quốc dân Đại hội Tân Trào quyết định Tổng khởi nghĩa.","Khởi nghĩa giành thắng lợi ở Hà Nội (19/8), Huế (23/8), Sài Gòn (25/8), trong vòng 15 ngày giành chính quyền cả nước.","Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hoà."]],["3. Nguyên nhân thắng lợi và ý nghĩa",["Truyền thống yêu nước; sự lãnh đạo đúng đắn của Đảng, Chủ tịch Hồ Chí Minh; sự chuẩn bị chu đáo; thời cơ thuận lợi.","Phá tan xiềng xích thực dân, phong kiến; mở ra kỉ nguyên độc lập, tự do cho dân tộc."]]],"nho":["1941: Mặt trận Việt Minh thành lập.","19/8/1945: khởi nghĩa thắng lợi ở Hà Nội.","2/9/1945: Tuyên ngôn Độc lập, nước Việt Nam Dân chủ Cộng hoà ra đời."],"hoi":["Trình bày quá trình chuẩn bị cho Tổng khởi nghĩa tháng Tám.","Vì sao nói Cách mạng tháng Tám đã nổ ra đúng thời cơ?","Nêu ý nghĩa lịch sử của Cách mạng tháng Tám năm 1945."]},{"so":9,"chuong":"Chương 3. Thế giới từ năm 1945 đến năm 1991","ten":"Chiến tranh lạnh (1947 – 1989)","trang":[41,43],"nam":1947,"tom":"Cuộc đối đầu căng thẳng giữa hai phe do Mỹ và Liên Xô đứng đầu, chi phối quan hệ quốc tế hơn bốn thập kỉ.","muc":[["1. Nguồn gốc của Chiến tranh lạnh",["Sau Chiến tranh thế giới thứ hai, Mỹ và Liên Xô từ đồng minh trở thành đối đầu do khác biệt về mục tiêu, chế độ chính trị.","Năm 1947, học thuyết Tru-man được công bố, mở đầu Chiến tranh lạnh."]],["2. Biểu hiện",["Hai phe chạy đua vũ trang, thành lập các khối quân sự đối lập: NATO (1949) và Tổ chức Hiệp ước Vác-sa-va (1955).","Các cuộc khủng hoảng, chiến tranh cục bộ ở nhiều nơi: chia cắt nước Đức, chiến tranh Triều Tiên, khủng hoảng Ca-ri-bê, chiến tranh Việt Nam."]],["3. Kết thúc và hậu quả",["Tháng 12/1989, Mỹ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh.","Thế giới luôn trong tình trạng căng thẳng; chi phí quân sự khổng lồ làm suy yếu nhiều nước."]]],"nho":["1947: học thuyết Tru-man, Chiến tranh lạnh bắt đầu.","NATO (1949) và Vác-sa-va (1955) đối đầu.","12/1989: Mỹ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh."],"hoi":["Vì sao Chiến tranh lạnh xảy ra?","Nêu những biểu hiện của Chiến tranh lạnh.","Chiến tranh lạnh tác động thế nào đến thế giới?"]},{"so":10,"chuong":"Chương 3. Thế giới từ năm 1945 đến năm 1991","ten":"Liên Xô và Đông Âu từ năm 1945 đến năm 1991","trang":[44,48],"nam":null,"tom":"Liên Xô và các nước Đông Âu xây dựng chủ nghĩa xã hội, đạt nhiều thành tựu rồi khủng hoảng và sụp đổ.","muc":[["1. Liên Xô từ năm 1945 đến năm 1991",["Liên Xô khôi phục kinh tế sau chiến tranh, trở thành cường quốc công nghiệp; năm 1957 phóng vệ tinh nhân tạo đầu tiên, năm 1961 đưa người bay vào vũ trụ.","Từ những năm 70, kinh tế trì trệ, khủng hoảng; công cuộc cải tổ (1985) không thành công.","Tháng 12/1991, Liên Xô tan rã."]],["2. Các nước Đông Âu",["Sau năm 1945, các nhà nước dân chủ nhân dân ra đời, tiến hành xây dựng chủ nghĩa xã hội và đạt nhiều thành tựu.","Cuối những năm 80, khủng hoảng toàn diện; chế độ xã hội chủ nghĩa ở Đông Âu sụp đổ (1989 – 1991)."]],["3. Nguyên nhân sụp đổ",["Mô hình xây dựng có nhiều sai lầm, chậm sửa đổi; không theo kịp cách mạng khoa học – kĩ thuật.","Cải tổ mắc sai lầm; sự chống phá của các thế lực bên ngoài."]]],"nho":["1957: vệ tinh nhân tạo đầu tiên; 1961: Ga-ga-rin bay vào vũ trụ.","1989 – 1991: chế độ xã hội chủ nghĩa ở Đông Âu sụp đổ.","12/1991: Liên Xô tan rã."],"hoi":["Nêu những thành tựu của Liên Xô sau năm 1945.","Trình bày nguyên nhân sụp đổ của Liên Xô và Đông Âu.","Rút ra bài học từ sự sụp đổ của Liên Xô và Đông Âu."]},{"so":11,"chuong":"Chương 3. Thế giới từ năm 1945 đến năm 1991","ten":"Nước Mỹ và Tây Âu từ năm 1945 đến năm 1991","trang":[49,51],"nam":null,"tom":"Mỹ và Tây Âu phục hồi, phát triển kinh tế mạnh mẽ; quá trình liên kết khu vực ở châu Âu.","muc":[["1. Nước Mỹ",["Sau chiến tranh, Mỹ trở thành nước tư bản giàu mạnh nhất, chiếm phần lớn sản lượng công nghiệp thế giới; đi đầu cách mạng khoa học – kĩ thuật.","Đối ngoại: thực hiện chiến lược toàn cầu nhằm làm bá chủ thế giới, can thiệp vào nhiều nước."]],["2. Tây Âu",["Nhờ kế hoạch Mác-san, các nước Tây Âu phục hồi kinh tế, phát triển nhanh từ những năm 50.","Quá trình liên kết khu vực: Cộng đồng châu Âu (EC) rồi Liên minh châu Âu (EU, 1993)."]]],"nho":["Mỹ là nước tư bản giàu mạnh nhất sau 1945.","Kế hoạch Mác-san giúp Tây Âu phục hồi.","Liên kết khu vực châu Âu dẫn tới EU."],"hoi":["Vì sao sau chiến tranh Mỹ trở thành nước giàu mạnh nhất?","Trình bày quá trình liên kết khu vực ở Tây Âu.","Chính sách đối ngoại của Mỹ sau 1945 có mục tiêu gì?"]},{"so":12,"chuong":"Chương 3. Thế giới từ năm 1945 đến năm 1991","ten":"Khu vực Mỹ La-tinh và châu Á từ năm 1945 đến năm 1991","trang":[52,60],"nam":null,"tom":"Phong trào giải phóng dân tộc và công cuộc xây dựng đất nước ở Mỹ La-tinh và châu Á.","muc":[["1. Mỹ La-tinh",["Sau năm 1945, phong trào đấu tranh chống chế độ độc tài thân Mỹ phát triển; cách mạng Cu-ba thắng lợi năm 1959.","Các nước Mỹ La-tinh từng bước củng cố độc lập, xây dựng và phát triển kinh tế."]],["2. Châu Á",["Phong trào giải phóng dân tộc phát triển mạnh, hầu hết các nước giành độc lập; năm 1949 nước Cộng hoà Nhân dân Trung Hoa ra đời.","Nhiều nước Đông Nam Á giành độc lập; ASEAN thành lập năm 1967.","Ấn Độ giành độc lập (1947), Nhật Bản phát triển “thần kì”; Hàn Quốc, Xin-ga-po… trở thành các nền kinh tế phát triển nhanh."]]],"nho":["1959: cách mạng Cu-ba thắng lợi.","1949: nước Cộng hoà Nhân dân Trung Hoa ra đời.","1967: ASEAN thành lập."],"hoi":["Trình bày phong trào đấu tranh ở Mỹ La-tinh sau năm 1945.","Nêu những nét chính về châu Á từ năm 1945 đến năm 1991.","Vì sao nói châu Á có sự phát triển năng động?"]},{"so":13,"chuong":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","ten":"Việt Nam trong năm đầu sau Cách mạng tháng Tám năm 1945","trang":[61,66],"nam":1945,"tom":"Chính quyền non trẻ vượt qua giặc đói, giặc dốt, thù trong giặc ngoài, bảo vệ thành quả cách mạng.","muc":[["1. Tình hình nước ta sau Cách mạng tháng Tám",["Chính quyền non trẻ đứng trước muôn vàn khó khăn: thù trong giặc ngoài, nạn đói, nạn dốt, ngân sách trống rỗng.","Quân Trung Hoa Dân quốc ở miền Bắc, quân Anh mở đường cho Pháp quay lại xâm lược Nam Bộ (23/9/1945)."]],["2. Xây dựng chính quyền và giải quyết khó khăn",["Ngày 6/1/1946, Tổng tuyển cử bầu Quốc hội; Hiến pháp đầu tiên được thông qua (11/1946).","Diệt giặc đói: phong trào tăng gia sản xuất, “Hũ gạo cứu đói”; diệt giặc dốt: Nha Bình dân học vụ, phong trào xoá mù chữ; giải quyết tài chính: “Tuần lễ vàng”, phát hành tiền Việt Nam."]],["3. Đấu tranh chống ngoại xâm",["Nhân dân Nam Bộ kháng chiến chống Pháp từ ngày 23/9/1945.","Sách lược mềm dẻo: hoà hoãn với quân Trung Hoa Dân quốc, rồi kí Hiệp định Sơ bộ (6/3/1946) và Tạm ước (14/9/1946) với Pháp để có thời gian chuẩn bị kháng chiến."]]],"nho":["6/1/1946: Tổng tuyển cử bầu Quốc hội.","Diệt giặc đói, giặc dốt, giải quyết tài chính.","6/3/1946: Hiệp định Sơ bộ; 14/9/1946: Tạm ước."],"hoi":["Vì sao nói nước ta sau Cách mạng tháng Tám ở thế “ngàn cân treo sợi tóc”?","Trình bày những biện pháp xây dựng chính quyền và giải quyết khó khăn.","Việc kí Hiệp định Sơ bộ có ý nghĩa gì?"]},{"so":14,"chuong":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","ten":"Việt Nam kháng chiến chống thực dân Pháp xâm lược giai đoạn 1946 – 1950","trang":[67,72],"nam":1946,"tom":"Toàn quốc kháng chiến bùng nổ (12/1946); chiến thắng Việt Bắc 1947 và Biên giới 1950.","muc":[["1. Cuộc kháng chiến toàn quốc bùng nổ",["Pháp bội ước, gây hấn ở nhiều nơi; đêm 19/12/1946, cuộc kháng chiến toàn quốc bùng nổ; Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến.","Đường lối kháng chiến: toàn dân, toàn diện, trường kì, tự lực cánh sinh."]],["2. Chiến dịch Việt Bắc thu – đông 1947",["Pháp tấn công lên Việt Bắc hòng tiêu diệt cơ quan đầu não kháng chiến.","Quân dân ta đánh bại cuộc tấn công, bảo vệ căn cứ địa, buộc Pháp chuyển sang đánh lâu dài."]],["3. Chiến dịch Biên giới thu – đông 1950",["Ta chủ động mở chiến dịch, tiêu diệt cụm cứ điểm Đông Khê, giải phóng tuyến biên giới Việt – Trung.","Thắng lợi mở ra con đường liên lạc với các nước xã hội chủ nghĩa, ta giành quyền chủ động trên chiến trường chính Bắc Bộ."]]],"nho":["19/12/1946: toàn quốc kháng chiến.","1947: chiến thắng Việt Bắc.","1950: chiến thắng Biên giới, ta giành thế chủ động."],"hoi":["Trình bày đường lối kháng chiến chống Pháp của Đảng.","Nêu kết quả và ý nghĩa của chiến dịch Việt Bắc 1947.","Vì sao chiến dịch Biên giới 1950 là bước ngoặt của cuộc kháng chiến?"]},{"so":15,"chuong":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","ten":"Việt Nam kháng chiến chống thực dân Pháp xâm lược giai đoạn 1951 – 1954","trang":[73,79],"nam":1954,"tom":"Cuộc kháng chiến phát triển và kết thúc thắng lợi bằng chiến thắng Điện Biên Phủ, Hiệp định Giơ-ne-vơ (1954).","muc":[["1. Phát triển hậu phương và đẩy mạnh kháng chiến",["Đại hội đại biểu toàn quốc lần thứ II của Đảng (2/1951) đề ra nhiệm vụ đưa kháng chiến đến thắng lợi.","Hậu phương được củng cố: phát triển sản xuất, giảm tô, cải cách ruộng đất; lực lượng vũ trang lớn mạnh."]],["2. Cuộc tiến công chiến lược Đông – Xuân 1953 – 1954 và chiến dịch Điện Biên Phủ",["Pháp đề ra kế hoạch Na-va, xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương.","Ta tiến công nhiều hướng, buộc địch phân tán lực lượng; ngày 13/3/1954 mở chiến dịch Điện Biên Phủ.","Sau ba đợt tấn công, chiều 7/5/1954, quân ta tiêu diệt toàn bộ tập đoàn cứ điểm, bắt sống tướng Đờ Cát-xtơ-ri."]],["3. Hiệp định Giơ-ne-vơ và ý nghĩa",["Ngày 21/7/1954, Hiệp định Giơ-ne-vơ được kí, công nhận độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, Lào, Cam-pu-chia.","Kết thúc cuộc kháng chiến chống Pháp, miền Bắc được giải phóng; cổ vũ phong trào giải phóng dân tộc trên thế giới."]]],"nho":["2/1951: Đại hội II của Đảng.","13/3 – 7/5/1954: chiến dịch Điện Biên Phủ.","21/7/1954: Hiệp định Giơ-ne-vơ."],"hoi":["Trình bày diễn biến chính của chiến dịch Điện Biên Phủ.","Nêu nội dung cơ bản của Hiệp định Giơ-ne-vơ.","Vì sao chiến thắng Điện Biên Phủ “lừng lẫy năm châu, chấn động địa cầu”?"],"sa_ban":{"ten":"Sa bàn 3D Điện Biên Phủ 1954","url":"khong-gian/dien-bien-phu/"}},{"so":16,"chuong":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","ten":"Việt Nam kháng chiến chống Mỹ, cứu nước, thống nhất đất nước giai đoạn 1954 – 1965","trang":[80,84],"nam":1960,"tom":"Miền Bắc xây dựng chủ nghĩa xã hội, miền Nam đấu tranh chống chính quyền Sài Gòn và chiến lược của Mỹ.","muc":[["1. Tình hình đất nước sau năm 1954",["Đất nước tạm thời chia cắt làm hai miền; miền Bắc hoàn toàn giải phóng, miền Nam dưới sự kiểm soát của Mỹ và chính quyền Sài Gòn.","Miền Bắc khôi phục kinh tế, cải cách ruộng đất, thực hiện kế hoạch 5 năm lần thứ nhất (1961 – 1965)."]],["2. Miền Nam đấu tranh chống Mỹ và chính quyền Sài Gòn",["Phong trào “Đồng khởi” (1959 – 1960) bùng nổ, tiêu biểu ở Bến Tre; ngày 20/12/1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời.","1961 – 1965: quân dân miền Nam đánh bại chiến lược “Chiến tranh đặc biệt” của Mỹ, với các chiến thắng Ấp Bắc (1963), Bình Giã (1964 – 1965)…"]]],"nho":["1959 – 1960: phong trào Đồng khởi.","20/12/1960: Mặt trận Dân tộc giải phóng miền Nam Việt Nam.","1961 – 1965: đánh bại “Chiến tranh đặc biệt”."],"hoi":["Nêu nhiệm vụ của cách mạng hai miền sau năm 1954.","Phong trào Đồng khởi có ý nghĩa như thế nào?","Trình bày những thắng lợi chống “Chiến tranh đặc biệt”."]},{"so":17,"chuong":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","ten":"Việt Nam kháng chiến chống Mỹ, cứu nước, thống nhất đất nước giai đoạn 1965 – 1975","trang":[85,92],"nam":1975,"tom":"Đánh bại các chiến lược chiến tranh của Mỹ; Tổng tiến công và nổi dậy mùa Xuân 1975 giải phóng miền Nam.","muc":[["1. Chống chiến lược “Chiến tranh cục bộ” (1965 – 1968)",["Mỹ đưa quân viễn chinh vào miền Nam, đồng thời ném bom phá hoại miền Bắc.","Quân dân miền Nam thắng Vạn Tường (1965), đánh bại hai mùa khô; Tổng tiến công và nổi dậy Tết Mậu Thân 1968 buộc Mỹ “phi Mỹ hoá” chiến tranh, chấp nhận đàm phán ở Pa-ri."]],["2. Chống chiến lược “Việt Nam hoá chiến tranh” (1969 – 1973)",["Cuộc tiến công chiến lược năm 1972 giành nhiều thắng lợi; miền Bắc đánh bại cuộc tập kích bằng B-52 cuối năm 1972 (“Điện Biên Phủ trên không”).","Ngày 27/1/1973, Hiệp định Pa-ri được kí kết, Mỹ phải rút quân."]],["3. Giải phóng hoàn toàn miền Nam (1975)",["Tổng tiến công và nổi dậy mùa Xuân 1975 qua ba chiến dịch: Tây Nguyên, Huế – Đà Nẵng, Hồ Chí Minh.","Ngày 30/4/1975, chiến dịch Hồ Chí Minh toàn thắng, miền Nam hoàn toàn giải phóng, đất nước thống nhất.","Nguyên nhân thắng lợi: sự lãnh đạo của Đảng, tinh thần đoàn kết của nhân dân hai miền, sự ủng hộ của bạn bè quốc tế."]]],"nho":["1968: Tổng tiến công và nổi dậy Tết Mậu Thân.","27/1/1973: Hiệp định Pa-ri.","30/4/1975: miền Nam hoàn toàn giải phóng."],"hoi":["Trình bày thắng lợi của quân dân ta chống “Chiến tranh cục bộ”.","Hiệp định Pa-ri có ý nghĩa gì?","Nêu nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước."]},{"so":18,"chuong":"Chương 5. Thế giới từ năm 1991 đến nay","ten":"Trật tự thế giới mới từ năm 1991 đến nay. Liên bang Nga và nước Mỹ từ năm 1991 đến nay","trang":[93,95],"nam":1991,"tom":"Trật tự hai cực sụp đổ, thế giới chuyển dần sang đa cực; Nga và Mỹ sau Chiến tranh lạnh.","muc":[["1. Trật tự thế giới mới",["Sau khi Liên Xô tan rã, trật tự hai cực sụp đổ; thế giới chuyển dần sang đa cực, với nhiều trung tâm quyền lực.","Các nước tập trung phát triển kinh tế; xu thế hoà bình, hợp tác nhưng vẫn còn xung đột, khủng bố, tranh chấp."]],["2. Liên bang Nga",["Sau năm 1991, Liên bang Nga là quốc gia kế tục Liên Xô; những năm 90 gặp nhiều khó khăn.","Từ đầu thế kỉ XXI, kinh tế phục hồi, Nga khôi phục vị thế cường quốc."]],["3. Nước Mỹ",["Mỹ vẫn là cường quốc hàng đầu về kinh tế, khoa học – công nghệ, quân sự.","Mỹ tìm cách duy trì vai trò lãnh đạo thế giới nhưng phải đối mặt với nhiều thách thức."]]],"nho":["Sau 1991, thế giới chuyển sang trật tự đa cực.","Liên bang Nga kế tục Liên Xô, khôi phục vị thế.","Mỹ vẫn là cường quốc hàng đầu."],"hoi":["Nêu những nét chính của trật tự thế giới sau năm 1991.","Trình bày tình hình Liên bang Nga từ năm 1991 đến nay.","Nước Mỹ có vị thế như thế nào trong thế giới hiện nay?"]},{"so":19,"chuong":"Chương 5. Thế giới từ năm 1991 đến nay","ten":"Châu Á từ năm 1991 đến nay","trang":[96,100],"nam":null,"tom":"Châu Á phát triển năng động; ASEAN mở rộng, nhiều nước vươn lên mạnh mẽ.","muc":[["1. Khái quát",["Châu Á là khu vực phát triển năng động bậc nhất thế giới; nhiều nước đạt tốc độ tăng trưởng cao.","Bên cạnh đó còn các vấn đề: tranh chấp lãnh thổ, xung đột sắc tộc, tôn giáo."]],["2. Một số quốc gia và khu vực",["Trung Quốc tiếp tục cải cách mở cửa, trở thành nền kinh tế lớn thứ hai thế giới.","Nhật Bản, Hàn Quốc, Ấn Độ phát triển mạnh về kinh tế, khoa học – công nghệ.","ASEAN mở rộng thành 10 nước (1999), hướng tới Cộng đồng ASEAN (2015)."]]],"nho":["Châu Á phát triển năng động.","ASEAN gồm 10 nước từ năm 1999; Cộng đồng ASEAN năm 2015."],"hoi":["Vì sao châu Á được coi là khu vực năng động?","Trình bày sự phát triển của ASEAN từ năm 1991 đến nay."]},{"so":20,"chuong":"Chương 6. Việt Nam từ năm 1976 đến nay","ten":"Việt Nam từ năm 1976 đến nay","trang":[101,110],"nam":1986,"tom":"Thống nhất đất nước về mặt nhà nước, bảo vệ Tổ quốc, công cuộc Đổi mới từ năm 1986 và hội nhập quốc tế.","muc":[["1. Việt Nam những năm 1976 – 1985",["Năm 1976, Quốc hội khoá VI quyết định tên nước là Cộng hoà xã hội chủ nghĩa Việt Nam, hoàn thành thống nhất đất nước về mặt nhà nước.","Quân dân ta bảo vệ biên giới Tây Nam, biên giới phía Bắc (1979); kinh tế gặp nhiều khó khăn, khủng hoảng."]],["2. Công cuộc Đổi mới từ năm 1986",["Đại hội VI của Đảng (12/1986) đề ra đường lối Đổi mới toàn diện, trọng tâm là đổi mới kinh tế.","Thành tựu: thoát khỏi khủng hoảng, kinh tế tăng trưởng, đời sống nhân dân cải thiện, vị thế quốc tế nâng cao.","Hội nhập quốc tế: bình thường hoá quan hệ với Mỹ, gia nhập ASEAN (1995), WTO (2007)."]]],"nho":["1976: nước Cộng hoà xã hội chủ nghĩa Việt Nam.","12/1986: Đại hội VI, đường lối Đổi mới.","1995 gia nhập ASEAN; 2007 gia nhập WTO."],"hoi":["Việt Nam đã hoàn thành thống nhất đất nước về mặt nhà nước như thế nào?","Vì sao phải tiến hành Đổi mới?","Nêu những thành tựu cơ bản của công cuộc Đổi mới."]},{"so":21,"chuong":"Chương 7. Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá","ten":"Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá","trang":[111,115],"nam":null,"tom":"Những thành tựu của cách mạng khoa học – kĩ thuật và tác động của toàn cầu hoá tới thế giới, Việt Nam.","muc":[["1. Cách mạng khoa học – kĩ thuật",["Bắt đầu từ những năm 40 của thế kỉ XX; khoa học trở thành lực lượng sản xuất trực tiếp.","Thành tựu: máy tính điện tử, Internet, công nghệ sinh học, vật liệu mới, năng lượng mới, chinh phục vũ trụ.","Tác động: năng suất lao động tăng, đời sống thay đổi; nhưng cũng gây ô nhiễm môi trường, vũ khí hiện đại đe doạ nhân loại."]],["2. Xu thế toàn cầu hoá",["Biểu hiện: thương mại quốc tế phát triển, các công ti xuyên quốc gia, liên kết kinh tế khu vực và quốc tế (WTO, EU, ASEAN…).","Tác động: thúc đẩy phát triển, giao lưu; đồng thời gia tăng cạnh tranh, khoảng cách giàu nghèo.","Việt Nam vừa có thời cơ vừa có thách thức, cần chủ động hội nhập."]]],"nho":["Khoa học trở thành lực lượng sản xuất trực tiếp.","Toàn cầu hoá là xu thế khách quan.","Việt Nam chủ động, tích cực hội nhập quốc tế."],"hoi":["Nêu những thành tựu tiêu biểu của cách mạng khoa học – kĩ thuật.","Toàn cầu hoá có những biểu hiện và tác động gì?","Việt Nam cần làm gì trước xu thế toàn cầu hoá?"]},{"so":"CĐ1","chuong":"Chủ đề chung","ten":"Đô thị: lịch sử và hiện tại (phần 2)","trang":[221,224],"nam":null,"tom":"Chủ đề tích hợp về đô thị Việt Nam qua các thời kì.","muc":[["1. Đô thị Việt Nam qua các thời kì",["Thời phong kiến: Thăng Long – Kẻ Chợ là trung tâm chính trị, kinh tế; thế kỉ XVI – XVIII có Phố Hiến, Hội An, Thanh Hà…","Thời Pháp thuộc: các đô thị như Hà Nội, Sài Gòn, Hải Phòng phát triển theo kiểu phương Tây.","Từ năm 1986, quá trình đô thị hoá diễn ra nhanh, nhiều đô thị mới hình thành."]],["2. Vai trò và thách thức",["Đô thị là trung tâm kinh tế, văn hoá, khoa học, giao lưu quốc tế.","Thách thức: dân số tăng nhanh, ô nhiễm môi trường, ùn tắc giao thông, bảo tồn di sản."]]],"nho":["Thăng Long – Kẻ Chợ, Phố Hiến, Hội An là đô thị tiêu biểu thời phong kiến.","Đô thị hoá nhanh từ khi Đổi mới."],"hoi":["Kể tên một số đô thị tiêu biểu trong lịch sử Việt Nam.","Nêu những thách thức của đô thị Việt Nam hiện nay."]},{"so":"CĐ2","chuong":"Chủ đề chung","ten":"Văn minh châu thổ sông Hồng và sông Cửu Long (phần 2)","trang":[225,229],"nam":null,"tom":"Chủ đề tích hợp tiếp nối lớp 8 về văn minh hai vùng châu thổ.","muc":[["1. Văn minh châu thổ trong thời kì cận – hiện đại",["Đồng bằng sông Hồng và sông Cửu Long tiếp tục là vựa lúa, trung tâm kinh tế lớn của cả nước.","Hệ thống đê điều, thuỷ lợi, kênh rạch được mở rộng; làng nghề, chợ nổi, lễ hội được gìn giữ."]],["2. Bảo tồn và phát triển",["Biến đổi khí hậu, xâm nhập mặn, sạt lở đe doạ hai vùng châu thổ.","Cần phát triển bền vững, gìn giữ giá trị văn hoá, sinh thái của hai vùng."]]],"nho":["Hai vùng châu thổ là vựa lúa và trung tâm kinh tế, văn hoá.","Biến đổi khí hậu là thách thức lớn."],"hoi":["Văn minh châu thổ có vai trò gì đối với đất nước hiện nay?","Đề xuất một việc làm để bảo vệ vùng châu thổ nơi em sống hoặc em biết."]},{"so":"CĐ3","chuong":"Chủ đề chung","ten":"Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông (phần 2)","trang":[230,235],"nam":null,"tom":"Chủ đề tích hợp tiếp nối lớp 8 về chủ quyền biển đảo.","muc":[["1. Việt Nam bảo vệ chủ quyền ở Biển Đông",["Các nhà nước Việt Nam liên tục thực thi chủ quyền đối với Hoàng Sa, Trường Sa từ thế kỉ XVII đến nay.","Việt Nam là thành viên Công ước của Liên hợp quốc về Luật Biển năm 1982; ban hành Luật Biển Việt Nam (2012)."]],["2. Quyền và lợi ích hợp pháp",["Việt Nam có quyền đối với nội thuỷ, lãnh hải, vùng đặc quyền kinh tế, thềm lục địa theo luật pháp quốc tế.","Chủ trương giải quyết tranh chấp bằng biện pháp hoà bình, giữ gìn hoà bình, ổn định trong khu vực."]]],"nho":["Công ước Luật Biển 1982; Luật Biển Việt Nam 2012.","Giải quyết tranh chấp bằng biện pháp hoà bình."],"hoi":["Việt Nam có những quyền gì đối với các vùng biển của mình?","Vì sao Việt Nam chủ trương giải quyết tranh chấp bằng biện pháp hoà bình?"]}]},"10":{"sach":"Lịch sử 10 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), tr. 6–106","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chủ đề 1. Lịch sử và Sử học","ten":"Hiện thực lịch sử và lịch sử được con người nhận thức","trang":[6,10],"nam":null,"tom":"Phân biệt quá khứ đã diễn ra với hiểu biết của con người về quá khứ; đối tượng, chức năng, nhiệm vụ của Sử học.","muc":[["1. Lịch sử là gì?",["Lịch sử là tất cả những gì đã diễn ra trong quá khứ của xã hội loài người, tồn tại khách quan, không phụ thuộc vào ý muốn con người (hiện thực lịch sử).","Nhận thức lịch sử là những hiểu biết, hình dung của con người về quá khứ, được trình bày qua lời kể, bài viết, công trình nghiên cứu."]],["2. Hiện thực lịch sử và nhận thức lịch sử",["Hiện thực lịch sử là duy nhất, còn nhận thức lịch sử có thể khác nhau tuỳ nguồn tư liệu, quan điểm, phương pháp của người tìm hiểu.","Nhận thức lịch sử càng gần với hiện thực lịch sử khi dựa trên sử liệu tin cậy và phương pháp khoa học."]],["3. Sử học",["Sử học là khoa học nghiên cứu về quá khứ của con người và xã hội loài người.","Đối tượng nghiên cứu rộng: chính trị, kinh tế, văn hoá, xã hội…; chức năng: khoa học (khôi phục, giải thích quá khứ) và xã hội (giáo dục, dự báo).","Nguyên tắc cơ bản: khách quan, trung thực, tiến bộ.","Nguồn sử liệu gồm: tư liệu chữ viết, hiện vật, truyền miệng, hình ảnh…; cần thu thập, phân loại, thẩm định trước khi sử dụng."]]],"nho":["Hiện thực lịch sử là khách quan; nhận thức lịch sử có thể khác nhau.","Sử học nghiên cứu quá khứ con người, theo nguyên tắc khách quan, trung thực.","Sử liệu cần được thẩm định trước khi sử dụng."],"hoi":["Phân biệt hiện thực lịch sử và nhận thức lịch sử.","Nêu chức năng và nhiệm vụ của Sử học.","Vì sao cần thẩm định nguồn sử liệu?"]},{"so":2,"chuong":"Chủ đề 1. Lịch sử và Sử học","ten":"Tri thức lịch sử và cuộc sống","trang":[11,15],"nam":null,"tom":"Vì sao cần học tập, khám phá lịch sử suốt đời và vận dụng tri thức lịch sử vào cuộc sống.","muc":[["1. Vai trò của tri thức lịch sử",["Tri thức lịch sử giúp con người hiểu nguồn gốc, cội rễ, bản sắc của bản thân, cộng đồng, dân tộc.","Rút ra bài học kinh nghiệm từ quá khứ để vận dụng cho hiện tại và tương lai."]],["2. Học tập lịch sử suốt đời",["Tri thức lịch sử rộng lớn và luôn được bổ sung, vì vậy cần học tập thường xuyên, suốt đời.","Có thể tự học qua sách báo, bảo tàng, di tích, phim tư liệu, Internet… và cần biết chọn lọc nguồn tin cậy."]],["3. Vận dụng tri thức lịch sử vào cuộc sống",["Giải thích các sự kiện, hiện tượng đang diễn ra; nhìn nhận các vấn đề thời sự có chiều sâu.","Góp phần giữ gìn, phát huy giá trị di sản, xây dựng quê hương, đất nước."]]],"nho":["Tri thức lịch sử giúp hiểu cội nguồn và rút bài học.","Học lịch sử là việc cần làm suốt đời.","Có nhiều cách tự học: bảo tàng, di tích, sách, tư liệu số."],"hoi":["Vì sao cần học tập lịch sử suốt đời?","Nêu một ví dụ vận dụng tri thức lịch sử để hiểu một vấn đề hiện nay.","Em đã từng tìm hiểu lịch sử qua những kênh nào ngoài lớp học?"]},{"so":3,"chuong":"Chủ đề 2. Vai trò của Sử học","ten":"Vai trò của Sử học","trang":[16,20],"nam":null,"tom":"Sử học với bảo tồn di sản văn hoá, phát triển du lịch và các ngành nghề liên quan.","muc":[["1. Sử học với công tác bảo tồn, phát huy di sản",["Di sản văn hoá gồm di sản vật thể (di tích, hiện vật) và phi vật thể (lễ hội, nghệ thuật, tri thức dân gian), cùng di sản thiên nhiên.","Sử học giúp xác định giá trị, nguồn gốc của di sản, là cơ sở để bảo tồn đúng và phát huy giá trị."]],["2. Sử học với phát triển du lịch",["Lịch sử, văn hoá là nguồn tài nguyên quan trọng của du lịch; hiểu biết lịch sử giúp xây dựng sản phẩm du lịch hấp dẫn.","Du lịch góp phần quảng bá, tạo nguồn lực cho bảo tồn di sản; nhưng cần tránh khai thác quá mức làm tổn hại di sản."]],["3. Mối quan hệ giữa Sử học với các ngành khoa học khác",["Sử học sử dụng thành tựu của nhiều ngành (khảo cổ học, địa lí, nhân học, khoa học tự nhiên…) để nghiên cứu.","Ngược lại, tri thức lịch sử cung cấp bối cảnh cho nhiều ngành khoa học khác."]]],"nho":["Sử học là cơ sở để bảo tồn và phát huy di sản.","Lịch sử, văn hoá là tài nguyên của du lịch.","Sử học có tính liên ngành."],"hoi":["Sử học có vai trò gì trong bảo tồn di sản?","Mối quan hệ giữa Sử học và du lịch thể hiện ở đâu?","Hãy giới thiệu một di sản ở địa phương em và giá trị lịch sử của nó."]},{"so":4,"chuong":"Chủ đề 3. Một số nền văn minh thế giới thời cổ – trung đại","ten":"Khái niệm văn minh. Một số nền văn minh phương Đông thời cổ – trung đại","trang":[21,30],"nam":null,"tom":"Khái niệm văn minh, văn hoá; thành tựu của văn minh Ai Cập, Lưỡng Hà, Ấn Độ, Trung Hoa.","muc":[["1. Khái niệm văn minh và văn hoá",["Văn hoá là tổng thể những giá trị vật chất và tinh thần do con người sáng tạo ra trong lịch sử.","Văn minh là trạng thái tiến bộ của văn hoá, khi con người đã có nhà nước, chữ viết, đô thị; văn hoá có từ khi có loài người, văn minh xuất hiện muộn hơn."]],["2. Văn minh Ai Cập cổ đại",["Hình thành bên lưu vực sông Nin; nhà nước ra đời sớm, đứng đầu là Pha-ra-ông.","Thành tựu: chữ tượng hình, giấy pa-pi-rút, lịch, toán học, kĩ thuật ướp xác, kim tự tháp và tượng nhân sư."]],["3. Văn minh Trung Hoa cổ – trung đại",["Hình thành ở lưu vực Hoàng Hà, Trường Giang.","Thành tựu: chữ Hán, Nho giáo, Đạo giáo; sử học, văn học (thơ Đường, tiểu thuyết Minh – Thanh); bốn phát minh kĩ thuật: giấy, la bàn, thuốc súng, kĩ thuật in; Vạn Lí Trường Thành."]],["4. Văn minh Ấn Độ cổ – trung đại",["Hình thành ở lưu vực sông Ấn, sông Hằng.","Thành tựu: chữ Phạn; Phật giáo, Ấn Độ giáo; sử thi Ra-ma-y-a-na, Ma-ha-bha-ra-ta; hệ số đếm có số 0; kiến trúc chùa hang, đền tháp."]]],"nho":["Văn minh là giai đoạn phát triển cao của văn hoá.","Ai Cập: chữ tượng hình, kim tự tháp.","Trung Hoa: Nho giáo, bốn phát minh; Ấn Độ: Phật giáo, chữ số 0."],"hoi":["Phân biệt văn hoá và văn minh.","Nêu những thành tựu tiêu biểu của văn minh Ai Cập cổ đại.","Văn minh Trung Hoa và Ấn Độ có ảnh hưởng thế nào đến Việt Nam?"]},{"so":5,"chuong":"Chủ đề 3. Một số nền văn minh thế giới thời cổ – trung đại","ten":"Một số nền văn minh phương Tây thời cổ – trung đại","trang":[31,37],"nam":null,"tom":"Văn minh Hy Lạp – La Mã cổ đại và văn minh thời Phục hưng.","muc":[["1. Văn minh Hy Lạp – La Mã cổ đại",["Hình thành ven Địa Trung Hải, kinh tế thủ công nghiệp và thương nghiệp phát triển; thể chế dân chủ chủ nô ở A-ten, cộng hoà rồi đế chế ở La Mã.","Thành tựu: chữ cái La-tinh, triết học, khoa học (Ta-lét, Pi-ta-go, Ác-si-mét), sử thi I-li-át, Ô-đi-xê, kịch, kiến trúc đền Pác-tê-nông, đấu trường Cô-li-dê, luật La Mã, Thế vận hội."]],["2. Văn minh Tây Âu thời Phục hưng",["Thế kỉ XIV – XVII, phong trào Phục hưng khởi đầu ở I-ta-li-a, đề cao giá trị con người (chủ nghĩa nhân văn).","Thành tựu: văn học (Đan-tê, Sếch-xpia, Xéc-van-téc), hội hoạ (Lê-ô-na-đô đa Vin-xi, Mi-ken-lăng-giơ, Ra-pha-en), khoa học (Cô-péc-ních, Ga-li-lê)."]]],"nho":["Hy Lạp – La Mã: chữ cái La-tinh, triết học, khoa học, Thế vận hội.","Phục hưng đề cao con người, khởi đầu ở I-ta-li-a."],"hoi":["Nêu những thành tựu tiêu biểu của văn minh Hy Lạp – La Mã.","Phong trào Văn hoá Phục hưng có ý nghĩa gì?","Kể tên một tác phẩm thời Phục hưng mà em biết."]},{"so":6,"chuong":"Chủ đề 4. Các cuộc cách mạng công nghiệp trong lịch sử thế giới","ten":"Các cuộc cách mạng công nghiệp thời cận đại","trang":[38,44],"nam":null,"tom":"Cách mạng công nghiệp lần thứ nhất và lần thứ hai: thành tựu và tác động.","muc":[["1. Cách mạng công nghiệp lần thứ nhất",["Bắt đầu ở Anh từ giữa thế kỉ XVIII; thành tựu tiêu biểu: máy kéo sợi, máy dệt, máy hơi nước (Giêm Oát), đầu máy xe lửa, tàu thuỷ chạy bằng hơi nước.","Lao động thủ công chuyển sang lao động bằng máy móc."]],["2. Cách mạng công nghiệp lần thứ hai",["Diễn ra từ nửa sau thế kỉ XIX đến đầu thế kỉ XX ở Mỹ, Đức, Anh, Pháp…","Thành tựu: điện năng, động cơ đốt trong, ô tô, máy bay, điện thoại, điện tín; sản xuất dây chuyền."]],["3. Ý nghĩa và tác động",["Năng suất lao động tăng vọt, nền sản xuất công nghiệp hình thành; đô thị hoá diễn ra mạnh.","Xã hội hình thành hai giai cấp cơ bản: tư sản và vô sản; đồng thời là ô nhiễm môi trường, các nước tư bản tranh giành thuộc địa."]]],"nho":["CMCN lần 1: giữa thế kỉ XVIII ở Anh, máy hơi nước.","CMCN lần 2: điện, động cơ đốt trong, dây chuyền.","Tạo ra nền sản xuất công nghiệp và biến đổi xã hội."],"hoi":["Nêu những thành tựu tiêu biểu của hai cuộc cách mạng công nghiệp thời cận đại.","Cách mạng công nghiệp đã tác động thế nào đến xã hội?"]},{"so":7,"chuong":"Chủ đề 4. Các cuộc cách mạng công nghiệp trong lịch sử thế giới","ten":"Các cuộc cách mạng công nghiệp thời hiện đại","trang":[45,50],"nam":null,"tom":"Cách mạng công nghiệp lần thứ ba và lần thứ tư: thành tựu và ý nghĩa.","muc":[["1. Cách mạng công nghiệp lần thứ ba",["Bắt đầu từ những năm 1950 – 1960; thành tựu: máy tính, tự động hoá, Internet, vật liệu mới, năng lượng nguyên tử, chinh phục vũ trụ.","Đặc điểm: khoa học trở thành lực lượng sản xuất trực tiếp."]],["2. Cách mạng công nghiệp lần thứ tư",["Bắt đầu từ đầu thế kỉ XXI, dựa trên công nghệ số; thành tựu: trí tuệ nhân tạo, Internet vạn vật, dữ liệu lớn, in 3D, công nghệ sinh học…","Xoá nhoà ranh giới giữa thế giới vật lí, kĩ thuật số và sinh học."]],["3. Ý nghĩa và tác động",["Tích cực: năng suất tăng, đời sống thay đổi, kết nối toàn cầu.","Thách thức: thất nghiệp do tự động hoá, an ninh mạng, khoảng cách số, ô nhiễm môi trường.","Việt Nam cần chủ động nắm bắt cơ hội, phát triển nguồn nhân lực chất lượng cao."]]],"nho":["CMCN lần 3: máy tính, Internet, tự động hoá.","CMCN lần 4: trí tuệ nhân tạo, Internet vạn vật, dữ liệu lớn.","Vừa là cơ hội vừa là thách thức."],"hoi":["So sánh cách mạng công nghiệp lần thứ ba và lần thứ tư.","Cách mạng công nghiệp lần thứ tư tác động thế nào đến đời sống của em?","Học sinh cần chuẩn bị gì để thích ứng?"]},{"so":8,"chuong":"Chủ đề 5. Văn minh Đông Nam Á thời cổ – trung đại","ten":"Hành trình phát triển và thành tựu của văn minh Đông Nam Á thời cổ – trung đại","trang":[51,58],"nam":null,"tom":"Cơ sở hình thành, các thời kì phát triển và thành tựu tiêu biểu của văn minh Đông Nam Á.","muc":[["1. Cơ sở hình thành",["Điều kiện tự nhiên: khí hậu nhiệt đới gió mùa, nhiều sông ngòi, đồng bằng phù sa, biển rộng; nền nông nghiệp lúa nước.","Là nơi giao lưu giữa hai nền văn minh lớn Ấn Độ và Trung Hoa."]],["2. Tiến trình phát triển",["Những thế kỉ đầu Công nguyên, các quốc gia sơ kì ra đời (Văn Lang – Âu Lạc, Phù Nam, Chăm-pa…).","Thế kỉ X – XV là thời kì phát triển thịnh đạt; từ thế kỉ XVI bước vào giai đoạn suy thoái, rồi bị thực dân phương Tây xâm lược."]],["3. Thành tựu tiêu biểu",["Tín ngưỡng, tôn giáo: tín ngưỡng phồn thực, thờ cúng tổ tiên; Phật giáo, Hin-đu giáo, Hồi giáo, Công giáo.","Chữ viết: tiếp thu chữ Phạn, chữ Hán để sáng tạo chữ viết riêng (chữ Chăm cổ, chữ Khơ-me cổ, chữ Nôm…).","Kiến trúc, điêu khắc: Ăng-co Vát, Bô-rô-bu-đua, tháp Chăm, chùa Vàng…"]]],"nho":["Nền tảng là nông nghiệp lúa nước.","Tiếp thu văn minh Ấn Độ, Trung Hoa nhưng mang bản sắc riêng.","Ăng-co Vát, Bô-rô-bu-đua là công trình tiêu biểu."],"hoi":["Nêu cơ sở hình thành văn minh Đông Nam Á.","Kể tên một số thành tựu kiến trúc tiêu biểu của Đông Nam Á.","Vì sao văn minh Đông Nam Á vừa có nét chung vừa có bản sắc riêng?"]},{"so":9,"chuong":"Chủ đề 6. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858)","ten":"Một số nền văn minh cổ trên đất nước Việt Nam","trang":[59,72],"nam":null,"tom":"Văn minh Văn Lang – Âu Lạc, văn minh Chăm-pa, văn minh Phù Nam.","muc":[["1. Văn minh Văn Lang – Âu Lạc",["Hình thành ở lưu vực sông Hồng, sông Mã, sông Cả; cơ sở là nông nghiệp lúa nước và kĩ thuật đúc đồng (trống đồng Đông Sơn).","Nhà nước Văn Lang của các vua Hùng, Âu Lạc của An Dương Vương; thành Cổ Loa.","Đời sống tinh thần: thờ cúng tổ tiên, các vị thần tự nhiên; tục nhuộm răng, ăn trầu, xăm mình."]],["2. Văn minh Chăm-pa",["Hình thành ở vùng duyên hải miền Trung; kinh tế nông nghiệp kết hợp khai thác biển, buôn bán.","Thành tựu: chữ Chăm cổ, Hin-đu giáo và Phật giáo, khu đền tháp Mỹ Sơn, nghệ thuật điêu khắc đá."]],["3. Văn minh Phù Nam",["Hình thành ở vùng Nam Bộ ngày nay; Óc Eo là thương cảng quốc tế sầm uất.","Thành tựu: kinh tế thương mại biển phát triển, kiến trúc gạch đá, đồ trang sức; tiếp thu văn hoá Ấn Độ."]]],"nho":["Văn Lang – Âu Lạc: lúa nước, trống đồng Đông Sơn, thành Cổ Loa.","Chăm-pa: tháp Chăm, Mỹ Sơn.","Phù Nam: thương cảng Óc Eo."],"hoi":["Trình bày cơ sở hình thành văn minh Văn Lang – Âu Lạc.","Nêu thành tựu tiêu biểu của văn minh Chăm-pa và Phù Nam.","Ba nền văn minh cổ có ý nghĩa gì đối với lịch sử Việt Nam?"]},{"so":10,"chuong":"Chủ đề 6. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858)","ten":"Văn minh Đại Việt","trang":[73,85],"nam":1010,"tom":"Cơ sở hình thành và thành tựu của văn minh Đại Việt trên các lĩnh vực.","muc":[["1. Cơ sở hình thành",["Kế thừa văn minh Văn Lang – Âu Lạc; được xây dựng trên nền độc lập dân tộc từ thế kỉ X.","Tiếp thu có chọn lọc văn minh Trung Hoa, Ấn Độ."]],["2. Quá trình phát triển",["Hình thành từ thời Ngô, Đinh, Tiền Lê; phát triển rực rỡ thời Lý, Trần, Lê sơ; tiếp tục phát triển, có nhiều biến đổi thời Mạc, Lê trung hưng, Tây Sơn và đầu thời Nguyễn."]],["3. Thành tựu tiêu biểu",["Chính trị: nhà nước quân chủ trung ương tập quyền ngày càng hoàn thiện; các bộ luật Hình thư, Quốc triều hình luật (luật Hồng Đức).","Kinh tế: nông nghiệp lúa nước, đê điều; thủ công nghiệp với nhiều làng nghề; thương nghiệp với Thăng Long, Phố Hiến, Hội An.","Tư tưởng, tôn giáo: Phật giáo phát triển thời Lý – Trần (Thiền phái Trúc Lâm), Nho giáo chiếm địa vị độc tôn thời Lê sơ.","Giáo dục, khoa cử: Văn Miếu (1070), Quốc Tử Giám (1076); văn học chữ Hán, chữ Nôm; nghệ thuật kiến trúc chùa Một Cột, Hoàng thành Thăng Long; khoa học: Đại Việt sử kí toàn thư, bản đồ Hồng Đức…"]],["4. Ý nghĩa",["Thể hiện sức sáng tạo của dân tộc, tạo nên sức mạnh để bảo vệ độc lập; là nền tảng cho văn hoá Việt Nam hiện nay."]]],"nho":["Văn minh Đại Việt phát triển rực rỡ thời Lý, Trần, Lê sơ.","1070: Văn Miếu; 1076: Quốc Tử Giám.","Phật giáo thịnh thời Lý – Trần, Nho giáo độc tôn thời Lê sơ."],"hoi":["Nêu cơ sở hình thành văn minh Đại Việt.","Trình bày thành tựu tiêu biểu của văn minh Đại Việt về giáo dục, khoa cử.","Văn minh Đại Việt có ý nghĩa gì đối với lịch sử dân tộc?"]},{"so":11,"chuong":"Chủ đề 7. Cộng đồng các dân tộc Việt Nam","ten":"Các dân tộc trên đất nước Việt Nam","trang":[86,89],"nam":null,"tom":"Thành phần dân tộc, các ngữ hệ và sự phân bố của 54 dân tộc ở Việt Nam.","muc":[["1. Thành phần dân tộc theo dân số",["Việt Nam là quốc gia thống nhất gồm 54 dân tộc; dân tộc Kinh (Việt) chiếm khoảng 85% dân số, 53 dân tộc còn lại là dân tộc thiểu số.","Các dân tộc có dân số trên 1 triệu người: Tày, Thái, Mường, Khơ-me, Hoa, Nùng, H'Mông."]],["2. Thành phần dân tộc theo ngữ hệ",["Các dân tộc được xếp vào 5 ngữ hệ: Nam Á, Thái – Ka-đai, H'Mông – Dao, Nam Đảo, Hán – Tạng; gồm 8 nhóm ngôn ngữ.","Các dân tộc sinh sống xen kẽ, không có lãnh thổ tộc người riêng biệt."]]],"nho":["Việt Nam có 54 dân tộc, dân tộc Kinh chiếm khoảng 85%.","Các dân tộc thuộc 5 ngữ hệ.","Các dân tộc cư trú xen kẽ."],"hoi":["Nêu cách phân chia thành phần dân tộc theo dân số và theo ngữ hệ.","Kể tên một số dân tộc ở địa phương em."]},{"so":12,"chuong":"Chủ đề 7. Cộng đồng các dân tộc Việt Nam","ten":"Khái quát về đời sống vật chất và tinh thần của cộng đồng các dân tộc Việt Nam","trang":[90,99],"nam":null,"tom":"Những nét chính về sản xuất, ăn, mặc, ở, tín ngưỡng, lễ hội của các dân tộc.","muc":[["1. Đời sống vật chất",["Hoạt động kinh tế: người Kinh chủ yếu trồng lúa nước, làm nghề thủ công, buôn bán; các dân tộc thiểu số làm ruộng bậc thang, nương rẫy, chăn nuôi, khai thác lâm sản.","Ở: nhà trệt (người Kinh), nhà sàn (nhiều dân tộc miền núi), nhà dài (một số dân tộc Tây Nguyên).","Ăn, mặc: lúa gạo là lương thực chính; trang phục phong phú, mang bản sắc riêng của mỗi dân tộc."]],["2. Đời sống tinh thần",["Tín ngưỡng: thờ cúng tổ tiên, thờ Mẫu, thờ thần tự nhiên; tôn giáo: Phật giáo, Công giáo, Tin Lành, Hồi giáo, Cao Đài, Hoà Hảo…","Phong tục, lễ hội: Tết Nguyên đán, lễ hội cầu mùa, lễ mừng cơm mới; nghệ thuật dân gian phong phú (hát quan họ, then, cồng chiêng Tây Nguyên)."]]],"nho":["Mỗi dân tộc có nét riêng về ăn, mặc, ở.","Thờ cúng tổ tiên là tín ngưỡng phổ biến.","Không gian văn hoá cồng chiêng Tây Nguyên là di sản tiêu biểu."],"hoi":["Trình bày những nét chính về đời sống vật chất của các dân tộc Việt Nam.","Kể tên một số lễ hội tiêu biểu của các dân tộc.","Em cần làm gì để giữ gìn bản sắc văn hoá các dân tộc?"]},{"so":13,"chuong":"Chủ đề 7. Cộng đồng các dân tộc Việt Nam","ten":"Khối đại đoàn kết dân tộc trong lịch sử Việt Nam","trang":[100,106],"nam":null,"tom":"Vai trò của khối đại đoàn kết dân tộc trong dựng nước, giữ nước và chính sách dân tộc hiện nay.","muc":[["1. Khối đại đoàn kết dân tộc trong lịch sử",["Hình thành từ sớm trong quá trình dựng nước và giữ nước, trị thuỷ, chống ngoại xâm.","Là nhân tố quyết định thắng lợi trong các cuộc kháng chiến chống ngoại xâm và công cuộc xây dựng đất nước."]],["2. Chính sách dân tộc của Đảng và Nhà nước",["Nguyên tắc: bình đẳng, đoàn kết, tôn trọng, giúp nhau cùng phát triển.","Nội dung: phát triển kinh tế – xã hội vùng dân tộc thiểu số, xoá đói giảm nghèo; giữ gìn, phát huy bản sắc văn hoá; đào tạo cán bộ người dân tộc thiểu số; bảo đảm quốc phòng, an ninh."]]],"nho":["Đại đoàn kết dân tộc là truyền thống và sức mạnh của dân tộc.","Chính sách dân tộc: bình đẳng, đoàn kết, tôn trọng, giúp nhau cùng phát triển."],"hoi":["Vì sao khối đại đoàn kết dân tộc có vai trò quan trọng?","Trình bày nội dung cơ bản của chính sách dân tộc hiện nay.","Học sinh có thể làm gì để góp phần củng cố khối đại đoàn kết dân tộc?"]}]},"11":{"sach":"Lịch sử 11 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), tr. 6–90","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chủ đề 1. Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản","ten":"Một số vấn đề chung về cách mạng tư sản","trang":[6,11],"nam":null,"tom":"Tiền đề, mục tiêu, nhiệm vụ, giai cấp lãnh đạo, động lực, kết quả và ý nghĩa của các cuộc cách mạng tư sản.","muc":[["1. Tiền đề của cách mạng tư sản",["Kinh tế: quan hệ sản xuất tư bản chủ nghĩa ra đời, phát triển nhưng bị chế độ phong kiến kìm hãm.","Chính trị – xã hội: mâu thuẫn giữa tư sản, nhân dân với chế độ phong kiến chuyên chế ngày càng gay gắt.","Tư tưởng: trào lưu Triết học Ánh sáng (Mông-te-xki-ơ, Vôn-te, Rút-xô) chuẩn bị cho cách mạng."]],["2. Một số cuộc cách mạng tư sản tiêu biểu",["Cách mạng tư sản Anh (thế kỉ XVII) dẫn tới chế độ quân chủ lập hiến.","Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ (1775 – 1783) khai sinh Hợp chúng quốc Hoa Kỳ.","Cách mạng tư sản Pháp (1789 – 1794) lật đổ chế độ quân chủ, công bố Tuyên ngôn Nhân quyền và Dân quyền."]],["3. Mục tiêu, nhiệm vụ, lực lượng và ý nghĩa",["Mục tiêu: xoá bỏ chế độ phong kiến, xác lập nhà nước tư sản, mở đường cho chủ nghĩa tư bản phát triển.","Lực lượng lãnh đạo là giai cấp tư sản; động lực là quần chúng nhân dân.","Ý nghĩa: mở ra thời kì thắng lợi và củng cố của chủ nghĩa tư bản trên thế giới."]]],"nho":["Triết học Ánh sáng là tiền đề tư tưởng.","1775 – 1783: chiến tranh giành độc lập ở Bắc Mỹ.","1789: Cách mạng tư sản Pháp."],"hoi":["Trình bày những tiền đề của cách mạng tư sản.","Nêu mục tiêu và lực lượng tham gia các cuộc cách mạng tư sản.","Vì sao Cách mạng tư sản Pháp được coi là triệt để nhất?"]},{"so":2,"chuong":"Chủ đề 1. Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản","ten":"Sự xác lập và phát triển của chủ nghĩa tư bản","trang":[12,18],"nam":null,"tom":"Chủ nghĩa tư bản được xác lập, chuyển sang giai đoạn đế quốc và chủ nghĩa tư bản hiện đại.","muc":[["1. Sự xác lập của chủ nghĩa tư bản",["Qua các cuộc cách mạng tư sản và cách mạng công nghiệp, chủ nghĩa tư bản được xác lập ở châu Âu, Bắc Mỹ trong thế kỉ XIX.","Các nước tư bản mở rộng xâm lược thuộc địa, hình thành hệ thống thuộc địa khắp thế giới."]],["2. Chủ nghĩa tư bản hiện đại",["Cuối thế kỉ XIX – đầu XX, chủ nghĩa tư bản chuyển sang giai đoạn độc quyền; từ sau Chiến tranh thế giới thứ hai là chủ nghĩa tư bản hiện đại.","Đặc điểm: ứng dụng mạnh mẽ khoa học – công nghệ, các công ti xuyên quốc gia, nhà nước can thiệp vào kinh tế.","Tiềm năng: khả năng thích ứng, điều chỉnh; hạn chế: bất bình đẳng, khủng hoảng chu kì, chênh lệch giàu nghèo."]]],"nho":["Chủ nghĩa tư bản xác lập trên phạm vi thế giới trong thế kỉ XIX.","Chủ nghĩa tư bản hiện đại có khả năng điều chỉnh nhưng còn nhiều hạn chế."],"hoi":["Trình bày quá trình xác lập chủ nghĩa tư bản.","Nêu tiềm năng và hạn chế của chủ nghĩa tư bản hiện đại."]},{"so":3,"chuong":"Chủ đề 2. Chủ nghĩa xã hội từ năm 1917 đến nay","ten":"Sự hình thành Liên bang Cộng hoà xã hội chủ nghĩa Xô viết","trang":[19,21],"nam":1922,"tom":"Cách mạng tháng Mười Nga và sự thành lập Liên Xô (1922).","muc":[["1. Cách mạng tháng Mười Nga năm 1917",["Đầu thế kỉ XX, nước Nga khủng hoảng toàn diện; Cách mạng tháng Hai (1917) lật đổ Nga hoàng, dẫn đến tình trạng hai chính quyền song song.","Ngày 25/10/1917 (lịch Nga), dưới sự lãnh đạo của Lê-nin và Đảng Bôn-sê-vích, khởi nghĩa giành thắng lợi ở Pê-tơ-rô-grát, nhà nước Xô viết ra đời."]],["2. Liên Xô được thành lập và xây dựng chủ nghĩa xã hội",["Sau nội chiến và Chính sách kinh tế mới, Liên Xô được thành lập (12/1922).","Liên Xô tiến hành công nghiệp hoá, tập thể hoá, trở thành cường quốc công nghiệp.","Ý nghĩa: chủ nghĩa xã hội từ lí luận trở thành hiện thực ở một quốc gia, cổ vũ phong trào cách mạng thế giới."]]],"nho":["25/10/1917: Cách mạng tháng Mười Nga thắng lợi.","12/1922: Liên Xô thành lập."],"hoi":["Trình bày những nét chính của Cách mạng tháng Mười Nga.","Cách mạng tháng Mười có ý nghĩa gì với thế giới?"]},{"so":4,"chuong":"Chủ đề 2. Chủ nghĩa xã hội từ năm 1917 đến nay","ten":"Sự phát triển của chủ nghĩa xã hội từ sau Chiến tranh thế giới thứ hai đến nay","trang":[22,28],"nam":null,"tom":"Chủ nghĩa xã hội mở rộng, khủng hoảng ở Liên Xô, Đông Âu và công cuộc cải cách ở các nước hiện nay.","muc":[["1. Chủ nghĩa xã hội mở rộng sau Chiến tranh thế giới thứ hai",["Các nước Đông Âu, Trung Quốc, Việt Nam, Triều Tiên, Cu-ba… đi theo con đường xã hội chủ nghĩa; hệ thống xã hội chủ nghĩa thế giới hình thành.","Hội đồng Tương trợ kinh tế (SEV, 1949), Tổ chức Hiệp ước Vác-sa-va (1955)."]],["2. Sự khủng hoảng và sụp đổ ở Liên Xô, Đông Âu",["Từ những năm 70, các nước lâm vào khủng hoảng; cải tổ thất bại.","Chế độ xã hội chủ nghĩa ở Đông Âu sụp đổ (1989 – 1991), Liên Xô tan rã (12/1991)."]],["3. Chủ nghĩa xã hội từ năm 1991 đến nay",["Trung Quốc, Việt Nam, Lào, Cu-ba tiếp tục con đường xã hội chủ nghĩa, tiến hành cải cách, đổi mới, đạt nhiều thành tựu.","Trung Quốc cải cách mở cửa từ năm 1978; Việt Nam Đổi mới từ năm 1986; Lào đổi mới từ năm 1986; Cu-ba điều chỉnh, cập nhật mô hình."]]],"nho":["Sau 1945, hệ thống xã hội chủ nghĩa thế giới hình thành.","1991: Liên Xô tan rã.","Trung Quốc, Việt Nam, Lào, Cu-ba tiếp tục cải cách, đổi mới."],"hoi":["Chủ nghĩa xã hội được mở rộng như thế nào sau năm 1945?","Nêu thành tựu cải cách, đổi mới của một nước xã hội chủ nghĩa hiện nay."]},{"so":5,"chuong":"Chủ đề 3. Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á","ten":"Quá trình xâm lược và cai trị của chủ nghĩa thực dân ở Đông Nam Á","trang":[29,36],"nam":null,"tom":"Các nước thực dân phương Tây xâm lược, cai trị Đông Nam Á và hậu quả.","muc":[["1. Quá trình xâm lược của thực dân phương Tây",["Từ thế kỉ XVI, các nước Bồ Đào Nha, Tây Ban Nha, Hà Lan, Anh, Pháp, Mỹ lần lượt xâm nhập Đông Nam Á.","Đến cuối thế kỉ XIX, hầu hết các nước Đông Nam Á hải đảo và lục địa trở thành thuộc địa; riêng Xiêm giữ được độc lập tương đối."]],["2. Chính sách cai trị của thực dân",["Chính trị: chia để trị, sử dụng tầng lớp phong kiến bản xứ làm tay sai.","Kinh tế: khai thác tài nguyên, bóc lột nhân công, biến thuộc địa thành thị trường tiêu thụ hàng hoá.","Văn hoá – xã hội: chính sách ngu dân; xã hội phân hoá, xuất hiện các giai cấp mới."]]],"nho":["Từ thế kỉ XVI, thực dân phương Tây xâm nhập Đông Nam Á.","Cuối thế kỉ XIX, hầu hết Đông Nam Á là thuộc địa, trừ Xiêm."],"hoi":["Trình bày quá trình xâm lược Đông Nam Á của thực dân phương Tây.","Vì sao Xiêm giữ được độc lập tương đối?","Nêu hậu quả của chính sách cai trị thực dân."]},{"so":6,"chuong":"Chủ đề 3. Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á","ten":"Hành trình đi đến độc lập dân tộc ở Đông Nam Á","trang":[37,42],"nam":null,"tom":"Phong trào đấu tranh giành độc lập của các dân tộc Đông Nam Á đến khi thắng lợi.","muc":[["1. Phong trào đấu tranh giành độc lập",["Cuối thế kỉ XIX – đầu thế kỉ XX, phong trào chống thực dân diễn ra ở In-đô-nê-xi-a, Phi-líp-pin, Mi-an-ma, Việt Nam, Lào, Cam-pu-chia…","Từ những năm 20 của thế kỉ XX, phong trào theo khuynh hướng vô sản phát triển song song với khuynh hướng tư sản."]],["2. Quá trình giành độc lập",["Năm 1945, nhiều nước nổi dậy giành độc lập: In-đô-nê-xi-a (8/1945), Việt Nam (9/1945), Lào (10/1945).","Sau đó các nước tiếp tục kháng chiến chống quay lại xâm lược; đến những năm 70 – 80, các nước Đông Nam Á lần lượt hoàn thành giải phóng dân tộc, Bru-nây độc lập năm 1984, Đông Ti-mo năm 2002."]]],"nho":["1945: nhiều nước Đông Nam Á giành độc lập.","Bru-nây (1984), Đông Ti-mo (2002) là những nước giành độc lập muộn nhất."],"hoi":["Nêu nét chính phong trào đấu tranh giành độc lập ở Đông Nam Á.","Trình bày quá trình giành độc lập của các nước Đông Nam Á."]},{"so":7,"chuong":"Chủ đề 4. Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)","ten":"Khái quát về chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam","trang":[43,49],"nam":null,"tom":"Vị trí, ý nghĩa và các cuộc kháng chiến bảo vệ Tổ quốc tiêu biểu, nguyên nhân thắng lợi, thất bại.","muc":[["1. Vị trí chiến lược của Việt Nam",["Nằm ở trung tâm Đông Nam Á, nơi giao thoa đường biển, đường bộ quan trọng nên thường xuyên bị các thế lực ngoại xâm nhòm ngó."]],["2. Một số cuộc kháng chiến tiêu biểu",["Kháng chiến chống Tống thời Tiền Lê (981) và thời Lý (1075 – 1077) với phòng tuyến sông Như Nguyệt.","Ba lần kháng chiến chống Mông – Nguyên thời Trần (thế kỉ XIII), chiến thắng Bạch Đằng 1288.","Kháng chiến chống quân Xiêm (1785) với trận Rạch Gầm – Xoài Mút, chống quân Thanh (1789) với trận Ngọc Hồi – Đống Đa của Tây Sơn.","Một số cuộc kháng chiến không thành công: chống Triệu (thế kỉ II TCN), thời Hồ chống Minh (1406 – 1407), triều Nguyễn chống Pháp (1858 – 1884)."]],["3. Nguyên nhân thắng lợi và bài học",["Truyền thống yêu nước, tinh thần đoàn kết toàn dân; đường lối, nghệ thuật quân sự đúng đắn, sáng tạo; vai trò của các vị tướng tài.","Bài học: xây dựng khối đại đoàn kết, “lấy dân làm gốc”, kết hợp sức mạnh dân tộc và thời đại."]]],"nho":["1077: phòng tuyến Như Nguyệt.","1288: chiến thắng Bạch Đằng.","1785: Rạch Gầm – Xoài Mút; 1789: Ngọc Hồi – Đống Đa."],"hoi":["Vì sao Việt Nam thường xuyên phải tiến hành chiến tranh bảo vệ Tổ quốc?","Nêu nguyên nhân thắng lợi của các cuộc kháng chiến.","Nguyên nhân thất bại của kháng chiến thời Hồ là gì?"],"sa_ban":{"ten":"Sa bàn 3D Như Nguyệt 1077","url":"khong-gian/engine/2.1.0/sa-ban.html?goi=nhu-nguyet-1077"}},{"so":8,"chuong":"Chủ đề 4. Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)","ten":"Một số cuộc khởi nghĩa và chiến tranh giải phóng trong lịch sử Việt Nam (từ thế kỉ III trước Công nguyên đến cuối thế kỉ XIX)","trang":[50,59],"nam":null,"tom":"Các cuộc khởi nghĩa thời Bắc thuộc, khởi nghĩa Lam Sơn, phong trào Tây Sơn: diễn biến và bài học.","muc":[["1. Khởi nghĩa và chiến tranh giải phóng thời Bắc thuộc",["Khởi nghĩa Hai Bà Trưng (40), Bà Triệu (248), Lý Bí (542) lập nước Vạn Xuân, Mai Thúc Loan, Phùng Hưng…","Năm 938, Ngô Quyền đánh tan quân Nam Hán trên sông Bạch Đằng, chấm dứt thời Bắc thuộc."]],["2. Khởi nghĩa Lam Sơn (1418 – 1427)",["Lê Lợi lãnh đạo, Nguyễn Trãi bày mưu; từ căn cứ Lam Sơn tiến vào Nghệ An rồi ra Bắc.","Chiến thắng Tốt Động – Chúc Động, Chi Lăng – Xương Giang buộc quân Minh rút về nước; Bình Ngô đại cáo ra đời."]],["3. Phong trào Tây Sơn",["Năm 1771, khởi nghĩa Tây Sơn bùng nổ; lật đổ chúa Nguyễn, chúa Trịnh, xoá bỏ ranh giới chia cắt đất nước.","Đánh tan quân Xiêm (1785), quân Thanh (1789), bảo vệ độc lập dân tộc."]],["4. Ý nghĩa và bài học",["Giành lại và bảo vệ nền độc lập, khẳng định ý chí tự chủ của dân tộc.","Bài học: dựa vào dân, đoàn kết toàn dân, biết chọn thời cơ và nghệ thuật quân sự sáng tạo."]]],"nho":["938: chiến thắng Bạch Đằng, chấm dứt Bắc thuộc.","1418 – 1427: khởi nghĩa Lam Sơn.","1771: khởi nghĩa Tây Sơn bùng nổ."],"hoi":["Kể tên các cuộc khởi nghĩa tiêu biểu thời Bắc thuộc.","Nêu nguyên nhân thắng lợi của khởi nghĩa Lam Sơn.","Phong trào Tây Sơn có những đóng góp gì cho lịch sử dân tộc?"],"sa_ban":{"ten":"Sa bàn 3D Bạch Đằng 938","url":"khong-gian/engine/2.0.0/sa-ban.html?goi=bach-dang-938"}},{"so":9,"chuong":"Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858)","ten":"Cuộc cải cách của Hồ Quý Ly và triều Hồ","trang":[60,63],"nam":1400,"tom":"Bối cảnh, nội dung, kết quả và ý nghĩa của cải cách Hồ Quý Ly cuối thế kỉ XIV – đầu thế kỉ XV.","muc":[["1. Bối cảnh",["Cuối thế kỉ XIV, nhà Trần suy yếu, kinh tế, xã hội khủng hoảng; nguy cơ ngoại xâm từ phương Bắc.","Hồ Quý Ly nắm quyền, năm 1400 lập nhà Hồ, đặt quốc hiệu Đại Ngu."]],["2. Nội dung cải cách",["Chính trị: cải tổ bộ máy, hạn chế quyền lực quý tộc Trần, dời đô vào Tây Đô (Thanh Hoá).","Kinh tế: phát hành tiền giấy, ban hành phép hạn điền, hạn nô; thống nhất đơn vị đo lường.","Văn hoá – giáo dục: đề cao chữ Nôm, cải cách thi cử; quân sự: tăng cường quân đội, xây dựng phòng tuyến."]],["3. Ý nghĩa và hạn chế",["Góp phần củng cố chế độ quân chủ trung ương tập quyền, thể hiện tinh thần dám đổi mới.","Hạn chế: chưa giải quyết được yêu cầu của nhân dân, chưa tạo được sự đồng thuận, nên kháng chiến chống Minh thất bại."]]],"nho":["1400: nhà Hồ thành lập, quốc hiệu Đại Ngu.","Phát hành tiền giấy, phép hạn điền, hạn nô.","Cải cách chưa tạo được sự đồng thuận của nhân dân."],"hoi":["Trình bày bối cảnh cuộc cải cách Hồ Quý Ly.","Nêu nội dung chính của cải cách.","Rút ra bài học từ cuộc cải cách của Hồ Quý Ly."]},{"so":10,"chuong":"Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858)","ten":"Cuộc cải cách của Lê Thánh Tông (thế kỉ XV)","trang":[64,68],"nam":1460,"tom":"Bối cảnh, nội dung và kết quả cải cách hành chính, luật pháp của vua Lê Thánh Tông.","muc":[["1. Bối cảnh",["Sau khi nhà Lê sơ thành lập, bộ máy nhà nước còn nhiều hạn chế, quyền lực của các đại thần lớn.","Năm 1460, Lê Thánh Tông lên ngôi, tiến hành cải cách toàn diện."]],["2. Nội dung cải cách",["Hành chính: chia cả nước thành 13 đạo thừa tuyên; tổ chức lại bộ máy trung ương với 6 bộ, các cơ quan giám sát.","Quan lại: tuyển chọn chủ yếu qua thi cử; quy định chặt chẽ về khảo khoá.","Luật pháp: ban hành Quốc triều hình luật (luật Hồng Đức) với nhiều điểm tiến bộ, bảo vệ quyền lợi của phụ nữ.","Quân đội, kinh tế, giáo dục: tổ chức lại quân đội; chế độ quân điền; đề cao Nho giáo, phát triển giáo dục khoa cử."]],["3. Kết quả và ý nghĩa",["Bộ máy nhà nước quân chủ trung ương tập quyền đạt đến đỉnh cao, Đại Việt phát triển cường thịnh.","Để lại nhiều kinh nghiệm về xây dựng bộ máy nhà nước và pháp luật."]]],"nho":["1460: Lê Thánh Tông lên ngôi.","13 đạo thừa tuyên; luật Hồng Đức.","Đại Việt phát triển cường thịnh thế kỉ XV."],"hoi":["Trình bày nội dung cải cách hành chính của Lê Thánh Tông.","Luật Hồng Đức có những điểm tiến bộ nào?","Cải cách Lê Thánh Tông có ý nghĩa gì?"]},{"so":11,"chuong":"Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858)","ten":"Cuộc cải cách của Minh Mạng (nửa đầu thế kỉ XIX)","trang":[69,72],"nam":1831,"tom":"Cải cách hành chính của vua Minh Mạng: lập 30 tỉnh và phủ Thừa Thiên, củng cố quyền lực trung ương.","muc":[["1. Bối cảnh",["Đầu thế kỉ XIX, bộ máy nhà nước thời Gia Long còn phân quyền, đặc biệt ở Bắc Thành và Gia Định Thành.","Năm 1820, Minh Mạng lên ngôi, tiến hành cải cách."]],["2. Nội dung cải cách",["Trung ương: thành lập Văn thư phòng (sau là Nội các), Cơ mật viện; hoàn thiện 6 bộ.","Địa phương: những năm 1831 – 1832, xoá bỏ Bắc Thành, Gia Định Thành, chia cả nước thành 30 tỉnh và phủ Thừa Thiên.","Quân sự, văn hoá, giáo dục: tổ chức quân đội theo hướng thống nhất, chính quy; coi trọng Nho giáo và khoa cử."]],["3. Ý nghĩa",["Hoàn thiện bộ máy nhà nước quân chủ trung ương tập quyền; thống nhất về hành chính trên cả nước.","Hệ thống tỉnh cơ bản được duy trì lâu dài về sau."]]],"nho":["1820: Minh Mạng lên ngôi.","1831 – 1832: chia cả nước thành 30 tỉnh và phủ Thừa Thiên.","Cải cách thống nhất hành chính trên cả nước."],"hoi":["Nêu bối cảnh cuộc cải cách Minh Mạng.","Trình bày cải cách hành chính địa phương của Minh Mạng.","Cải cách có ý nghĩa gì đối với đất nước?"]},{"so":12,"chuong":"Chủ đề 6. Lịch sử bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","ten":"Vị trí và tầm quan trọng của Biển Đông","trang":[73,79],"nam":null,"tom":"Vị trí địa lí, tầm quan trọng chiến lược và tài nguyên của Biển Đông, các quần đảo Hoàng Sa, Trường Sa.","muc":[["1. Vị trí và tầm quan trọng của Biển Đông",["Biển Đông là biển nửa kín, rộng khoảng 3,5 triệu km², nằm trên tuyến hàng hải quốc tế giữa Thái Bình Dương và Ấn Độ Dương.","Có nhiều đảo, quần đảo, eo biển quan trọng; tài nguyên phong phú: dầu khí, hải sản, khoáng sản."]],["2. Tầm quan trọng chiến lược",["Là tuyến giao thông biển huyết mạch của khu vực và thế giới.","Có vị trí quan trọng về an ninh, quốc phòng đối với các nước ven biển, trong đó có Việt Nam."]]],"nho":["Biển Đông nằm trên tuyến hàng hải quốc tế quan trọng.","Tài nguyên phong phú, đặc biệt là dầu khí và hải sản."],"hoi":["Nêu vị trí và đặc điểm của Biển Đông.","Vì sao Biển Đông có tầm quan trọng chiến lược?"]},{"so":13,"chuong":"Chủ đề 6. Lịch sử bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","ten":"Việt Nam và Biển Đông","trang":[80,90],"nam":null,"tom":"Quá trình Việt Nam xác lập, thực thi chủ quyền và đấu tranh bảo vệ chủ quyền ở Biển Đông.","muc":[["1. Vị trí của Biển Đông với Việt Nam",["Việt Nam có đường bờ biển dài hơn 3 260 km; vùng biển Việt Nam có nhiều đảo, trong đó có hai quần đảo Hoàng Sa và Trường Sa.","Biển Đông có vai trò quan trọng đối với kinh tế, quốc phòng, an ninh của Việt Nam."]],["2. Quá trình xác lập và thực thi chủ quyền",["Từ thế kỉ XVII, chúa Nguyễn lập đội Hoàng Sa, Bắc Hải khai thác và quản lí các quần đảo.","Thời Nguyễn tiếp tục thực thi chủ quyền: cắm mốc, dựng bia, vẽ bản đồ; thời Pháp thuộc, chính quyền thuộc địa thay mặt Việt Nam quản lí.","Hiện nay, Việt Nam khẳng định chủ quyền qua Luật Biển Việt Nam (2012), tuân thủ Công ước Liên hợp quốc về Luật Biển năm 1982."]],["3. Chủ trương giải quyết tranh chấp",["Giải quyết các tranh chấp bằng biện pháp hoà bình trên cơ sở luật pháp quốc tế.","Thúc đẩy thực hiện Tuyên bố về ứng xử của các bên ở Biển Đông (DOC) và đàm phán Bộ quy tắc ứng xử (COC)."]]],"nho":["Đội Hoàng Sa, Bắc Hải từ thế kỉ XVII.","Luật Biển Việt Nam 2012; Công ước Luật Biển 1982.","Giải quyết tranh chấp bằng biện pháp hoà bình."],"hoi":["Trình bày quá trình xác lập, thực thi chủ quyền của Việt Nam ở Hoàng Sa, Trường Sa.","Nêu chủ trương của Việt Nam trong giải quyết tranh chấp ở Biển Đông.","Em có thể làm gì để góp phần bảo vệ chủ quyền biển đảo?"]}]},"12":{"sach":"Lịch sử 12 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), tr. 6–109","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chủ đề 1. Thế giới trong và sau Chiến tranh lạnh","ten":"Liên hợp quốc","trang":[6,12],"nam":1945,"tom":"Bối cảnh ra đời, mục tiêu, nguyên tắc hoạt động và vai trò của Liên hợp quốc.","muc":[["1. Sự thành lập Liên hợp quốc",["Hội nghị I-an-ta (2/1945) quyết định thành lập tổ chức quốc tế mới; Hội nghị Xan Phran-xi-xcô (4 – 6/1945) thông qua Hiến chương.","Ngày 24/10/1945, Hiến chương có hiệu lực, Liên hợp quốc chính thức ra đời."]],["2. Mục tiêu, nguyên tắc và cơ cấu",["Mục tiêu: duy trì hoà bình, an ninh quốc tế; phát triển quan hệ hữu nghị, hợp tác giữa các quốc gia.","Nguyên tắc: bình đẳng chủ quyền, không can thiệp vào công việc nội bộ, giải quyết tranh chấp bằng biện pháp hoà bình; nguyên tắc nhất trí giữa 5 nước uỷ viên thường trực Hội đồng Bảo an (Liên Xô – nay là Nga, Mỹ, Anh, Pháp, Trung Quốc).","Cơ quan chính: Đại hội đồng, Hội đồng Bảo an, Hội đồng Kinh tế – Xã hội, Toà án Quốc tế, Ban Thư kí…"]],["3. Vai trò của Liên hợp quốc",["Duy trì hoà bình, giải quyết xung đột; thúc đẩy phát triển kinh tế, văn hoá, giáo dục, y tế; bảo vệ quyền con người, môi trường.","Việt Nam gia nhập Liên hợp quốc năm 1977, hai lần là Uỷ viên không thường trực Hội đồng Bảo an (2008 – 2009, 2020 – 2021)."]]],"nho":["24/10/1945: Liên hợp quốc ra đời.","5 uỷ viên thường trực Hội đồng Bảo an.","1977: Việt Nam gia nhập Liên hợp quốc."],"hoi":["Trình bày sự thành lập của Liên hợp quốc.","Nêu mục tiêu và nguyên tắc hoạt động của Liên hợp quốc.","Việt Nam đã đóng góp gì trong Liên hợp quốc?"]},{"so":2,"chuong":"Chủ đề 1. Thế giới trong và sau Chiến tranh lạnh","ten":"Trật tự thế giới trong Chiến tranh lạnh","trang":[13,17],"nam":1945,"tom":"Trật tự hai cực I-an-ta hình thành, tồn tại và sụp đổ.","muc":[["1. Sự hình thành trật tự thế giới hai cực I-an-ta",["Hội nghị I-an-ta (2/1945) của Liên Xô, Mỹ, Anh phân chia khu vực ảnh hưởng sau chiến tranh.","Thế giới hình thành hai cực do Liên Xô và Mỹ đứng đầu."]],["2. Trật tự hai cực trong Chiến tranh lạnh",["Hai phe đối đầu gay gắt về chính trị, kinh tế, quân sự; chạy đua vũ trang, lập các khối quân sự.","Xảy ra nhiều cuộc chiến tranh cục bộ, khủng hoảng quốc tế."]],["3. Sự sụp đổ",["Liên Xô và Mỹ đều suy giảm vị thế; năm 1989 tuyên bố chấm dứt Chiến tranh lạnh.","Năm 1991, Liên Xô tan rã, trật tự hai cực I-an-ta sụp đổ."]]],"nho":["2/1945: Hội nghị I-an-ta.","Trật tự hai cực do Liên Xô và Mỹ đứng đầu.","1991: trật tự hai cực sụp đổ."],"hoi":["Hội nghị I-an-ta có vai trò gì trong việc hình thành trật tự hai cực?","Vì sao trật tự hai cực sụp đổ?"]},{"so":3,"chuong":"Chủ đề 1. Thế giới trong và sau Chiến tranh lạnh","ten":"Trật tự thế giới sau Chiến tranh lạnh","trang":[18,20],"nam":1991,"tom":"Xu thế phát triển của thế giới sau Chiến tranh lạnh, hướng tới trật tự đa cực.","muc":[["1. Trật tự thế giới sau Chiến tranh lạnh",["Thế giới chuyển dần sang trật tự đa cực, với sự vươn lên của Mỹ, Liên minh châu Âu, Trung Quốc, Nhật Bản, Nga, Ấn Độ…","Mỹ muốn duy trì trật tự đơn cực nhưng không thực hiện được."]],["2. Xu thế phát triển chính của thế giới",["Hoà bình, hợp tác và phát triển; các nước lấy phát triển kinh tế làm trọng tâm.","Toàn cầu hoá, liên kết khu vực phát triển mạnh; vai trò của các cường quốc tầm trung và tổ chức khu vực tăng lên.","Nhưng vẫn còn xung đột, khủng bố, cạnh tranh chiến lược giữa các nước lớn."]]],"nho":["Sau Chiến tranh lạnh, thế giới chuyển sang đa cực.","Xu thế chính: hoà bình, hợp tác, phát triển."],"hoi":["Nêu những xu thế chính của thế giới sau Chiến tranh lạnh.","Việt Nam cần làm gì trước các xu thế đó?"]},{"so":4,"chuong":"Chủ đề 2. ASEAN: những chặng đường lịch sử","ten":"Sự ra đời và phát triển của Hiệp hội các quốc gia Đông Nam Á (ASEAN)","trang":[21,24],"nam":1967,"tom":"ASEAN thành lập năm 1967 và mở rộng thành tổ chức của cả khu vực.","muc":[["1. Sự ra đời của ASEAN",["Ngày 8/8/1967, tại Băng Cốc, 5 nước In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po, Thái Lan thành lập Hiệp hội các quốc gia Đông Nam Á (ASEAN).","Mục tiêu: hợp tác phát triển kinh tế, văn hoá, duy trì hoà bình, ổn định khu vực."]],["2. Quá trình phát triển",["Năm 1976, Hiệp ước Thân thiện và Hợp tác ở Đông Nam Á (Hiệp ước Ba-li) được kí, xác định nguyên tắc quan hệ.","ASEAN mở rộng: Bru-nây (1984), Việt Nam (1995), Lào và Mi-an-ma (1997), Cam-pu-chia (1999).","Năm 2007, Hiến chương ASEAN được thông qua; Đông Ti-mo được kết nạp năm 2025."]]],"nho":["8/8/1967: ASEAN thành lập.","1976: Hiệp ước Ba-li.","1995: Việt Nam gia nhập ASEAN."],"hoi":["Trình bày sự ra đời và mục tiêu của ASEAN.","Nêu các giai đoạn phát triển của ASEAN.","Việt Nam gia nhập ASEAN có ý nghĩa gì?"]},{"so":5,"chuong":"Chủ đề 2. ASEAN: những chặng đường lịch sử","ten":"Cộng đồng ASEAN: Từ ý tưởng đến hiện thực","trang":[25,30],"nam":2015,"tom":"Ý tưởng, mục tiêu và ba trụ cột của Cộng đồng ASEAN chính thức thành lập năm 2015.","muc":[["1. Ý tưởng và quá trình xây dựng Cộng đồng ASEAN",["Tầm nhìn ASEAN 2020 (1997) đề ra ý tưởng xây dựng cộng đồng; Tuyên bố Ba-li II (2003) xác định ba trụ cột.","Ngày 31/12/2015, Cộng đồng ASEAN chính thức được thành lập."]],["2. Ba trụ cột",["Cộng đồng Chính trị – An ninh (APSC), Cộng đồng Kinh tế (AEC), Cộng đồng Văn hoá – Xã hội (ASCC).","Tầm nhìn Cộng đồng ASEAN đến năm 2025 và tiếp theo được thông qua để tiếp tục phát triển."]],["3. Thời cơ, thách thức và Việt Nam",["Thời cơ: thị trường lớn, thu hút đầu tư, nâng cao vị thế khu vực.","Thách thức: chênh lệch trình độ phát triển, bất đồng về một số vấn đề như Biển Đông.","Việt Nam tích cực đóng góp, từng giữ vai trò Chủ tịch ASEAN (1998, 2010, 2020)."]]],"nho":["31/12/2015: Cộng đồng ASEAN thành lập.","Ba trụ cột: Chính trị – An ninh, Kinh tế, Văn hoá – Xã hội."],"hoi":["Nêu quá trình hình thành Cộng đồng ASEAN.","Trình bày ba trụ cột của Cộng đồng ASEAN.","Việt Nam có vai trò gì trong Cộng đồng ASEAN?"]},{"so":6,"chuong":"Chủ đề 3. Cách mạng tháng Tám năm 1945, chiến tranh giải phóng dân tộc và chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam (từ tháng 8 năm 1945 đến nay)","ten":"Cách mạng tháng Tám năm 1945","trang":[31,36],"nam":1945,"tom":"Bối cảnh, diễn biến, nguyên nhân thắng lợi và ý nghĩa của Cách mạng tháng Tám năm 1945.","muc":[["1. Thời cơ và diễn biến",["Tháng 8/1945, Nhật đầu hàng Đồng minh, kẻ thù chính của nhân dân ta suy sụp; đây là thời cơ “ngàn năm có một”.","Hội nghị toàn quốc của Đảng (13 – 15/8) và Quốc dân Đại hội Tân Trào (16/8) quyết định Tổng khởi nghĩa.","Từ 14 đến 28/8/1945, Tổng khởi nghĩa thắng lợi trong cả nước; ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập."]],["2. Nguyên nhân thắng lợi",["Khách quan: Hồng quân Liên Xô và Đồng minh đánh bại phát xít.","Chủ quan: truyền thống yêu nước; sự lãnh đạo của Đảng và Chủ tịch Hồ Chí Minh; quá trình chuẩn bị lâu dài qua các cao trào 1930 – 1931, 1936 – 1939, 1939 – 1945; khối đoàn kết trong Mặt trận Việt Minh."]],["3. Ý nghĩa và bài học",["Lật đổ ách thống trị thực dân, phát xít và chế độ phong kiến; mở ra kỉ nguyên độc lập, tự do.","Bài học: kết hợp nhiệm vụ dân tộc và dân chủ; xây dựng khối đoàn kết toàn dân; nắm vững thời cơ."]]],"nho":["14 – 28/8/1945: Tổng khởi nghĩa thắng lợi cả nước.","2/9/1945: nước Việt Nam Dân chủ Cộng hoà ra đời.","Bài học về chớp thời cơ."],"hoi":["Phân tích thời cơ của Cách mạng tháng Tám năm 1945.","Nêu nguyên nhân thắng lợi của Cách mạng tháng Tám.","Rút ra bài học kinh nghiệm từ Cách mạng tháng Tám."]},{"so":7,"chuong":"Chủ đề 3. Cách mạng tháng Tám năm 1945, chiến tranh giải phóng dân tộc và chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam (từ tháng 8 năm 1945 đến nay)","ten":"Cuộc kháng chiến chống thực dân Pháp (1945 – 1954)","trang":[37,44],"nam":1946,"tom":"Các giai đoạn, thắng lợi tiêu biểu và ý nghĩa của cuộc kháng chiến chống Pháp.","muc":[["1. Khái quát cuộc kháng chiến (1945 – 1954)",["Kháng chiến bùng nổ ở Nam Bộ (23/9/1945), lan ra toàn quốc (19/12/1946) theo đường lối toàn dân, toàn diện, trường kì, tự lực cánh sinh.","Những thắng lợi lớn: Việt Bắc (1947), Biên giới (1950), Đông – Xuân 1953 – 1954 và Điện Biên Phủ (1954).","Hiệp định Giơ-ne-vơ (21/7/1954) kết thúc chiến tranh, miền Bắc được giải phóng."]],["2. Nguyên nhân thắng lợi",["Sự lãnh đạo của Đảng với đường lối kháng chiến đúng đắn; tinh thần đoàn kết, hi sinh của toàn dân; hậu phương vững chắc.","Liên minh chiến đấu Việt Nam – Lào – Cam-pu-chia; sự ủng hộ của các nước xã hội chủ nghĩa và nhân dân tiến bộ thế giới."]],["3. Ý nghĩa lịch sử",["Chấm dứt ách thống trị của thực dân Pháp; giáng đòn nặng nề vào chủ nghĩa thực dân cũ.","Cổ vũ mạnh mẽ phong trào giải phóng dân tộc ở châu Á, châu Phi, Mỹ La-tinh."]]],"nho":["19/12/1946: toàn quốc kháng chiến.","7/5/1954: chiến thắng Điện Biên Phủ.","21/7/1954: Hiệp định Giơ-ne-vơ."],"hoi":["Trình bày những thắng lợi tiêu biểu của cuộc kháng chiến chống Pháp.","Nêu nguyên nhân thắng lợi của cuộc kháng chiến.","Vì sao cuộc kháng chiến có ý nghĩa quốc tế to lớn?"],"sa_ban":{"ten":"Sa bàn 3D Điện Biên Phủ 1954","url":"khong-gian/dien-bien-phu/"}},{"so":8,"chuong":"Chủ đề 3. Cách mạng tháng Tám năm 1945, chiến tranh giải phóng dân tộc và chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam (từ tháng 8 năm 1945 đến nay)","ten":"Cuộc kháng chiến chống Mỹ, cứu nước (1954 – 1975)","trang":[45,53],"nam":1975,"tom":"Các giai đoạn, thắng lợi tiêu biểu và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước.","muc":[["1. Khái quát cuộc kháng chiến (1954 – 1975)",["Miền Nam đánh bại lần lượt các chiến lược chiến tranh của Mỹ: “Chiến tranh đơn phương” (1954 – 1960), “Chiến tranh đặc biệt” (1961 – 1965), “Chiến tranh cục bộ” (1965 – 1968), “Việt Nam hoá chiến tranh” (1969 – 1975).","Miền Bắc xây dựng chủ nghĩa xã hội, là hậu phương lớn, đồng thời đánh bại hai cuộc chiến tranh phá hoại bằng không quân của Mỹ.","Hiệp định Pa-ri (27/1/1973) buộc Mỹ rút quân; Tổng tiến công và nổi dậy Xuân 1975 giải phóng hoàn toàn miền Nam (30/4/1975)."]],["2. Nguyên nhân thắng lợi",["Sự lãnh đạo của Đảng với đường lối tiến hành đồng thời hai chiến lược cách mạng ở hai miền.","Tinh thần yêu nước, đoàn kết của nhân dân hai miền; hậu phương miền Bắc; sự ủng hộ của các nước xã hội chủ nghĩa và nhân dân yêu chuộng hoà bình thế giới."]],["3. Ý nghĩa lịch sử",["Kết thúc 21 năm chiến đấu chống Mỹ và 30 năm chiến tranh giải phóng dân tộc; thống nhất đất nước.","Mở ra kỉ nguyên cả nước độc lập, thống nhất, đi lên chủ nghĩa xã hội; cổ vũ phong trào cách mạng thế giới."]]],"nho":["Bốn chiến lược chiến tranh của Mỹ ở miền Nam đều thất bại.","27/1/1973: Hiệp định Pa-ri.","30/4/1975: miền Nam hoàn toàn giải phóng."],"hoi":["Trình bày các giai đoạn chính của cuộc kháng chiến chống Mỹ, cứu nước.","Hậu phương miền Bắc có vai trò như thế nào?","Nêu ý nghĩa lịch sử của cuộc kháng chiến chống Mỹ."],"sa_ban":{"ten":"Sa bàn 3D Thành cổ Quảng Trị 1972","url":"khong-gian/thanh-co-quang-tri/"}},{"so":9,"chuong":"Chủ đề 3. Cách mạng tháng Tám năm 1945, chiến tranh giải phóng dân tộc và chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam (từ tháng 8 năm 1945 đến nay)","ten":"Cuộc đấu tranh bảo vệ Tổ quốc từ sau tháng 4 – 1975 đến nay. Một số bài học lịch sử của các cuộc kháng chiến bảo vệ Tổ quốc từ năm 1945 đến nay","trang":[54,60],"nam":1979,"tom":"Bảo vệ biên giới Tây Nam, biên giới phía Bắc, chủ quyền biển đảo và các bài học lịch sử.","muc":[["1. Đấu tranh bảo vệ biên giới",["Quân dân ta chiến đấu bảo vệ biên giới Tây Nam (từ 1975 – 1979), đồng thời giúp nhân dân Cam-pu-chia thoát khỏi chế độ diệt chủng.","Chiến đấu bảo vệ biên giới phía Bắc (từ tháng 2/1979, kéo dài trong những năm 80)."]],["2. Đấu tranh bảo vệ chủ quyền biển đảo",["Bảo vệ chủ quyền ở quần đảo Trường Sa, tiêu biểu là cuộc chiến đấu ở Gạc Ma (3/1988).","Tiếp tục đấu tranh bằng biện pháp hoà bình theo luật pháp quốc tế để bảo vệ chủ quyền Hoàng Sa, Trường Sa."]],["3. Bài học lịch sử của các cuộc kháng chiến",["Giương cao ngọn cờ độc lập dân tộc và chủ nghĩa xã hội; xây dựng khối đại đoàn kết toàn dân.","Kết hợp sức mạnh dân tộc với sức mạnh thời đại; nghệ thuật quân sự sáng tạo, lấy nhỏ thắng lớn; xây dựng nền quốc phòng toàn dân."]]],"nho":["1975 – 1979: bảo vệ biên giới Tây Nam.","2/1979: bảo vệ biên giới phía Bắc.","3/1988: chiến đấu bảo vệ Gạc Ma."],"hoi":["Trình bày cuộc đấu tranh bảo vệ biên giới sau năm 1975.","Nêu những bài học lịch sử của các cuộc kháng chiến bảo vệ Tổ quốc.","Bài học nào vẫn còn giá trị đối với hiện nay?"]},{"so":10,"chuong":"Chủ đề 4. Công cuộc Đổi mới ở Việt Nam từ năm 1986 đến nay","ten":"Khái quát về công cuộc Đổi mới từ năm 1986 đến nay","trang":[61,64],"nam":1986,"tom":"Bối cảnh và các giai đoạn của công cuộc Đổi mới bắt đầu từ Đại hội VI (1986).","muc":[["1. Bối cảnh Đổi mới",["Sau năm 1975, đất nước gặp nhiều khó khăn; từ cuối những năm 70, kinh tế – xã hội khủng hoảng nghiêm trọng.","Trên thế giới, Liên Xô và các nước xã hội chủ nghĩa khủng hoảng, cải tổ; xu thế đối thoại, hợp tác phát triển."]],["2. Các giai đoạn của công cuộc Đổi mới",["1986 – 1995: Đại hội VI (12/1986) đề ra đường lối Đổi mới toàn diện; khắc phục khủng hoảng, bắt đầu hội nhập.","1996 – 2006: đẩy mạnh công nghiệp hoá, hiện đại hoá.","2006 đến nay: tiếp tục hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa, hội nhập quốc tế sâu rộng."]]],"nho":["12/1986: Đại hội VI khởi xướng Đổi mới.","Đổi mới toàn diện, trọng tâm là kinh tế."],"hoi":["Vì sao Việt Nam phải tiến hành Đổi mới?","Trình bày các giai đoạn chính của công cuộc Đổi mới."]},{"so":11,"chuong":"Chủ đề 4. Công cuộc Đổi mới ở Việt Nam từ năm 1986 đến nay","ten":"Thành tựu cơ bản và bài học của công cuộc Đổi mới ở Việt Nam từ năm 1986 đến nay","trang":[65,72],"nam":null,"tom":"Thành tựu về kinh tế, chính trị, xã hội, đối ngoại và các bài học kinh nghiệm.","muc":[["1. Thành tựu",["Kinh tế: thoát khỏi khủng hoảng, tăng trưởng nhanh; từ nước thiếu lương thực trở thành nước xuất khẩu gạo hàng đầu; cuối thập niên 2000 ra khỏi nhóm nước thu nhập thấp.","Chính trị: hệ thống chính trị ổn định; xây dựng Nhà nước pháp quyền xã hội chủ nghĩa.","Xã hội, văn hoá: giảm nghèo nhanh, đời sống nhân dân nâng cao; giáo dục, y tế phát triển.","Hội nhập quốc tế: quan hệ ngoại giao với hầu hết các nước; gia nhập ASEAN (1995), APEC (1998), WTO (2007)."]],["2. Bài học kinh nghiệm",["Kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội; đổi mới toàn diện, đồng bộ, có bước đi phù hợp.","Lấy dân làm gốc; kết hợp sức mạnh dân tộc với sức mạnh thời đại."]]],"nho":["Xuất khẩu gạo hàng đầu thế giới.","1995 ASEAN, 1998 APEC, 2007 WTO.","Bài học: lấy dân làm gốc."],"hoi":["Nêu những thành tựu cơ bản của công cuộc Đổi mới.","Trình bày bài học kinh nghiệm của công cuộc Đổi mới.","Em thấy thành tựu Đổi mới qua những thay đổi nào ở địa phương?"]},{"so":12,"chuong":"Chủ đề 5. Lịch sử đối ngoại của Việt Nam thời cận – hiện đại","ten":"Hoạt động đối ngoại của Việt Nam trong đấu tranh giành độc lập dân tộc (từ đầu thế kỉ XX đến trước Cách mạng tháng Tám năm 1945)","trang":[73,76],"nam":null,"tom":"Hoạt động đối ngoại của Phan Bội Châu, Phan Châu Trinh, Nguyễn Ái Quốc và Đảng Cộng sản.","muc":[["1. Hoạt động đối ngoại đầu thế kỉ XX đến năm 1930",["Phan Bội Châu với phong trào Đông du (1905 – 1909) dựa vào Nhật Bản; Phan Châu Trinh hoạt động ở Pháp.","Nguyễn Ái Quốc gửi Bản yêu sách đến Hội nghị Véc-xai (1919), hoạt động trong Đảng Cộng sản Pháp, Quốc tế Cộng sản, gắn cách mạng Việt Nam với cách mạng thế giới."]],["2. Hoạt động đối ngoại 1930 – 1945",["Đảng Cộng sản Đông Dương được Quốc tế Cộng sản công nhận là phân bộ độc lập (1931); tham gia mặt trận chống phát xít.","Nguyễn Ái Quốc tranh thủ sự giúp đỡ của các lực lượng Đồng minh chống Nhật."]]],"nho":["1905 – 1909: phong trào Đông du.","1919: Bản yêu sách của nhân dân An Nam."],"hoi":["Nêu những hoạt động đối ngoại tiêu biểu đầu thế kỉ XX.","Hoạt động đối ngoại của Nguyễn Ái Quốc có ý nghĩa gì?"]},{"so":13,"chuong":"Chủ đề 5. Lịch sử đối ngoại của Việt Nam thời cận – hiện đại","ten":"Hoạt động đối ngoại của Việt Nam trong kháng chiến chống Pháp (1945 – 1954) và kháng chiến chống Mỹ (1954 – 1975)","trang":[77,81],"nam":null,"tom":"Ngoại giao phục vụ kháng chiến: Hiệp định Sơ bộ, Giơ-ne-vơ, Pa-ri.","muc":[["1. Đối ngoại 1945 – 1954",["1945 – 1946: hoà hoãn với quân Trung Hoa Dân quốc, kí Hiệp định Sơ bộ (6/3/1946), Tạm ước (14/9/1946) với Pháp.","Năm 1950, Trung Quốc, Liên Xô và các nước xã hội chủ nghĩa công nhận, đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hoà.","Hội nghị Giơ-ne-vơ (1954) kết thúc chiến tranh ở Đông Dương."]],["2. Đối ngoại 1954 – 1975",["Tranh thủ sự ủng hộ của các nước xã hội chủ nghĩa và nhân dân tiến bộ, kể cả nhân dân Mỹ.","Hội nghị Pa-ri (1968 – 1973) là cuộc đấu tranh ngoại giao dài nhất, kết thúc bằng Hiệp định Pa-ri (27/1/1973)."]]],"nho":["6/3/1946: Hiệp định Sơ bộ.","1950: các nước xã hội chủ nghĩa công nhận Việt Nam.","27/1/1973: Hiệp định Pa-ri."],"hoi":["Trình bày hoạt động đối ngoại của Việt Nam 1945 – 1946.","Hội nghị Pa-ri có ý nghĩa gì về mặt đối ngoại?"]},{"so":14,"chuong":"Chủ đề 5. Lịch sử đối ngoại của Việt Nam thời cận – hiện đại","ten":"Hoạt động đối ngoại của Việt Nam từ năm 1975 đến nay","trang":[82,87],"nam":1995,"tom":"Phá thế bao vây cấm vận, bình thường hoá quan hệ, gia nhập ASEAN (1995) và hội nhập quốc tế.","muc":[["1. Đối ngoại 1975 – 1985",["Việt Nam gia nhập Liên hợp quốc (1977), mở rộng quan hệ với các nước; quan hệ với các nước xã hội chủ nghĩa được tăng cường.","Gặp khó khăn do bị bao vây, cấm vận."]],["2. Đối ngoại từ năm 1986 đến nay",["Đường lối đối ngoại độc lập, tự chủ, đa phương hoá, đa dạng hoá; Việt Nam muốn là bạn, là đối tác tin cậy của các nước.","Năm 1991 bình thường hoá quan hệ với Trung Quốc; năm 1995 bình thường hoá quan hệ với Mỹ và gia nhập ASEAN.","Gia nhập APEC (1998), WTO (2007); tham gia nhiều hiệp định thương mại tự do; tham gia lực lượng gìn giữ hoà bình Liên hợp quốc."]]],"nho":["1977: gia nhập Liên hợp quốc.","1995: bình thường hoá quan hệ với Mỹ, gia nhập ASEAN.","Đối ngoại độc lập, tự chủ, đa phương hoá, đa dạng hoá."],"hoi":["Nêu nét chính hoạt động đối ngoại của Việt Nam 1975 – 1985.","Trình bày những thành tựu đối ngoại từ năm 1986 đến nay."]},{"so":15,"chuong":"Chủ đề 6. Hồ Chí Minh trong lịch sử Việt Nam","ten":"Khái quát cuộc đời và sự nghiệp của Hồ Chí Minh","trang":[88,93],"nam":1890,"tom":"Những nét chính về cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh từ năm 1890 đến năm 1969.","muc":[["1. Quê hương, gia đình và thời niên thiếu",["Chủ tịch Hồ Chí Minh (Nguyễn Sinh Cung) sinh ngày 19/5/1890 tại Nghệ An, trong một gia đình nhà nho yêu nước.","Lớn lên khi đất nước bị thực dân Pháp đô hộ, Người sớm có lòng yêu nước, thương dân."]],["2. Hành trình tìm đường cứu nước (1911 – 1930)",["Ngày 5/6/1911, Người rời bến Nhà Rồng ra đi tìm đường cứu nước; qua nhiều nước châu Âu, châu Phi, châu Mỹ.","Năm 1920, tìm thấy con đường cứu nước theo chủ nghĩa Mác – Lê-nin; năm 1930, sáng lập Đảng Cộng sản Việt Nam."]],["3. Lãnh đạo cách mạng (1930 – 1969)",["Năm 1941, về nước trực tiếp lãnh đạo cách mạng; lãnh đạo Cách mạng tháng Tám, đọc Tuyên ngôn Độc lập (2/9/1945).","Lãnh đạo hai cuộc kháng chiến chống Pháp, chống Mỹ; Người qua đời ngày 2/9/1969, để lại bản Di chúc thiêng liêng."]]],"nho":["19/5/1890: Nguyễn Sinh Cung ra đời.","5/6/1911: ra đi tìm đường cứu nước.","2/9/1969: Chủ tịch Hồ Chí Minh qua đời."],"hoi":["Trình bày những nét chính về cuộc đời Chủ tịch Hồ Chí Minh.","Hành trình tìm đường cứu nước của Người có ý nghĩa gì?"]},{"so":16,"chuong":"Chủ đề 6. Hồ Chí Minh trong lịch sử Việt Nam","ten":"Hồ Chí Minh – Anh hùng giải phóng dân tộc","trang":[94,104],"nam":1930,"tom":"Vai trò của Hồ Chí Minh trong tìm đường cứu nước, thành lập Đảng, lãnh đạo cách mạng và kháng chiến.","muc":[["1. Tìm ra con đường cứu nước",["Người xác định con đường giải phóng dân tộc theo cách mạng vô sản, chấm dứt khủng hoảng đường lối cứu nước."]],["2. Chuẩn bị và lãnh đạo giành độc lập",["Sáng lập Đảng Cộng sản Việt Nam, Mặt trận Việt Minh, lực lượng vũ trang; chủ trì Hội nghị Trung ương 8 (1941).","Lãnh đạo Tổng khởi nghĩa tháng Tám, khai sinh nước Việt Nam Dân chủ Cộng hoà."]],["3. Lãnh đạo kháng chiến bảo vệ độc lập, thống nhất",["Đề ra đường lối kháng chiến chống Pháp, chống Mỹ; nêu chân lí “Không có gì quý hơn độc lập, tự do”.","Năm 1987, UNESCO tôn vinh Người là “Anh hùng giải phóng dân tộc, nhà văn hoá kiệt xuất”."]]],"nho":["Người tìm ra con đường cứu nước theo cách mạng vô sản.","“Không có gì quý hơn độc lập, tự do.”","1987: UNESCO tôn vinh Người."],"hoi":["Phân tích vai trò của Hồ Chí Minh trong Cách mạng tháng Tám.","Vì sao Hồ Chí Minh được tôn vinh là Anh hùng giải phóng dân tộc?"]},{"so":17,"chuong":"Chủ đề 6. Hồ Chí Minh trong lịch sử Việt Nam","ten":"Dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam","trang":[105,109],"nam":null,"tom":"Sự tôn vinh và lòng kính yêu của nhân dân Việt Nam, bạn bè quốc tế đối với Hồ Chí Minh.","muc":[["1. Giá trị tư tưởng, văn hoá",["Tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của cách mạng Việt Nam.","Người để lại nhiều tác phẩm văn học, báo chí có giá trị (Nhật kí trong tù, Tuyên ngôn Độc lập…)."]],["2. Dấu ấn trong lòng nhân dân và thế giới",["Hình ảnh và tên tuổi Người gắn với nhiều công trình, địa danh: Lăng Chủ tịch Hồ Chí Minh, Thành phố Hồ Chí Minh, các khu di tích Kim Liên, Pác Bó, Phủ Chủ tịch…","Nhiều nước trên thế giới dựng tượng đài, đặt tên đường, công viên mang tên Người."]],["3. Học tập và làm theo",["Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh: cần, kiệm, liêm, chính, chí công vô tư; giản dị, gần dân.","Thế hệ trẻ thực hiện Năm điều Bác Hồ dạy thiếu niên, nhi đồng; ra sức học tập, rèn luyện."]]],"nho":["Tư tưởng Hồ Chí Minh là kim chỉ nam của cách mạng Việt Nam.","Cần, kiệm, liêm, chính, chí công vô tư."],"hoi":["Nêu những dấu ấn của Hồ Chí Minh trong lòng dân tộc và thế giới.","Em học tập được gì từ tấm gương đạo đức Hồ Chí Minh?"]}]}}};
